        public partial class NetworkEngine : IDisposable
        {
            private readonly string _host;
    
    
            private readonly int _port;
    
    
            private readonly string _clientId;
    
    
            private TcpClient? _tcpClient;
    
    
            private NetworkStream? _stream;
    
    
            private CancellationTokenSource? _cts;
    
    
            private readonly CircuitBreaker _circuitBreaker;
    
    
            private readonly ExponentialBackoffWithJitter _backoff;
    
    
            private readonly ConcurrentQueue<TransportMessage> _sendQueue = new();
    
    
            private readonly ConcurrentQueue<TransportMessage> _receiveQueue = new();
    
    
            private readonly byte[] _readBuffer = new byte[65536];
    
    
            private Task? _readLoopTask;
    
    
            private Task? _sendLoopTask;
    
    
            private Task? _heartbeatTask;
    
    
            private volatile bool _isConnected;
    
    
            private volatile bool _disposed;
    
    
            private DateTime _lastHeartbeatUtc = DateTime.MinValue;
    
    
            private string? _sessionId;
    
    
            public bool IsConnected => _isConnected;
    
    
            public string? SessionId => _sessionId;
    
    
            public string ClientId => _clientId;
    
    
            public long BytesSent { get; private set; }
    
    
            public long BytesReceived { get; private set; }
    
    
            public NetworkEngine(string host, int port, string clientId)
            {
            _host = host;
            _port = port;
            _clientId = clientId;
            _circuitBreaker = new CircuitBreaker();
            _backoff = new ExponentialBackoffWithJitter();
            }
    
    
            public async Task<bool> ConnectAsync(CancellationToken ct = default)
            {
            if (_isConnected) return true;
            if (!_circuitBreaker.AllowRequest()) return false;
    
            try
            {
                _tcpClient = new TcpClient { NoDelay = true, ReceiveTimeout = 30000, SendTimeout = 30000 };
                await _tcpClient.ConnectAsync(_host, _port, ct).ConfigureAwait(false);
                _stream = _tcpClient.GetStream();
                _isConnected = true;
                _cts = CancellationTokenSource.CreateLinkedTokenSource(ct);
                _circuitBreaker.RecordSuccess();
                _backoff.Reset();
    
                // Start IO loops
                _readLoopTask = ReadLoopAsync(_cts.Token);
                _sendLoopTask = SendLoopAsync(_cts.Token);
                _heartbeatTask = HeartbeatLoopAsync(_cts.Token);
    
                // Perform handshake
                await SendHandshakeAsync(_cts.Token).ConfigureAwait(false);
                OnConnected?.Invoke();
                Log("Connected successfully.");
                return true;
            }
            catch (Exception ex)
            {
                _circuitBreaker.RecordFailure();
                Log($"Connection failed: {ex.Message}");
                OnError?.Invoke(ex);
                return false;
            }
            }
    
    
            public async Task DisconnectAsync(string reason = "Manual disconnect")
            {
            _isConnected = false;
            _cts?.Cancel();
            Cleanup();
            OnDisconnected?.Invoke(reason);
            Log($"Disconnected: {reason}");
            }
    
    
            public void EnqueueSend(TransportMessage message)
            {
            _sendQueue.Enqueue(message);
            }
    
    
            public async Task<bool> SendAsync(TransportMessage message, CancellationToken ct = default)
            {
            if (!_isConnected || _stream == null) return false;
            try
            {
                var data = Encoding.UTF8.GetBytes(SerializeMessage(message));
                await _stream.WriteAsync(data, 0, data.Length, ct).ConfigureAwait(false);
                await _stream.FlushAsync(ct).ConfigureAwait(false);
                BytesSent += data.Length;
                return true;
            }
            catch (Exception ex)
            {
                Log($"Send failed: {ex.Message}");
                return false;
            }
            }
    
    
            public bool TryDequeueReceived(out TransportMessage message)
            {
            return _receiveQueue.TryDequeue(out message!);
            }
    
    
            private async Task ReadLoopAsync(CancellationToken ct)
            {
            var buffer = new byte[65536];
            while (!ct.IsCancellationRequested && _isConnected)
            {
                try
                {
                if (_stream == null) break;
                int bytesRead = await _stream.ReadAsync(buffer, 0, buffer.Length, ct).ConfigureAwait(false);
                if (bytesRead == 0) { await DisconnectAsync("Server closed connection"); break; }
    
                BytesReceived += bytesRead;
                var text = Encoding.UTF8.GetString(buffer, 0, bytesRead);
    
                // Handle multi-message frames (newline delimited)
                foreach (var line in text.Split('\n', StringSplitOptions.RemoveEmptyEntries))
                {
                    var msg = DeserializeMessage(line.Trim());
                    if (msg != null)
                    {
                    _receiveQueue.Enqueue(msg);
                    OnMessageReceived?.Invoke(msg);
                    }
                }
                }
                catch (OperationCanceledException) { break; }
                catch (IOException) { await AttemptReconnectAsync(ct).ConfigureAwait(false); }
                catch (Exception ex) { Log($"Read error: {ex.Message}"); }
            }
            }
    
    
            private async Task SendLoopAsync(CancellationToken ct)
            {
            while (!ct.IsCancellationRequested && _isConnected)
            {
                while (_sendQueue.TryDequeue(out var msg))
                {
                await SendAsync(msg, ct).ConfigureAwait(false);
                }
                await Task.Delay(50, ct).ConfigureAwait(false);
            }
            }
    
    
            private async Task HeartbeatLoopAsync(CancellationToken ct)
            {
            while (!ct.IsCancellationRequested && _isConnected)
            {
                await Task.Delay(10000, ct).ConfigureAwait(false);
                if (!_isConnected) break;
                var hb = new HeartbeatPayload { ATM_ID = _clientId, SessionId = _sessionId, TimestampUtc = DateTime.UtcNow };
                var msg = new TransportMessage { MessageType = "HEARTBEAT", Payload = Encoding.UTF8.GetBytes(SerializeHeartbeat(hb)) };
                EnqueueSend(msg);
                _lastHeartbeatUtc = DateTime.UtcNow;
            }
            }
    
    
            private async Task SendHandshakeAsync(CancellationToken ct)
            {
            var hs = new HandshakeRequest { ATM_ID = _clientId, ProtocolVersion = "EJLv5" };
            var msg = new TransportMessage { MessageType = "HANDSHAKE", Payload = Encoding.UTF8.GetBytes(SerializeHandshake(hs)) };
            await SendAsync(msg, ct).ConfigureAwait(false);
            }
    
    
            private async Task AttemptReconnectAsync(CancellationToken ct)
            {
            _isConnected = false;
            Cleanup();
            while (!ct.IsCancellationRequested && !_isConnected)
            {
                var delay = _backoff.NextDelay();
                Log($"Reconnecting in {delay.TotalSeconds:N0}s...");
                await Task.Delay(delay, ct).ConfigureAwait(false);
                await ConnectAsync(ct).ConfigureAwait(false);
            }
            }
    
    
            private static string SerializeMessage(TransportMessage msg)
            {
            return $"{msg.MessageType}|{msg.TransferId}|{msg.FileName}|{msg.ChunkIndex}|{msg.TotalChunks}|{msg.ChunkSize}|{msg.Checksum}|{msg.IsLastChunk}|{Convert.ToBase64String(msg.Payload ?? Array.Empty<byte>())}\n";
            }
    
    
            private static TransportMessage? DeserializeMessage(string line)
            {
            try
            {
                var parts = line.Split('|');
                if (parts.Length < 9) return null;
                return new TransportMessage
                {
                MessageType = parts[0],
                TransferId = parts[1],
                FileName = parts[2],
                ChunkIndex = int.TryParse(parts[3], out var ci) ? ci : 0,
                TotalChunks = int.TryParse(parts[4], out var tc) ? tc : 0,
                ChunkSize = int.TryParse(parts[5], out var cs) ? cs : 0,
                Checksum = parts[6],
                IsLastChunk = bool.TryParse(parts[7], out var lc) && lc,
                Payload = Convert.FromBase64String(parts[8])
                };
            }
            catch { return null; }
            }
    
    
            private static string SerializeHeartbeat(HeartbeatPayload hb)
            {
            return $"HB|{hb.ATM_ID}|{hb.SessionId}|{hb.TimestampUtc:O}";
            }
    
    
            private static string SerializeHandshake(HandshakeRequest hs)
            {
            return $"HS|{hs.ATM_ID}|{hs.MachineId}|{hs.ProtocolVersion}|{hs.ClientVersion}|{hs.Nonce}|{hs.TimestampUtc:O}";
            }
    
    
            private void Cleanup()
            {
            try { _tcpClient?.Close(); } catch { }
            try { _stream?.Dispose(); } catch { }
            _tcpClient = null;
            _stream = null;
            }
    
    
            private void Log(string msg)
            {
            try { OnLog?.Invoke($"[NetworkEngine] {msg}"); } catch { }
            }
    
    
            public void Dispose()
            {
            if (!_disposed)
            {
                _disposed = true;
                _cts?.Cancel();
                _cts?.Dispose();
                Cleanup();
            }
            }
    
    
            public event Action? OnConnected;
    
    
            public event Action<string>? OnDisconnected;
    
    
            public event Action<string>? OnLog;
    
    
            public event Action<Exception>? OnError;
    
    
            public event Action<TransportMessage>? OnMessageReceived;
    
    
            public event Action<string, string>? OnSessionEstablished;
    
    
        }
    
