    namespace EJLive.Client.WinForms.Services
    {
        public class NetworkEngine
        {
            using System;
        using System.Linq;
        using EJLive.Core;
        using EJLive.Core.Engine;
        using EJLive.Core.Models;
        using EJLive.Shared;
    
        namespace EJLive.Client.WinForms.Services
        {
        public sealed class NetworkEngine : IDisposable
        {
            private readonly EJLive.Core.Engine.NetworkEngine _engine;
    
            public event Action<string>? OnLog;
            public event Action<Exception>? OnError;
            public event Action? OnConnected;
            public event Action? OnDisconnected;
            public event Action<string, string[]>? OnCommandReceived;
        private readonly string _atmId;
            private readonly string _atmType;
            private readonly string _serverIP;
            private readonly int _serverPort;
            private TcpClient _client;
            private NetworkStream _stream;
            private Thread _heartbeatThread;
            private Thread _readThread;
            private volatile bool _isConnected;
    
            public event Action<string> OnLog;
            public event Action<Exception> OnError;
            public event Action OnConnected;
            public event Action OnDisconnected;
            public event Action<string, string[]> OnCommandReceived;
            public bool IsConnected => _engine.IsConnected;
    
            public NetworkEngine(string atmId, string atmType, string serverIP, int serverPort)
            {
            var config = AppConfig.Load();
            var transport = new NetworkTransportOptions
            {
                EnableTlsTransport = config.EnableTlsTransport,
                RequireTlsTransport = config.RequireTlsTransport,
                AllowUntrustedTlsCertificate = config.AllowUntrustedTlsCertificate,
                EnableAdaptiveChunking = config.EnableAdaptiveChunking,
                WeakNetworkLatencyMs = config.WeakNetworkLatencyMs
            };
    
            _engine = new EJLive.Core.Engine.NetworkEngine(
                serverIP,
                serverPort,
                string.IsNullOrWhiteSpace(atmId) ? "Unknown" : atmId.Trim(),
                string.IsNullOrWhiteSpace(atmType) ? AppConstants.ATM_TYPE_NCR : atmType.Trim(),
                transportOptions: transport);
    
            _engine.OnLog += (_, message) => OnLog?.Invoke("[Network] " + message);
            _engine.OnError += (_, message) => OnError?.Invoke(new InvalidOperationException(message));
            _engine.OnConnectionChanged += (_, connected) =>
            {
                if (connected) OnConnected?.Invoke();
                else OnDisconnected?.Invoke();
            };
            _engine.OnMessageReceived += (_, message) => HandleIncomingMessage(message);
            }
    
            public void Connect()
            {
            _engine.Connect();
            }
    
            public void Disconnect()
            {
            _engine.Disconnect();
            }
    
            public bool SendJournalData(string fileName, byte[] rawData, string checksum)
            {
            var payload = rawData ?? Array.Empty<byte>();
            var computedChecksum = string.IsNullOrWhiteSpace(checksum)
                ? SecurityHelper.SHA256Hash(payload)
                : checksum;
            return _engine.SendJournalFile(fileName ?? "journal.ej", payload, 0, computedChecksum);
            }
    
            public void SendTerminalProfile(string branchName, string vendor, string network, string region)
            {
            var payload = $"STATUSMETA|branch={Sanitize(branchName)}|vendor={Sanitize(vendor)}|network={Sanitize(network)}|region={Sanitize(region)}";
            _engine.SendMessage(CommunicationProtocol.BuildFrame(CommunicationProtocol.MsgType.Broadcast, payload));
            }
    
            public void SendCashStatus(int cass1, int cass2, int cass3, int cass4, int remaining, int loaded, int depositIn, int dispenseOut, int reject, int retract)
            {
            var payload = string.Join("|", new[]
            {
                "CASHSTATUS",
                "cass1=" + cass1,
                "cass2=" + cass2,
                "cass3=" + cass3,
                "cass4=" + cass4,
                "remaining=" + remaining,
                "loaded=" + loaded,
                "depositIn=" + depositIn,
                "dispenseOut=" + dispenseOut,
                "reject=" + reject,
                "retract=" + retract
            });
            _engine.SendMessage(CommunicationProtocol.BuildFrame(CommunicationProtocol.MsgType.Broadcast, payload));
            }
    
            public void SendCommandResult(string command, bool success, string message)
            {
            _engine.SendMessage(CommunicationProtocol.BuildCommandResult(
                string.IsNullOrWhiteSpace(command) ? Guid.NewGuid().ToString("N") : command,
                success,
                message ?? string.Empty));
            }
    
            public void SendFile(string fileName, byte[] data, string checksum)
            {
            var payload = data ?? Array.Empty<byte>();
            var computedChecksum = string.IsNullOrWhiteSpace(checksum)
                ? SecurityHelper.SHA256Hash(payload)
                : checksum;
            _engine.SendJournalFile(fileName ?? "payload.bin", payload, 0, computedChecksum);
            }
    
            public void SendRawData(byte[] data)
            {
            if (data == null || data.Length == 0)
                return;
            _engine.SendMessage(data);
            }
    
            private void HandleIncomingMessage(EJMessage message)
            {
            if (message.Type != CommunicationProtocol.MsgType.Command)
                return;
    
            if (RemoteCommandEnvelope.TryParse(message.Text, out var command))
            {
                var parameters = string.IsNullOrWhiteSpace(command.Payload)
                ? Array.Empty<string>()
                : command.Payload.Split(';', StringSplitOptions.RemoveEmptyEntries)
                    .Select(value => value.Trim())
                    .Where(value => value.Length > 0)
                    .ToArray();
                OnCommandReceived?.Invoke(command.CommandType, parameters);
                return;
            }
    
            if (!AppConfig.Load().AllowUnsignedLegacyCommands)
            {
                OnLog?.Invoke("[Network] Command rejected: signature verification failed and unsigned fallback is disabled.");
                return;
            }
    
            var fallbackParts = (message.Text ?? string.Empty).Split('|', StringSplitOptions.RemoveEmptyEntries);
            if (fallbackParts.Length == 0)
                return;
            OnCommandReceived?.Invoke(fallbackParts[0], fallbackParts.Skip(1).ToArray());
            }
    
            private static string Sanitize(string value)
            {
            if (string.IsNullOrWhiteSpace(value))
                return "-";
            return value.Replace("|", "/").Replace("\r", " ").Replace("\n", " ").Trim();
            }
    
            public void Dispose()
            {
            _engine.Dispose();
            }
        }
        }
    
    
    
            public bool IsConnected
            {
            get
            {
                return _isConnected;
            }
            }
    
            public NetworkEngine(string atmId, string atmType, string serverIP, int serverPort)
            {
            _atmId = string.IsNullOrWhiteSpace(atmId) ? "Unknown" : atmId.Trim();
            _atmType = string.IsNullOrWhiteSpace(atmType) ? "Unknown" : atmType.Trim();
            _serverIP = serverIP;
            _serverPort = serverPort;
            }
    
            public void Connect()
            {
            try
            {
                Disconnect();
                _client = new TcpClient();
                _client.Connect(_serverIP, _serverPort);
                _stream = _client.GetStream();
                _isConnected = true;
    
                SendLine("EJLIVE_HANDSHAKE|" + _atmId + "|" + _atmType + "|" + DateTime.Now.ToString("yyyyMMddHHmmss"));
                StartHeartbeat();
                StartReader();
                Log("Connected to server " + _serverIP + ":" + _serverPort);
                OnConnected?.Invoke();
            }
            catch (Exception ex)
            {
                _isConnected = false;
                OnError?.Invoke(ex);
                OnDisconnected?.Invoke();
            }
            }
    
            public void Disconnect()
            {
            bool wasConnected = _isConnected;
            _isConnected = false;
            try
            {
                _stream?.Close();
            }
            catch { }
            try
            {
                _client?.Close();
            }
            catch { }
            _stream = null;
            _client = null;
            if (wasConnected)
            {
                Log("Disconnected from server.");
                OnDisconnected?.Invoke();
            }
            }
    
            public bool SendJournalData(string fileName, byte[] rawData, string checksum)
            {
            if (!_isConnected || _stream == null) return false;
            try
            {
                byte[] compressed = CompressData(rawData);
                byte[] encrypted = EncryptAES256(compressed);
                string header = "EJDATA|" + _atmId + "|" + encrypted.Length + "|" + Sanitize(fileName) + "|" + Sanitize(checksum);
                byte[] headerBytes = Encoding.UTF8.GetBytes(header + "\n");
                _stream.Write(headerBytes, 0, headerBytes.Length);
                _stream.Write(encrypted, 0, encrypted.Length);
                _stream.Flush();
                return true;
            }
            catch (Exception ex)
            {
                OnError?.Invoke(ex);
                Disconnect();
                return false;
            }
            }
    
            public void SendTerminalProfile(string branchName, string vendor, string network, string region)
            {
            SendLine("STATUSMETA|" + _atmId + "|branch=" + Sanitize(branchName) + "|vendor=" + Sanitize(vendor) + "|network=" + Sanitize(network) + "|region=" + Sanitize(region));
            }
    
            public void SendCashStatus(int cass1, int cass2, int cass3, int cass4, int remaining, int loaded, int depositIn, int dispenseOut, int reject, int retract)
            {
            SendLine(
                "CASHSTATUS|" + _atmId +
                "|cass1=" + cass1 +
                "|cass2=" + cass2 +
                "|cass3=" + cass3 +
                "|cass4=" + cass4 +
                "|remaining=" + remaining +
                "|loaded=" + loaded +
                "|depositIn=" + depositIn +
                "|dispenseOut=" + dispenseOut +
                "|reject=" + reject +
                "|retract=" + retract);
            }
    
            public void SendCommandResult(string command, bool success, string message)
            {
            SendLine("CMD_RESULT|" + _atmId + "|" + Sanitize(command) + "|" + (success ? "OK" : "FAIL") + "|" + Sanitize(message));
            }
    
            public void SendFile(string fileName, byte[] data, string checksum)
            {
            if (!_isConnected || _stream == null || data == null) return;
            try
            {
                string header = "EJFILE|" + _atmId + "|" + data.Length + "|" + Sanitize(fileName) + "|" + Sanitize(checksum);
                byte[] headerBytes = Encoding.UTF8.GetBytes(header + "\n");
                _stream.Write(headerBytes, 0, headerBytes.Length);
                _stream.Write(data, 0, data.Length);
                _stream.Flush();
            }
            catch (Exception ex)
            {
                OnError?.Invoke(ex);
                Disconnect();
            }
            }
    
            public void SendRawData(byte[] data)
            {
            if (!_isConnected || _stream == null || data == null) return;
            try
            {
                _stream.Write(data, 0, data.Length);
                _stream.Flush();
            }
            catch (Exception ex)
            {
                OnError?.Invoke(ex);
                Disconnect();
            }
            }
    
            private void StartHeartbeat()
            {
            _heartbeatThread = new Thread(() => {
                while (_isConnected)
                {
                try
                {
                    SendLine("HEARTBEAT|" + _atmId + "|" + DateTime.Now.ToString("yyyyMMddHHmmss"));
                    Thread.Sleep(30000);
                }
                catch
                {
                    Disconnect();
                    break;
                }
                }
            });
            _heartbeatThread.IsBackground = true;
            _heartbeatThread.Start();
            }
    
            private void StartReader()
            {
            _readThread = new Thread(() => {
                byte[] buffer = new byte[8192];
                while (_isConnected)
                {
                try
                {
                    int bytesRead = _stream.Read(buffer, 0, buffer.Length);
                    if (bytesRead <= 0) break;
                    string payload = Encoding.UTF8.GetString(buffer, 0, bytesRead).Trim();
                    if (string.IsNullOrWhiteSpace(payload)) continue;
                    foreach (string line in payload.Split(new[] {
                '\n'
            }, StringSplitOptions.RemoveEmptyEntries))
                    {
                    HandleServerLine(line.Trim());
                    }
                }
                catch (Exception ex)
                {
                    OnError?.Invoke(ex);
                    break;
                }
                }
                Disconnect();
            });
            _readThread.IsBackground = true;
            _readThread.Start();
            }
    
            private void HandleServerLine(string line)
            {
            if (line.StartsWith("CMD|", StringComparison.OrdinalIgnoreCase))
            {
                string[] parts = line.Split('|');
                if (parts.Length >= 2)
                {
                string command = parts[1];
                string[] parameters = parts.Length > 2 ? new ArraySegment<string>(parts, 2, parts.Length - 2).ToArray() : new string[0];
                OnCommandReceived?.Invoke(command, parameters);
                }
            }
            }
    
            private void SendLine(string line)
            {
            if (!_isConnected || _stream == null) return;
            byte[] bytes = Encoding.UTF8.GetBytes(line + "\n");
            _stream.Write(bytes, 0, bytes.Length);
            _stream.Flush();
            }
    
            private static string Sanitize(string value)
            {
            if (string.IsNullOrWhiteSpace(value)) return "-";
            return value.Replace("|", "/").Replace("\r", " ").Replace("\n", " ").Trim();
            }
    
            private void Log(string message)
            {
            OnLog?.Invoke("[Network] " + message);
            }
    
            private static byte[] CompressData(byte[] data)
            {
            using (MemoryStream output = new MemoryStream())
            {
                using (DeflateStream deflate = new DeflateStream(output, CompressionMode.Compress))
                {
                deflate.Write(data, 0, data.Length);
                }
                return output.ToArray();
            }
            }
    
            private static byte[] EncryptAES256(byte[] data)
            {
            using (Aes aes = Aes.Create())
            {
                aes.Key = Encoding.UTF8.GetBytes(EJLive.Core.Constants.Encryption.AESKey);
                aes.IV = Encoding.UTF8.GetBytes(EJLive.Core.Constants.Encryption.AESIV);
                aes.Mode = CipherMode.CBC;
                aes.Padding = PaddingMode.PKCS7;
                using (ICryptoTransform encryptor = aes.CreateEncryptor())
                {
                return encryptor.TransformFinalBlock(data, 0, data.Length);
                }
            }
            }
        }
        public sealed class NetworkEngine : IDisposable
        {
            private readonly EJLive.Core.Engine.NetworkEngine _engine;
    
            public event Action<string>? OnLog;
            public event Action<Exception>? OnError;
            public event Action? OnConnected;
            public event Action? OnDisconnected;
            public event Action<string, string[]>? OnCommandReceived;
        private readonly string _atmId;
            private readonly string _atmType;
            private readonly string _serverIP;
            private readonly int _serverPort;
            private TcpClient _client;
            private NetworkStream _stream;
            private Thread _heartbeatThread;
            private Thread _readThread;
            private volatile bool _isConnected;
    
            public event Action<string> OnLog;
            public event Action<Exception> OnError;
            public event Action OnConnected;
            public event Action OnDisconnected;
            public event Action<string, string[]> OnCommandReceived;
            public bool IsConnected => _engine.IsConnected;
    
            public NetworkEngine(string atmId, string atmType, string serverIP, int serverPort)
            {
            var config = AppConfig.Load();
            var transport = new NetworkTransportOptions
            {
                EnableTlsTransport = config.EnableTlsTransport,
                RequireTlsTransport = config.RequireTlsTransport,
                AllowUntrustedTlsCertificate = config.AllowUntrustedTlsCertificate,
                EnableAdaptiveChunking = config.EnableAdaptiveChunking,
                WeakNetworkLatencyMs = config.WeakNetworkLatencyMs
            };
    
            _engine = new EJLive.Core.Engine.NetworkEngine(
                serverIP,
                serverPort,
                string.IsNullOrWhiteSpace(atmId) ? "Unknown" : atmId.Trim(),
                string.IsNullOrWhiteSpace(atmType) ? AppConstants.ATM_TYPE_NCR : atmType.Trim(),
                transportOptions: transport);
    
            _engine.OnLog += (_, message) => OnLog?.Invoke("[Network] " + message);
            _engine.OnError += (_, message) => OnError?.Invoke(new InvalidOperationException(message));
            _engine.OnConnectionChanged += (_, connected) =>
            {
                if (connected) OnConnected?.Invoke();
                else OnDisconnected?.Invoke();
            };
            _engine.OnMessageReceived += (_, message) => HandleIncomingMessage(message);
            }
    
            public void Connect()
            {
            _engine.Connect();
            }
    
            public void Disconnect()
            {
            _engine.Disconnect();
            }
    
            public bool SendJournalData(string fileName, byte[] rawData, string checksum)
            {
            var payload = rawData ?? Array.Empty<byte>();
            var computedChecksum = string.IsNullOrWhiteSpace(checksum)
                ? SecurityHelper.SHA256Hash(payload)
                : checksum;
            return _engine.SendJournalFile(fileName ?? "journal.ej", payload, 0, computedChecksum);
            }
    
            public void SendTerminalProfile(string branchName, string vendor, string network, string region)
            {
            var payload = $"STATUSMETA|branch={Sanitize(branchName)}|vendor={Sanitize(vendor)}|network={Sanitize(network)}|region={Sanitize(region)}";
            _engine.SendMessage(CommunicationProtocol.BuildFrame(CommunicationProtocol.MsgType.Broadcast, payload));
            }
    
            public void SendCashStatus(int cass1, int cass2, int cass3, int cass4, int remaining, int loaded, int depositIn, int dispenseOut, int reject, int retract)
            {
            var payload = string.Join("|", new[]
            {
                "CASHSTATUS",
                "cass1=" + cass1,
                "cass2=" + cass2,
                "cass3=" + cass3,
                "cass4=" + cass4,
                "remaining=" + remaining,
                "loaded=" + loaded,
                "depositIn=" + depositIn,
                "dispenseOut=" + dispenseOut,
                "reject=" + reject,
                "retract=" + retract
            });
            _engine.SendMessage(CommunicationProtocol.BuildFrame(CommunicationProtocol.MsgType.Broadcast, payload));
            }
    
            public void SendCommandResult(string command, bool success, string message)
            {
            _engine.SendMessage(CommunicationProtocol.BuildCommandResult(
                string.IsNullOrWhiteSpace(command) ? Guid.NewGuid().ToString("N") : command,
                success,
                message ?? string.Empty));
            }
    
            public void SendFile(string fileName, byte[] data, string checksum)
            {
            var payload = data ?? Array.Empty<byte>();
            var computedChecksum = string.IsNullOrWhiteSpace(checksum)
                ? SecurityHelper.SHA256Hash(payload)
                : checksum;
            _engine.SendJournalFile(fileName ?? "payload.bin", payload, 0, computedChecksum);
            }
    
            public void SendRawData(byte[] data)
            {
            if (data == null || data.Length == 0)
                return;
            _engine.SendMessage(data);
            }
    
            private void HandleIncomingMessage(EJMessage message)
            {
            if (message.Type != CommunicationProtocol.MsgType.Command)
                return;
    
            if (RemoteCommandEnvelope.TryParse(message.Text, out var command))
            {
                var parameters = string.IsNullOrWhiteSpace(command.Payload)
                ? Array.Empty<string>()
                : command.Payload.Split(';', StringSplitOptions.RemoveEmptyEntries)
                    .Select(value => value.Trim())
                    .Where(value => value.Length > 0)
                    .ToArray();
                OnCommandReceived?.Invoke(command.CommandType, parameters);
                return;
            }
    
            if (!AppConfig.Load().AllowUnsignedLegacyCommands)
            {
                OnLog?.Invoke("[Network] Command rejected: signature verification failed and unsigned fallback is disabled.");
                return;
            }
    
            var fallbackParts = (message.Text ?? string.Empty).Split('|', StringSplitOptions.RemoveEmptyEntries);
            if (fallbackParts.Length == 0)
                return;
            OnCommandReceived?.Invoke(fallbackParts[0], fallbackParts.Skip(1).ToArray());
            }
    
            private static string Sanitize(string value)
            {
            if (string.IsNullOrWhiteSpace(value))
                return "-";
            return value.Replace("|", "/").Replace("\r", " ").Replace("\n", " ").Trim();
            }
    
            public void Dispose()
            {
            _engine.Dispose();
            }
        }
