        public partial class NetworkEngine
        {
            private readonly string _atmId;
    
    
            private readonly string _atmType;
    
    
            private readonly string _serverIP;
    
    
            private readonly int _serverPort;
    
    
            private TcpClient _client;
    
    
            private NetworkStream _stream;
    
    
            private Thread _heartbeatThread;
    
    
            private Thread _readThread;
    
    
            private volatile bool _isConnected;
    
    
            public bool IsConnected { get { return _isConnected; } }
    
    
            public NetworkEngine(string atmId, string atmType, string serverIP, int serverPort)
            {
            _atmId = string.IsNullOrWhiteSpace(atmId) ? "Unknown" : atmId.Trim();
            _atmType = string.IsNullOrWhiteSpace(atmType) ? "Unknown" : atmType.Trim();
            _serverIP = serverIP;
            _serverPort = serverPort;
            }
    
    
            public void Connect()
            {
            try
            {
                Disconnect();
                _client = new TcpClient();
                _client.Connect(_serverIP, _serverPort);
                _stream = _client.GetStream();
                _isConnected = true;
    
                SendLine("EJLIVE_HANDSHAKE|" + _atmId + "|" + _atmType + "|" + DateTime.Now.ToString("yyyyMMddHHmmss"));
                StartHeartbeat();
                StartReader();
                Log("Connected to server " + _serverIP + ":" + _serverPort);
                OnConnected?.Invoke();
            }
            catch (Exception ex)
            {
                _isConnected = false;
                OnError?.Invoke(ex);
                OnDisconnected?.Invoke();
            }
            }
    
    
            public void Disconnect()
            {
            bool wasConnected = _isConnected;
            _isConnected = false;
            try { _stream?.Close(); } catch { }
            try { _client?.Close(); } catch { }
            _stream = null;
            _client = null;
            if (wasConnected)
            {
                Log("Disconnected from server.");
                OnDisconnected?.Invoke();
            }
            }
    
    
            public bool SendJournalData(string fileName, byte[] rawData, string checksum)
            {
            if (!_isConnected || _stream == null) return false;
            try
            {
                byte[] compressed = CompressData(rawData);
                byte[] encrypted = EncryptAES256(compressed);
                string header = "EJDATA|" + _atmId + "|" + encrypted.Length + "|" + Sanitize(fileName) + "|" + Sanitize(checksum);
                byte[] headerBytes = Encoding.UTF8.GetBytes(header + "\n");
                _stream.Write(headerBytes, 0, headerBytes.Length);
                _stream.Write(encrypted, 0, encrypted.Length);
                _stream.Flush();
                return true;
            }
            catch (Exception ex)
            {
                OnError?.Invoke(ex);
                Disconnect();
                return false;
            }
            }
    
    
            public void SendTerminalProfile(string branchName, string vendor, string network, string region)
            {
            SendLine("STATUSMETA|" + _atmId + "|branch=" + Sanitize(branchName) + "|vendor=" + Sanitize(vendor) + "|network=" + Sanitize(network) + "|region=" + Sanitize(region));
            }
    
    
            public void SendCashStatus(int cass1, int cass2, int cass3, int cass4, int remaining, int loaded, int depositIn, int dispenseOut, int reject, int retract)
            {
            SendLine(
                "CASHSTATUS|" + _atmId +
                "|cass1=" + cass1 +
                "|cass2=" + cass2 +
                "|cass3=" + cass3 +
                "|cass4=" + cass4 +
                "|remaining=" + remaining +
                "|loaded=" + loaded +
                "|depositIn=" + depositIn +
                "|dispenseOut=" + dispenseOut +
                "|reject=" + reject +
                "|retract=" + retract);
            }
    
    
            public void SendCommandResult(string commandId, bool success, string message)
            {
            SendLine(
                "CMD_RESULT|" +
                _atmId + "|" +
                Sanitize(commandId) + "|" +
                (success ? "ACK" : "FAILED") + "|" +
                Sanitize(message) + "|" +
                DateTime.Now.ToString("yyyyMMddHHmmss"));
            }
    
    
            public void SendFile(string fileName, byte[] data, string checksum)
            {
            if (!_isConnected || _stream == null || data == null) return;
            try
            {
                string header = "EJFILE|" + _atmId + "|" + data.Length + "|" + Sanitize(fileName) + "|" + Sanitize(checksum);
                byte[] headerBytes = Encoding.UTF8.GetBytes(header + "\n");
                _stream.Write(headerBytes, 0, headerBytes.Length);
                _stream.Write(data, 0, data.Length);
                _stream.Flush();
            }
            catch (Exception ex)
            {
                OnError?.Invoke(ex);
                Disconnect();
            }
            }
    
    
            public void SendRawData(byte[] data)
            {
            if (!_isConnected || _stream == null || data == null) return;
            try
            {
                _stream.Write(data, 0, data.Length);
                _stream.Flush();
            }
            catch (Exception ex)
            {
                OnError?.Invoke(ex);
                Disconnect();
            }
            }
    
    
            private void StartHeartbeat()
            {
            _heartbeatThread = new Thread(() =>
            {
                while (_isConnected)
                {
                try
                {
                    SendLine("HEARTBEAT|" + _atmId + "|" + DateTime.Now.ToString("yyyyMMddHHmmss"));
                    Thread.Sleep(30000);
                }
                catch
                {
                    Disconnect();
                    break;
                }
                }
            });
            _heartbeatThread.IsBackground = true;
            _heartbeatThread.Start();
            }
    
    
            private void StartReader()
            {
            _readThread = new Thread(() =>
            {
                byte[] buffer = new byte[8192];
                while (_isConnected)
                {
                try
                {
                    int bytesRead = _stream.Read(buffer, 0, buffer.Length);
                    if (bytesRead <= 0) break;
                    string payload = Encoding.UTF8.GetString(buffer, 0, bytesRead).Trim();
                    if (string.IsNullOrWhiteSpace(payload)) continue;
                    foreach (string line in payload.Split(new[] { '\n' }, StringSplitOptions.RemoveEmptyEntries))
                    {
                    HandleServerLine(line.Trim());
                    }
                }
                catch (Exception ex)
                {
                    OnError?.Invoke(ex);
                    break;
                }
                }
                Disconnect();
            });
            _readThread.IsBackground = true;
            _readThread.Start();
            }
    
    
            private void HandleServerLine(string line)
            {
            if (line.StartsWith("CMD|", StringComparison.OrdinalIgnoreCase))
            {
                string[] parts = line.Split('|');
                if (parts.Length >= 3)
                {
                string commandId = parts[1];
                string command = parts[2];
                string[] parameters = parts.Length > 3 ? new ArraySegment<string>(parts, 3, parts.Length - 3).ToArray() : new string[0];
                OnCommandReceived?.Invoke(commandId, command, parameters);
                }
            }
            }
    
    
            private void SendLine(string line)
            {
            if (!_isConnected || _stream == null) return;
            byte[] bytes = Encoding.UTF8.GetBytes(line + "\n");
            _stream.Write(bytes, 0, bytes.Length);
            _stream.Flush();
            }
    
    
            private static string Sanitize(string value)
            {
            if (string.IsNullOrWhiteSpace(value)) return "-";
            return value.Replace("|", "/").Replace("\r", " ").Replace("\n", " ").Trim();
            }
    
    
            private void Log(string message)
            {
            OnLog?.Invoke("[Network] " + message);
            }
    
    
            private static byte[] CompressData(byte[] data)
            {
            using (MemoryStream output = new MemoryStream())
            {
                using (DeflateStream deflate = new DeflateStream(output, CompressionMode.Compress))
                {
                deflate.Write(data, 0, data.Length);
                }
                return output.ToArray();
            }
            }
    
    
            private static byte[] EncryptAES256(byte[] data)
            {
            using (Aes aes = Aes.Create())
            {
                aes.Key = Encoding.UTF8.GetBytes(EJLive.Core.Constants.Encryption.AESKey);
                aes.IV = Encoding.UTF8.GetBytes(EJLive.Core.Constants.Encryption.AESIV);
                aes.Mode = CipherMode.CBC;
                aes.Padding = PaddingMode.PKCS7;
                using (ICryptoTransform encryptor = aes.CreateEncryptor())
                {
                return encryptor.TransformFinalBlock(data, 0, data.Length);
                }
            }
            }
    
    
            public event Action<string> OnLog;
    
    
            public event Action<Exception> OnError;
    
    
            public event Action OnConnected;
    
    
            public event Action OnDisconnected;
    
    
            public event Action<string, string, string[]> OnCommandReceived;
    
    
        }
        public partial class NetworkEngine : IDisposable
        {
            private readonly EJLive.Core.Engine.NetworkEngine _engine;
    
    
            public bool IsConnected => _engine.IsConnected;
    
    
            public NetworkEngine(string atmId, string atmType, string serverIP, int serverPort)
            {
            var config = AppConfig.Load();
            var transport = new NetworkTransportOptions
            {
                EnableTlsTransport = config.EnableTlsTransport,
                RequireTlsTransport = config.RequireTlsTransport,
                AllowUntrustedTlsCertificate = config.AllowUntrustedTlsCertificate,
                EnableAdaptiveChunking = config.EnableAdaptiveChunking,
                WeakNetworkLatencyMs = config.WeakNetworkLatencyMs
            };
    
            _engine = new EJLive.Core.Engine.NetworkEngine(
                serverIP,
                serverPort,
                string.IsNullOrWhiteSpace(atmId) ? "Unknown" : atmId.Trim(),
                string.IsNullOrWhiteSpace(atmType) ? AppConstants.ATM_TYPE_NCR : atmType.Trim(),
                transportOptions: transport);
    
            _engine.OnLog += (_, message) => OnLog?.Invoke("[Network] " + message);
            _engine.OnError += (_, message) => OnError?.Invoke(new InvalidOperationException(message));
            _engine.OnConnectionChanged += (_, connected) =>
            {
                if (connected) OnConnected?.Invoke();
                else OnDisconnected?.Invoke();
            };
            _engine.OnMessageReceived += (_, message) => HandleIncomingMessage(message);
            }
    
    
            public void Connect()
            {
            _engine.Connect();
            }
    
    
            public void Disconnect()
            {
            _engine.Disconnect();
            }
    
    
            public bool SendJournalData(string fileName, byte[] rawData, string checksum)
            {
            var payload = rawData ?? Array.Empty<byte>();
            var computedChecksum = string.IsNullOrWhiteSpace(checksum)
                ? SecurityHelper.SHA256Hash(payload)
                : checksum;
            return _engine.SendJournalFile(fileName ?? "journal.ej", payload, 0, computedChecksum);
            }
    
    
            public void SendTerminalProfile(string branchName, string vendor, string network, string region)
            {
            var payload = $"STATUSMETA|branch={Sanitize(branchName)}|vendor={Sanitize(vendor)}|network={Sanitize(network)}|region={Sanitize(region)}";
            _engine.SendMessage(CommunicationProtocol.BuildFrame(CommunicationProtocol.MsgType.Broadcast, payload));
            }
    
    
            public void SendCashStatus(int cass1, int cass2, int cass3, int cass4, int remaining, int loaded, int depositIn, int dispenseOut, int reject, int retract)
            {
            var payload = string.Join("|", new[]
            {
                "CASHSTATUS",
                "cass1=" + cass1,
                "cass2=" + cass2,
                "cass3=" + cass3,
                "cass4=" + cass4,
                "remaining=" + remaining,
                "loaded=" + loaded,
                "depositIn=" + depositIn,
                "dispenseOut=" + dispenseOut,
                "reject=" + reject,
                "retract=" + retract
            });
            _engine.SendMessage(CommunicationProtocol.BuildFrame(CommunicationProtocol.MsgType.Broadcast, payload));
            }
    
    
            public void SendCommandResult(string command, bool success, string message)
            {
            _engine.SendMessage(CommunicationProtocol.BuildCommandResult(
                string.IsNullOrWhiteSpace(command) ? Guid.NewGuid().ToString("N") : command,
                success,
                message ?? string.Empty));
            }
    
    
            public void SendFile(string fileName, byte[] data, string checksum)
            {
            var payload = data ?? Array.Empty<byte>();
            var computedChecksum = string.IsNullOrWhiteSpace(checksum)
                ? SecurityHelper.SHA256Hash(payload)
                : checksum;
            _engine.SendJournalFile(fileName ?? "payload.bin", payload, 0, computedChecksum);
            }
    
    
            public void SendRawData(byte[] data)
            {
            if (data == null || data.Length == 0)
                return;
            _engine.SendMessage(data);
            }
    
    
            private void HandleIncomingMessage(EJMessage message)
            {
            if (message.Type != CommunicationProtocol.MsgType.Command)
                return;
    
            if (RemoteCommandEnvelope.TryParse(message.Text, out var command))
            {
                var parameters = string.IsNullOrWhiteSpace(command.Payload)
                ? Array.Empty<string>()
                : command.Payload.Split(';', StringSplitOptions.RemoveEmptyEntries)
                    .Select(value => value.Trim())
                    .Where(value => value.Length > 0)
                    .ToArray();
                OnCommandReceived?.Invoke(command.CommandType, parameters);
                return;
            }
    
            if (!AppConfig.Load().AllowUnsignedLegacyCommands)
            {
                OnLog?.Invoke("[Network] Command rejected: signature verification failed and unsigned fallback is disabled.");
                return;
            }
    
            var fallbackParts = (message.Text ?? string.Empty).Split('|', StringSplitOptions.RemoveEmptyEntries);
            if (fallbackParts.Length == 0)
                return;
            OnCommandReceived?.Invoke(fallbackParts[0], fallbackParts.Skip(1).ToArray());
            }
    
    
            private static string Sanitize(string value)
            {
            if (string.IsNullOrWhiteSpace(value))
                return "-";
            return value.Replace("|", "/").Replace("\r", " ").Replace("\n", " ").Trim();
            }
    
    
            public void Dispose()
            {
            _engine.Dispose();
            }
    
    
            public event Action<string>? OnLog;
    
    
            public event Action<Exception>? OnError;
    
    
            public event Action? OnConnected;
    
    
            public event Action? OnDisconnected;
    
    
            public event Action<string, string[]>? OnCommandReceived;
    
    
        }
        public partial class SimpleNetworkEngine
        {
            private TcpClient _tcpClient;
            private NetworkStream _stream;
            private Thread _receiveThread;
            private Thread _heartbeatThread;
            private string _serverIP;
            private int _serverPort;
            private string _atmId;
            private string _atmType;
            private string _clientVersion;
            private bool _isConnected;
            private bool _isRunning;
            private DateTime _lastHeartbeat;
            public bool IsConnected     { get { return _isConnected; } }
            public DateTime LastHeartbeat { get { return _lastHeartbeat; } }
            public SimpleNetworkEngine(string atmId, string atmType, string serverIP, int serverPort)
            {
            _atmId         = atmId;
            _atmType       = atmType;
            _serverIP      = serverIP;
            _serverPort    = serverPort;
            _clientVersion = AppConstants.APP_VERSION;
            _isConnected   = false;
            _isRunning     = false;
            }
            private readonly object _sendLock = new object();
            public bool Connect()
            {
            try
            {
                if (_isConnected) return true;
                OnLog?.Invoke("[Network] Connecting to " + _serverIP + ":" + _serverPort);
                _tcpClient = new TcpClient();
                _tcpClient.ReceiveTimeout  = NetworkConfig.CONNECTION_TIMEOUT_MS;
                _tcpClient.SendTimeout     = NetworkConfig.CONNECTION_TIMEOUT_MS;
                _tcpClient.ReceiveBufferSize = NetworkConfig.SOCKET_BUFFER_SIZE;
                _tcpClient.SendBufferSize  = NetworkConfig.SOCKET_BUFFER_SIZE;
                _tcpClient.NoDelay         = true;
                var result    = _tcpClient.BeginConnect(_serverIP, _serverPort, null, null);
                bool connected = result.AsyncWaitHandle.WaitOne(NetworkConfig.CONNECTION_TIMEOUT_MS);
                if (!connected)
                {
                OnLog?.Invoke("[Network] Connection timeout");
                return false;
                }
                _tcpClient.EndConnect(result);
                _stream = _tcpClient.GetStream();
                if (!PerformHandshake())
                {
                Disconnect();
                return false;
                }
                _isConnected = true;
                _isRunning   = true;
                _lastHeartbeat = DateTime.Now;
                _receiveThread = new Thread(ReceiveLoop);
                _receiveThread.IsBackground = true;
                _receiveThread.Start();
                _heartbeatThread = new Thread(HeartbeatLoop);
                _heartbeatThread.IsBackground = true;
                _heartbeatThread.Start();
                OnLog?.Invoke("[Network] Connected successfully");
                OnConnected?.Invoke();
                return true;
            }
            catch (Exception ex)
            {
                OnLog?.Invoke("[Network] Connection failed: " + ex.Message);
                OnError?.Invoke(ex);
                return false;
            }
            }
            public void Disconnect()
            {
            _isRunning   = false;
            _isConnected = false;
            try
            {
                if (_stream != null) { _stream.Close(); _stream = null; }
                if (_tcpClient != null) { _tcpClient.Close(); _tcpClient = null; }
            }
            catch { }
            OnLog?.Invoke("[Network] Disconnected");
            OnDisconnected?.Invoke();
            }
            public bool SendJournalData(string fileName, byte[] data, string checksum)
            {
            try
            {
                if (!_isConnected) return false;
                string header = Protocol.BuildMessage(
                Protocol.DATA_JOURNAL,
                _atmId,
                fileName,
                data.Length.ToString(),
                checksum,
                DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss")
                );
                lock (_sendLock)
                {
                SendString(header + Protocol.HEADER_END);
                _stream.Write(data, 0, data.Length);
                _stream.Flush();
                byte[] endMarker = Encoding.UTF8.GetBytes(Protocol.DATA_END);
                _stream.Write(endMarker, 0, endMarker.Length);
                _stream.Flush();
                }
                OnLog?.Invoke(string.Format("[Network] Sent {0} ({1} bytes)", fileName, data.Length));
                return true;
            }
            catch (Exception ex)
            {
                OnError?.Invoke(ex);
                HandleConnectionLost();
                return false;
            }
            }
            public bool SendFile(string fileName, byte[] fileData, string checksum)
            {
            try
            {
                if (!_isConnected) return false;
                string header = Protocol.BuildMessage(
                Protocol.DATA_FILE,
                _atmId,
                fileName,
                fileData.Length.ToString(),
                checksum,
                DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss")
                );
                lock (_sendLock)
                {
                SendString(header + Protocol.HEADER_END);
                _stream.Write(fileData, 0, fileData.Length);
                _stream.Flush();
                byte[] endMarker = Encoding.UTF8.GetBytes(Protocol.DATA_END);
                _stream.Write(endMarker, 0, endMarker.Length);
                _stream.Flush();
                }
                OnLog?.Invoke(string.Format("[Network] Sent file {0} ({1} bytes)", fileName, fileData.Length));
                return true;
            }
            catch (Exception ex)
            {
                OnError?.Invoke(ex);
                HandleConnectionLost();
                return false;
            }
            }
            public bool SendStatus(string status, string cscStatus)
            {
            try
            {
                if (!_isConnected) return false;
                string msg = Protocol.BuildMessage(
                Protocol.STATUS_RESPONSE,
                _atmId,
                status,
                cscStatus,
                DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss")
                );
                lock (_sendLock) { SendString(msg); }
                return true;
            }
            catch (Exception ex)
            {
                OnError?.Invoke(ex);
                return false;
            }
            }
            public bool SendCommandResult(string commandId, bool success, string resultData)
            {
            try
            {
                if (!_isConnected) return false;
                string msg = Protocol.BuildMessage(
                Protocol.CMD_RESULT,
                _atmId,
                commandId,
                success ? "OK" : "FAIL",
                resultData
                );
                lock (_sendLock) { SendString(msg); }
                return true;
            }
            catch (Exception ex)
            {
                OnError?.Invoke(ex);
                return false;
            }
            }
            public bool Ping()
            {
            try
            {
                var ping = new System.Net.NetworkInformation.Ping();
                var reply = ping.Send(_serverIP, NetworkConfig.PING_TIMEOUT_MS);
                return reply.Status == System.Net.NetworkInformation.IPStatus.Success;
            }
            catch { return false; }
            }
            private bool PerformHandshake()
            {
            try
            {
                string handshake = Protocol.BuildMessage(
                Protocol.HANDSHAKE,
                _atmId,
                _atmType,
                _clientVersion
                );
                SendString(handshake);
                string response = ReceiveString(5000);
                if (string.IsNullOrEmpty(response))
                {
                OnLog?.Invoke("[Network] Handshake timeout - no response");
                return false;
                }
                string[] parts = Protocol.ParseMessage(response);
                if (parts.Length > 0 && parts[0] == Protocol.HANDSHAKE_ACK)
                {
                OnLog?.Invoke("[Network] Handshake successful");
                return true;
                }
                OnLog?.Invoke("[Network] Handshake rejected: " + response);
                return false;
            }
            catch (Exception ex)
            {
                OnLog?.Invoke("[Network] Handshake error: " + ex.Message);
                return false;
            }
            }
            private void ReceiveLoop()
            {
            byte[] buffer = new byte[NetworkConfig.SOCKET_BUFFER_SIZE];
            StringBuilder messageBuilder = new StringBuilder();
            while (_isRunning && _isConnected)
            {
                try
                {
                if (_stream == null || !_tcpClient.Connected) break;
                if (!_stream.DataAvailable)
                {
                    Thread.Sleep(50);
                    continue;
                }
                int bytesRead = _stream.Read(buffer, 0, buffer.Length);
                if (bytesRead == 0)
                {
                    HandleConnectionLost();
                    break;
                }
                string received = Encoding.UTF8.GetString(buffer, 0, bytesRead);
                messageBuilder.Append(received);
                string fullMessage = messageBuilder.ToString();
                int newlineIdx;
                while ((newlineIdx = fullMessage.IndexOf('\n')) >= 0)
                {
                    string msg = fullMessage.Substring(0, newlineIdx).Trim();
                    fullMessage = fullMessage.Substring(newlineIdx + 1);
                    if (!string.IsNullOrEmpty(msg))
                    {
                    ProcessReceivedMessage(msg);
                    }
                }
                messageBuilder.Clear();
                if (fullMessage.Length > 0) messageBuilder.Append(fullMessage);
                }
                catch (Exception ex)
                {
                if (_isRunning)
                {
                    OnError?.Invoke(ex);
                    HandleConnectionLost();
                }
                break;
                }
            }
            }
            private void ProcessReceivedMessage(string message)
            {
            string[] parts = Protocol.ParseMessage(message);
            if (parts.Length == 0) return;
            string msgType = parts[0];
            switch (msgType)
            {
                case Protocol.HEARTBEAT_ACK:
                _lastHeartbeat = DateTime.Now;
                break;
                case Protocol.DATA_ACK:
                OnLog?.Invoke("[Network] Data acknowledged by server");
                break;
                case Protocol.STATUS_REQUEST:
                OnMessageReceived?.Invoke(message);
                break;
                case Protocol.CMD_RESTART:
                case Protocol.CMD_SCREENSHOT:
                case Protocol.CMD_TIMESYNC:
                case Protocol.CMD_SHUTDOWN:
                case Protocol.CMD_CHANGE_PASSWORD:
                case Protocol.CMD_SEND_IMAGE:
                case Protocol.CMD_UPDATE_CONFIG:
                case Protocol.CMD_GET_SYSINFO:
                OnCommandReceived?.Invoke(msgType, parts);
                OnLog?.Invoke("[Network] Command received: " + msgType);
                break;
                default:
