        public sealed class NetworkEngine : IDisposable
        {
        private enum CircuitBreakerState
        {
            Closed,
            Open,
            HalfOpen
        }
    
        private readonly string _serverIp;
        private readonly int _serverPort;
        private readonly string _atmId;
        private readonly string _atmType;
        private readonly RetryPolicy _reconnectPolicy;
        private readonly NetworkTransportOptions _transportOptions;
        private readonly SemaphoreSlim _sendGate = new(1, 1);
        private readonly object _circuitLock = new();
        private readonly object _latencyLock = new();
        private TcpClient? _client;
        private Stream? _stream;
        private CancellationTokenSource? _cts;
        private volatile bool _running;
        private volatile bool _usingTlsTransport;
        private CircuitBreakerState _circuitState = CircuitBreakerState.Closed;
        private int _consecutiveConnectFailures;
        private int _circuitOpenCycles;
        private int _lastNetworkLatencyMs = -1;
        private DateTime _nextCircuitProbeUtc = DateTime.MinValue;
        private DateTime _lastLatencyProbeUtc = DateTime.MinValue;
        private int _heartbeatInFlight;
        private long _lastHeartbeatSentTicks;
        private static readonly TimeSpan CircuitBaseWindow = TimeSpan.FromSeconds(15);
        private static readonly TimeSpan CircuitMaxWindow = TimeSpan.FromMinutes(2);
        private static readonly TimeSpan LatencyProbeInterval = TimeSpan.FromSeconds(20);
        private static readonly TimeSpan MinHeartbeatGap = TimeSpan.FromSeconds(5);
    
        public NetworkEngine(
            string serverIp,
            int serverPort,
            string atmId,
            string atmType,
            string networkType = "LAN",
            JournalOutbox? outbox = null,
            NetworkTransportOptions? transportOptions = null)
        {
            _serverIp = serverIp;
            _serverPort = serverPort;
            _atmId = atmId;
            _atmType = atmType;
            NetworkType = networkType;
            Outbox = outbox ?? new JournalOutbox();
            _reconnectPolicy = RetryPolicy.ForNetwork(networkType);
            _transportOptions = transportOptions ?? NetworkTransportOptions.FromEnvironment();
        }
    
        public string NetworkType { get; }
        public JournalOutbox Outbox { get; }
        public string SessionId { get; private set; } = string.Empty;
        public bool IsConnected => _client?.Connected == true;
        public int ReconnectAttempts { get; private set; }
        public DateTime ConnectedAt { get; private set; }
        public long TotalBytesSent { get; private set; }
        public long TotalBytesReceived { get; private set; }
        public double SpeedKBs { get; private set; }
    
        public event EventHandler<bool>? OnConnectionChanged;
        public event EventHandler<string>? OnSessionEstablished;
        public event EventHandler<EJMessage>? OnMessageReceived;
        public event EventHandler<string>? OnJournalAcknowledged;
        public event EventHandler<HandshakeResponse>? OnHandshakeResponse;
        public event EventHandler<HeartbeatAck>? OnHeartbeatAck;
        public event EventHandler<ChunkAck>? OnChunkAck;
        public event EventHandler<string>? OnError;
        public event EventHandler<string>? OnLog;
    
        public bool Connect()
        {
            _running = true;
            _cts?.Dispose();
            _cts = new CancellationTokenSource();
    
            if (!TryEnterConnectWindow(out var waitFor))
            {
            Log($"Connection circuit open; next probe in {Math.Max(1, waitFor.TotalSeconds):F0}s.");
            return false;
            }
    
            for (var attempt = 1; attempt <= _reconnectPolicy.MaxAttempts; attempt++)
            {
            try
            {
                ReconnectAttempts = attempt;
                if (attempt == 1 && _consecutiveConnectFailures > 0)
                {
                var initialJitterMs = Random.Shared.Next(250, 1500);
                Thread.Sleep(initialJitterMs);
                }
    
                _client = new TcpClient { ReceiveTimeout = AppConstants.SocketTimeoutMs, SendTimeout = AppConstants.SocketTimeoutMs, NoDelay = true };
                var result = _client.BeginConnect(_serverIp, _serverPort, null, null);
                if (!result.AsyncWaitHandle.WaitOne(AppConstants.SocketTimeoutMs))
                throw new TimeoutException("Connection timed out.");
    
                _client.EndConnect(result);
                var stream = _client.GetStream();
                _stream = UpgradeStreamIfRequested(stream);
                SessionId = Guid.NewGuid().ToString("N");
                ConnectedAt = DateTime.UtcNow;
                OnConnectSuccess();
                OnConnectionChanged?.Invoke(this, true);
                OnSessionEstablished?.Invoke(this, SessionId);
                Log(_usingTlsTransport
                ? $"Connected to {_serverIp}:{_serverPort} over TLS."
                : $"Connected to {_serverIp}:{_serverPort}");
                SendMessage(CommunicationProtocol.BuildHandshake(_atmId, _atmType, AppConstants.AppVersion));
                _ = Task.Run(() => ReceiveLoopAsync(_cts.Token), _cts.Token);
                _ = Task.Run(() => HeartbeatLoopAsync(_cts.Token), _cts.Token);
                return true;
            }
            catch (Exception ex)
            {
                ReportError("Connect", ex);
                var circuitOpened = OnConnectFailure(ex);
                Disconnect();
                if (!_running || attempt >= _reconnectPolicy.MaxAttempts || circuitOpened)
                break;
    
                var retryDelayMs = ComputeRetryDelayWithJitter(attempt);
                Thread.Sleep(retryDelayMs);
            }
            }
    
            return false;
        }
    
        public void SendMessage(byte[] frame)
        {
            if (_stream is null || !IsConnected)
            return;
    
            _sendGate.Wait();
            try
            {
            _stream.Write(frame, 0, frame.Length);
            _stream.Flush();
            TotalBytesSent += frame.Length;
            SpeedKBs = frame.Length / 1024.0;
            }
            finally
            {
            _sendGate.Release();
            }
        }
    
        public async Task SendMessageAsync(byte[] frame, CancellationToken cancellationToken = default)
        {
            if (_stream is null || !IsConnected)
            return;
    
            await _sendGate.WaitAsync(cancellationToken).ConfigureAwait(false);
            try
            {
            await _stream.WriteAsync(frame.AsMemory(0, frame.Length), cancellationToken).ConfigureAwait(false);
            await _stream.FlushAsync(cancellationToken).ConfigureAwait(false);
            TotalBytesSent += frame.Length;
            SpeedKBs = frame.Length / 1024.0;
            }
            finally
            {
            _sendGate.Release();
            }
        }
    
        public void DispatchReceived(EJMessage message)
        {
            TotalBytesReceived += message.Payload.Length;
            OnMessageReceived?.Invoke(this, message);
        }
    
        public void SendHandshake(HandshakeRequest request)
        {
            if (request is null)
            throw new ArgumentNullException(nameof(request));
    
            SendMessage(CommunicationProtocol.BuildHandshake(request.AtmId, _atmType, request.ClientVersion));
        }
    
        public void SendHeartbeat(HeartbeatPayload payload)
        {
            if (payload is null)
            throw new ArgumentNullException(nameof(payload));
    
            if (!TryEnterHeartbeatSend())
            return;
    
            try
            {
            if (!IsConnected)
                return;
    
            var frame = CommunicationProtocol.BuildHeartbeat(payload.AtmId, BuildHeartbeatPayloadJson(payload));
            SendMessage(frame);
            MarkHeartbeatSentNow();
            }
            finally
            {
            ExitHeartbeatSend();
            }
        }
    
        public void SendChunk(ChunkPayload payload)
        {
            if (payload is null)
            throw new ArgumentNullException(nameof(payload));
    
            SendMessage(CommunicationProtocol.BuildChunk(payload.Sequence, payload.Data));
        }
    
        public void SendTransferComplete(TransferComplete complete)
        {
            if (complete is null)
            throw new ArgumentNullException(nameof(complete));
    
            SendMessage(CommunicationProtocol.BuildComplete(complete.FileName, string.Empty, complete.Sha256));
        }
    
        public bool SendJournalFile(string fileName, byte[] data, long offset, string checksum)
        {
            if (!IsConnected)
            {
            Outbox.Enqueue(_atmId, fileName, data, offset, checksum);
            return false;
            }
    
            SendMessage(CommunicationProtocol.BuildStartFile(_atmId, fileName, data.Length, offset, checksum));
            var chunkSize = GetEffectiveChunkSizeBytes();
            var totalChunks = (int)Math.Ceiling(data.Length / (double)chunkSize);
            for (var i = 0; i < totalChunks; i++)
            {
            var chunkOffset = i * chunkSize;
            var chunkLen = Math.Min(chunkSize, data.Length - chunkOffset);
            var chunk = new byte[chunkLen];
            Buffer.BlockCopy(data, chunkOffset, chunk, 0, chunkLen);
            SendMessage(CommunicationProtocol.BuildChunk(i, chunk));
            }
            SendMessage(CommunicationProtocol.BuildComplete(fileName, checksum, SecurityHelper.SHA256Hash(data)));
            return true;
        }
    
        public async Task<bool> SendJournalFileAsync(string fileName, byte[] data, long offset, string checksum, CancellationToken cancellationToken = default)
        {
            if (!IsConnected)
            {
            Outbox.Enqueue(_atmId, fileName, data, offset, checksum);
            return false;
            }
    
            await SendMessageAsync(CommunicationProtocol.BuildStartFile(_atmId, fileName, data.Length, offset, checksum), cancellationToken).ConfigureAwait(false);
            var chunkSize = GetEffectiveChunkSizeBytes();
            var totalChunks = (int)Math.Ceiling(data.Length / (double)chunkSize);
            for (var i = 0; i < totalChunks; i++)
            {
            cancellationToken.ThrowIfCancellationRequested();
            var chunkOffset = i * chunkSize;
            var chunkLen = Math.Min(chunkSize, data.Length - chunkOffset);
            var chunk = new byte[chunkLen];
            Buffer.BlockCopy(data, chunkOffset, chunk, 0, chunkLen);
            await SendMessageAsync(CommunicationProtocol.BuildChunk(i, chunk), cancellationToken).ConfigureAwait(false);
            }
            await SendMessageAsync(CommunicationProtocol.BuildComplete(fileName, checksum, SecurityHelper.SHA256Hash(data)), cancellationToken).ConfigureAwait(false);
            return true;
        }
    
        public void Disconnect()
        {
            _running = false;
            try { _cts?.Cancel(); } catch { }
            try { _stream?.Dispose(); } catch { }
            try { _client?.Close(); } catch { }
            _stream = null;
            _client = null;
            OnConnectionChanged?.Invoke(this, false);
        }
    
        private void Log(string message) => OnLog?.Invoke(this, message);
        private void ReportError(string context, Exception ex) => OnError?.Invoke(this, $"{context}: {ex.Message}");
    
        private bool OnConnectFailure(Exception ex)
        {
            string? openedMessage = null;
            var opened = false;
            lock (_circuitLock)
            {
            _consecutiveConnectFailures++;
            if (_consecutiveConnectFailures < 4)
                return false;
    
            _circuitState = CircuitBreakerState.Open;
            _circuitOpenCycles++;
            var exponent = Math.Min(6, _circuitOpenCycles - 1);
            var scaled = CircuitBaseWindow.TotalMilliseconds * Math.Pow(2, exponent);
            var jitterMs = Random.Shared.Next(250, 3000);
            var openMs = Math.Min(CircuitMaxWindow.TotalMilliseconds, scaled + jitterMs);
            _nextCircuitProbeUtc = DateTime.UtcNow.AddMilliseconds(openMs);
            openedMessage = $"Circuit opened after {_consecutiveConnectFailures} failures. reason={ex.GetType().Name} nextProbe={_nextCircuitProbeUtc:O}";
            opened = true;
            }
    
            if (!string.IsNullOrWhiteSpace(openedMessage))
            Log(openedMessage);
    
            return opened;
        }
    
        private void OnConnectSuccess()
        {
            lock (_circuitLock)
            {
            _consecutiveConnectFailures = 0;
            _circuitOpenCycles = 0;
            _nextCircuitProbeUtc = DateTime.MinValue;
            _circuitState = CircuitBreakerState.Closed;
            }
        }
    
        private bool TryEnterConnectWindow(out TimeSpan waitFor)
        {
            lock (_circuitLock)
            {
            var now = DateTime.UtcNow;
            if (_circuitState == CircuitBreakerState.Open)
            {
                if (_nextCircuitProbeUtc > now)
                {
                waitFor = _nextCircuitProbeUtc - now;
                return false;
                }
    
                _circuitState = CircuitBreakerState.HalfOpen;
                waitFor = TimeSpan.Zero;
                return true;
            }
    
            waitFor = TimeSpan.Zero;
            return true;
            }
        }
    
        private int ComputeRetryDelayWithJitter(int attempt)
        {
            var baseDelay = _reconnectPolicy.ComputeDelay(attempt);
            var herdJitter = Random.Shared.Next(200, 2000);
            return checked(baseDelay + herdJitter);
        }
    
        private Stream UpgradeStreamIfRequested(NetworkStream networkStream)
        {
            _usingTlsTransport = false;
            if (!_transportOptions.EnableTlsTransport)
            return networkStream;
    
            try
            {
            var ssl = new SslStream(
                networkStream,
                leaveInnerStreamOpen: false,
                (_, cert, chain, errors) =>
                {
                if (_transportOptions.AllowUntrustedTlsCertificate)
                    return true;
                return errors == SslPolicyErrors.None;
                });
    
            var sslProtocols = SslProtocols.Tls13 | SslProtocols.Tls12;
            ssl.AuthenticateAsClient(_serverIp, null, sslProtocols, checkCertificateRevocation: true);
            _usingTlsTransport = true;
            return ssl;
            }
            catch (Exception ex)
            {
            if (_transportOptions.RequireTlsTransport)
                throw new AuthenticationException("TLS is required but handshake failed.", ex);
    
            Log("TLS handshake failed, fallback to TCP stream: " + ex.Message);
            return networkStream;
            }
        }
    
        private int GetEffectiveChunkSizeBytes()
        {
            var baseSize = AppConstants.ChunkSizeBytes;
            if (!_transportOptions.EnableAdaptiveChunking)
            return baseSize;
    
            var latencyMs = GetRecentNetworkLatencyMs();
            if (latencyMs < 0)
            return baseSize;
    
            var weakThreshold = Math.Clamp(_transportOptions.WeakNetworkLatencyMs, 120, 3000);
            if (latencyMs >= weakThreshold * 2)
            return Math.Max(8 * 1024, baseSize / 4);
            if (latencyMs >= weakThreshold)
            return Math.Max(16 * 1024, baseSize / 2);
            if (latencyMs >= weakThreshold / 2)
            return Math.Max(32 * 1024, (baseSize * 3) / 4);
    
            return baseSize;
        }
    
        private int GetRecentNetworkLatencyMs()
        {
            lock (_latencyLock)
            {
            var now = DateTime.UtcNow;
            if (_lastNetworkLatencyMs >= 0 && now - _lastLatencyProbeUtc <= LatencyProbeInterval)
                return _lastNetworkLatencyMs;
            }
    
            var measured = ProbeNetworkLatencyMs();
            lock (_latencyLock)
            {
            _lastNetworkLatencyMs = measured;
            _lastLatencyProbeUtc = DateTime.UtcNow;
            return _lastNetworkLatencyMs;
            }
        }
    
        private int ProbeNetworkLatencyMs()
        {
            try
            {
            using var ping = new Ping();
            var reply = ping.Send(_serverIp, 1200);
            if (reply?.Status == IPStatus.Success)
                return (int)Math.Clamp(reply.RoundtripTime, 1, int.MaxValue);
            }
            catch
            {
            // Best effort QoS signal.
            }
    
            return -1;
        }
    
        private async Task ReceiveLoopAsync(CancellationToken cancellationToken)
        {
            while (!cancellationToken.IsCancellationRequested && _stream is not null && IsConnected)
            {
            try
            {
                var message = await Task.Run(() => CommunicationProtocol.ReadMessage(_stream), cancellationToken).ConfigureAwait(false);
                if (message.Type == CommunicationProtocol.MsgType.HandshakeAck)
                {
                var parts = message.Text.Split('|');
                if (parts.Length >= 2)
                {
                    SessionId = parts[1];
                    OnSessionEstablished?.Invoke(this, SessionId);
                }
    
                OnHandshakeResponse?.Invoke(this, new HandshakeResponse(
                    Accepted: true,
                    ServerSessionId: SessionId,
                    RejectionReason: null,
                    ServerTimeUtc: DateTime.UtcNow,
                    CommandPendingCount: 0,
                    HeartbeatInterval: TimeSpan.FromSeconds(AppConstants.HeartbeatIntervalSec)));
                Log($"Server acknowledged session {SessionId}.");
                }
                else if (message.Type == CommunicationProtocol.MsgType.HeartbeatAck)
                {
                if (!CommunicationProtocol.TryParseHeartbeatAck(message.Text, out var heartbeatAck))
                {
                    heartbeatAck = new HeartbeatAck(
                    ServerTimeUtc: DateTime.UtcNow,
                    CommandsPendingCount: 0,
                    RequestImmediateSync: false,
                    ServerMessage: message.Text);
                }
    
                OnHeartbeatAck?.Invoke(this, heartbeatAck);
                Log($"Heartbeat acknowledged. pending={heartbeatAck.CommandsPendingCount}; immediateSync={heartbeatAck.RequestImmediateSync}.");
                }
                else if (message.Type == CommunicationProtocol.MsgType.ChunkAck)
                {
                int sequence = 0;
                _ = int.TryParse(message.Text, out sequence);
                OnChunkAck?.Invoke(this, new ChunkAck(
                    TransferId: Guid.Empty,
                    Sequence: sequence,
                    Ok: true,
                    NextExpectedOffset: 0,
                    ServerHash: null));
                }
                else if (message.Type == CommunicationProtocol.MsgType.JournalAck)
                {
                OnJournalAcknowledged?.Invoke(this, message.Text ?? string.Empty);
                Log($"Journal acknowledged: {message.Text}");
                }
                else
                {
                DispatchReceived(message);
                }
            }
            catch (OperationCanceledException)
            {
                break;
            }
            catch (ObjectDisposedException)
            {
                break;
            }
            catch (IOException ex)
            {
                ReportError("Receive", ex);
                Disconnect();
                break;
            }
            catch (Exception ex)
            {
                ReportError("Receive", ex);
                Disconnect();
                break;
            }
            }
        }
    
        private async Task HeartbeatLoopAsync(CancellationToken cancellationToken)
        {
            while (!cancellationToken.IsCancellationRequested && _running)
            {
            try
            {
                await Task.Delay(TimeSpan.FromSeconds(AppConstants.HeartbeatIntervalSec), cancellationToken).ConfigureAwait(false);
                if (IsConnected)
                {
                if (WasHeartbeatSentRecently(MinHeartbeatGap))
                    continue;
    
                await SendHeartbeatAsync(CreateBaselineHeartbeatPayload(), cancellationToken).ConfigureAwait(false);
                }
            }
            catch (OperationCanceledException)
            {
                break;
            }
            catch (Exception ex)
            {
                ReportError("Heartbeat", ex);
            }
            }
        }
    
        private async Task SendHeartbeatAsync(HeartbeatPayload payload, CancellationToken cancellationToken)
        {
            if (!TryEnterHeartbeatSend())
            return;
    
            try
            {
            if (!IsConnected)
                return;
    
            var frame = CommunicationProtocol.BuildHeartbeat(payload.AtmId, BuildHeartbeatPayloadJson(payload));
            await SendMessageAsync(frame, cancellationToken).ConfigureAwait(false);
            MarkHeartbeatSentNow();
            }
            finally
            {
            ExitHeartbeatSend();
            }
        }
    
        private HeartbeatPayload CreateBaselineHeartbeatPayload()
        {
            return new HeartbeatPayload(
            AtmId: _atmId,
            SessionId: string.IsNullOrWhiteSpace(SessionId) ? null : SessionId,
            TimestampUtc: DateTime.UtcNow,
            OutboxCount: Outbox.Count,
            FileWatcherHealthy: true,
            CpuPercent: 0,
            MemoryMb: 0,
            DiskFreeMb: 0,
            LastJournalOffset: 0,
            LastError: null,
            AgentState: IsConnected ? "connected" : "disconnected",
            WatcherState: "unknown");
        }
    
        private static string BuildHeartbeatPayloadJson(HeartbeatPayload payload)
        {
            return JsonSerializer.Serialize(new
            {
            ATM_ID = payload.AtmId,
            SessionId = payload.SessionId,
            TimestampUtc = payload.TimestampUtc.ToString("O"),
            AgentState = payload.AgentState,
            OutboxCount = payload.OutboxCount,
            LastJournalOffset = payload.LastJournalOffset,
            CPU = payload.CpuPercent,
            Memory = payload.MemoryMb,
            Disk = payload.DiskFreeMb,
            WatcherState = payload.WatcherState,
            FileWatcherHealthy = payload.FileWatcherHealthy,
            LastError = payload.LastError
            });
        }
    
        private bool TryEnterHeartbeatSend() => Interlocked.Exchange(ref _heartbeatInFlight, 1) == 0;
        private void ExitHeartbeatSend() => Interlocked.Exchange(ref _heartbeatInFlight, 0);
    
        private void MarkHeartbeatSentNow() => Interlocked.Exchange(ref _lastHeartbeatSentTicks, DateTime.UtcNow.Ticks);
    
        private bool WasHeartbeatSentRecently(TimeSpan window)
        {
            var ticks = Interlocked.Read(ref _lastHeartbeatSentTicks);
            if (ticks <= 0)
            return false;
    
            var lastSentUtc = new DateTime(ticks, DateTimeKind.Utc);
            return DateTime.UtcNow - lastSentUtc < window;
        }
    
        public void Dispose()
        {
            Disconnect();
            _cts?.Dispose();
            _sendGate.Dispose();
        }
        }
        public class NetworkEngine { public bool IsRunning { get; private set; } }
        public sealed class NetworkEngine : IDisposable
        {
        private enum CircuitBreakerState
        {
            Closed,
            Open,
            HalfOpen
        }
    
        private readonly string _serverIp;
        private readonly int _serverPort;
        private readonly string _atmId;
        private readonly string _atmType;
        private readonly RetryPolicy _reconnectPolicy;
        private readonly NetworkTransportOptions _transportOptions;
        private readonly SemaphoreSlim _sendGate = new(1, 1);
        private readonly object _circuitLock = new();
        private readonly object _latencyLock = new();
        private TcpClient? _client;
        private Stream? _stream;
        private CancellationTokenSource? _cts;
        private volatile bool _running;
        private volatile bool _usingTlsTransport;
        private CircuitBreakerState _circuitState = CircuitBreakerState.Closed;
        private int _consecutiveConnectFailures;
        private int _circuitOpenCycles;
        private int _lastNetworkLatencyMs = -1;
        private DateTime _nextCircuitProbeUtc = DateTime.MinValue;
        private DateTime _lastLatencyProbeUtc = DateTime.MinValue;
        private static readonly TimeSpan CircuitBaseWindow = TimeSpan.FromSeconds(15);
        private static readonly TimeSpan CircuitMaxWindow = TimeSpan.FromMinutes(2);
        private static readonly TimeSpan LatencyProbeInterval = TimeSpan.FromSeconds(20);
    
        public NetworkEngine(
            string serverIp,
            int serverPort,
            string atmId,
            string atmType,
            string networkType = "LAN",
            JournalOutbox? outbox = null,
            NetworkTransportOptions? transportOptions = null)
        {
            _serverIp = serverIp;
            _serverPort = serverPort;
            _atmId = atmId;
            _atmType = atmType;
            NetworkType = networkType;
            Outbox = outbox ?? new JournalOutbox();
            _reconnectPolicy = RetryPolicy.ForNetwork(networkType);
            _transportOptions = transportOptions ?? NetworkTransportOptions.FromEnvironment();
        }
    
        public string NetworkType { get; }
        public JournalOutbox Outbox { get; }
        public string SessionId { get; private set; } = string.Empty;
        public bool IsConnected => _client?.Connected == true;
        public int ReconnectAttempts { get; private set; }
        public DateTime ConnectedAt { get; private set; }
        public long TotalBytesSent { get; private set; }
        public long TotalBytesReceived { get; private set; }
        public double SpeedKBs { get; private set; }
    
        public event EventHandler<bool>? OnConnectionChanged;
        public event EventHandler<string>? OnSessionEstablished;
        public event EventHandler<EJMessage>? OnMessageReceived;
        public event EventHandler<string>? OnJournalAcknowledged;
        public event EventHandler<string>? OnError;
        public event EventHandler<string>? OnLog;
    
        public bool Connect()
        {
            _running = true;
            _cts?.Dispose();
            _cts = new CancellationTokenSource();
    
            if (!TryEnterConnectWindow(out var waitFor))
            {
            Log($"Connection circuit open; next probe in {Math.Max(1, waitFor.TotalSeconds):F0}s.");
            return false;
            }
    
            for (var attempt = 1; attempt <= _reconnectPolicy.MaxAttempts; attempt++)
            {
            try
            {
                ReconnectAttempts = attempt;
                if (attempt == 1 && _consecutiveConnectFailures > 0)
                {
                var initialJitterMs = Random.Shared.Next(250, 1500);
                Thread.Sleep(initialJitterMs);
                }
    
                _client = new TcpClient { ReceiveTimeout = AppConstants.SocketTimeoutMs, SendTimeout = AppConstants.SocketTimeoutMs, NoDelay = true };
                var result = _client.BeginConnect(_serverIp, _serverPort, null, null);
                if (!result.AsyncWaitHandle.WaitOne(AppConstants.SocketTimeoutMs))
                throw new TimeoutException("Connection timed out.");
    
                _client.EndConnect(result);
                var stream = _client.GetStream();
                _stream = UpgradeStreamIfRequested(stream);
                SessionId = Guid.NewGuid().ToString("N");
                ConnectedAt = DateTime.UtcNow;
                OnConnectSuccess();
                OnConnectionChanged?.Invoke(this, true);
                OnSessionEstablished?.Invoke(this, SessionId);
                Log(_usingTlsTransport
                ? $"Connected to {_serverIp}:{_serverPort} over TLS."
                : $"Connected to {_serverIp}:{_serverPort}");
                SendMessage(CommunicationProtocol.BuildHandshake(_atmId, _atmType, AppConstants.AppVersion));
                _ = Task.Run(() => ReceiveLoopAsync(_cts.Token), _cts.Token);
                _ = Task.Run(() => HeartbeatLoopAsync(_cts.Token), _cts.Token);
                return true;
            }
            catch (Exception ex)
            {
                ReportError("Connect", ex);
                var circuitOpened = OnConnectFailure(ex);
                Disconnect();
                if (!_running || attempt >= _reconnectPolicy.MaxAttempts || circuitOpened)
                break;
    
                var retryDelayMs = ComputeRetryDelayWithJitter(attempt);
                Thread.Sleep(retryDelayMs);
            }
            }
    
            return false;
        }
    
        public void SendMessage(byte[] frame)
        {
            if (_stream is null || !IsConnected)
            return;
    
            _sendGate.Wait();
            try
            {
            _stream.Write(frame, 0, frame.Length);
            _stream.Flush();
            TotalBytesSent += frame.Length;
            SpeedKBs = frame.Length / 1024.0;
            }
            finally
            {
            _sendGate.Release();
            }
        }
    
        public async Task SendMessageAsync(byte[] frame, CancellationToken cancellationToken = default)
        {
            if (_stream is null || !IsConnected)
            return;
    
            await _sendGate.WaitAsync(cancellationToken).ConfigureAwait(false);
            try
            {
            await _stream.WriteAsync(frame.AsMemory(0, frame.Length), cancellationToken).ConfigureAwait(false);
            await _stream.FlushAsync(cancellationToken).ConfigureAwait(false);
            TotalBytesSent += frame.Length;
            SpeedKBs = frame.Length / 1024.0;
            }
            finally
            {
            _sendGate.Release();
            }
        }
    
        public void DispatchReceived(EJMessage message)
        {
            TotalBytesReceived += message.Payload.Length;
            OnMessageReceived?.Invoke(this, message);
        }
    
        public bool SendJournalFile(string fileName, byte[] data, long offset, string checksum)
        {
            if (!IsConnected)
            {
            Outbox.Enqueue(_atmId, fileName, data, offset, checksum);
            return false;
            }
    
            SendMessage(CommunicationProtocol.BuildStartFile(_atmId, fileName, data.Length, offset, checksum));
            var chunkSize = GetEffectiveChunkSizeBytes();
            var totalChunks = (int)Math.Ceiling(data.Length / (double)chunkSize);
            for (var i = 0; i < totalChunks; i++)
            {
            var chunkOffset = i * chunkSize;
            var chunkLen = Math.Min(chunkSize, data.Length - chunkOffset);
            var chunk = new byte[chunkLen];
            Buffer.BlockCopy(data, chunkOffset, chunk, 0, chunkLen);
            SendMessage(CommunicationProtocol.BuildChunk(i, chunk));
            }
            SendMessage(CommunicationProtocol.BuildComplete(fileName, checksum, SecurityHelper.SHA256Hash(data)));
            return true;
        }
    
        public async Task<bool> SendJournalFileAsync(string fileName, byte[] data, long offset, string checksum, CancellationToken cancellationToken = default)
        {
            if (!IsConnected)
            {
            Outbox.Enqueue(_atmId, fileName, data, offset, checksum);
            return false;
            }
    
            await SendMessageAsync(CommunicationProtocol.BuildStartFile(_atmId, fileName, data.Length, offset, checksum), cancellationToken).ConfigureAwait(false);
            var chunkSize = GetEffectiveChunkSizeBytes();
            var totalChunks = (int)Math.Ceiling(data.Length / (double)chunkSize);
            for (var i = 0; i < totalChunks; i++)
            {
            cancellationToken.ThrowIfCancellationRequested();
            var chunkOffset = i * chunkSize;
            var chunkLen = Math.Min(chunkSize, data.Length - chunkOffset);
            var chunk = new byte[chunkLen];
            Buffer.BlockCopy(data, chunkOffset, chunk, 0, chunkLen);
            await SendMessageAsync(CommunicationProtocol.BuildChunk(i, chunk), cancellationToken).ConfigureAwait(false);
            }
            await SendMessageAsync(CommunicationProtocol.BuildComplete(fileName, checksum, SecurityHelper.SHA256Hash(data)), cancellationToken).ConfigureAwait(false);
            return true;
        }
    
        public void Disconnect()
        {
            _running = false;
            try { _cts?.Cancel(); } catch { }
            try { _stream?.Dispose(); } catch { }
            try { _client?.Close(); } catch { }
            _stream = null;
            _client = null;
            OnConnectionChanged?.Invoke(this, false);
        }
    
        private void Log(string message) => OnLog?.Invoke(this, message);
        private void ReportError(string context, Exception ex) => OnError?.Invoke(this, $"{context}: {ex.Message}");
    
        private bool OnConnectFailure(Exception ex)
        {
            string? openedMessage = null;
            var opened = false;
            lock (_circuitLock)
            {
            _consecutiveConnectFailures++;
            if (_consecutiveConnectFailures < 4)
                return false;
    
            _circuitState = CircuitBreakerState.Open;
            _circuitOpenCycles++;
            var exponent = Math.Min(6, _circuitOpenCycles - 1);
            var scaled = CircuitBaseWindow.TotalMilliseconds * Math.Pow(2, exponent);
            var jitterMs = Random.Shared.Next(250, 3000);
            var openMs = Math.Min(CircuitMaxWindow.TotalMilliseconds, scaled + jitterMs);
            _nextCircuitProbeUtc = DateTime.UtcNow.AddMilliseconds(openMs);
            openedMessage = $"Circuit opened after {_consecutiveConnectFailures} failures. reason={ex.GetType().Name} nextProbe={_nextCircuitProbeUtc:O}";
            opened = true;
            }
    
            if (!string.IsNullOrWhiteSpace(openedMessage))
            Log(openedMessage);
    
            return opened;
        }
    
        private void OnConnectSuccess()
        {
            lock (_circuitLock)
            {
            _consecutiveConnectFailures = 0;
            _circuitOpenCycles = 0;
            _nextCircuitProbeUtc = DateTime.MinValue;
            _circuitState = CircuitBreakerState.Closed;
            }
        }
    
        private bool TryEnterConnectWindow(out TimeSpan waitFor)
        {
            lock (_circuitLock)
            {
            var now = DateTime.UtcNow;
            if (_circuitState == CircuitBreakerState.Open)
            {
                if (_nextCircuitProbeUtc > now)
                {
                waitFor = _nextCircuitProbeUtc - now;
                return false;
                }
    
                _circuitState = CircuitBreakerState.HalfOpen;
                waitFor = TimeSpan.Zero;
                return true;
            }
    
            waitFor = TimeSpan.Zero;
            return true;
            }
        }
    
        private int ComputeRetryDelayWithJitter(int attempt)
        {
            var baseDelay = _reconnectPolicy.ComputeDelay(attempt);
            var herdJitter = Random.Shared.Next(200, 2000);
            return checked(baseDelay + herdJitter);
        }
    
        private Stream UpgradeStreamIfRequested(NetworkStream networkStream)
        {
            _usingTlsTransport = false;
            if (!_transportOptions.EnableTlsTransport)
            return networkStream;
    
            try
            {
            var ssl = new SslStream(
                networkStream,
                leaveInnerStreamOpen: false,
                (_, cert, chain, errors) =>
                {
                if (_transportOptions.AllowUntrustedTlsCertificate)
                    return true;
                return errors == SslPolicyErrors.None;
                });
    
            var sslProtocols = SslProtocols.Tls13 | SslProtocols.Tls12;
            ssl.AuthenticateAsClient(_serverIp, null, sslProtocols, checkCertificateRevocation: true);
            _usingTlsTransport = true;
            return ssl;
            }
            catch (Exception ex)
            {
            if (_transportOptions.RequireTlsTransport)
                throw new AuthenticationException("TLS is required but handshake failed.", ex);
    
            Log("TLS handshake failed, fallback to TCP stream: " + ex.Message);
            return networkStream;
            }
        }
    
        private int GetEffectiveChunkSizeBytes()
        {
            var baseSize = AppConstants.ChunkSizeBytes;
            if (!_transportOptions.EnableAdaptiveChunking)
            return baseSize;
    
            var latencyMs = GetRecentNetworkLatencyMs();
            if (latencyMs < 0)
            return baseSize;
    
            var weakThreshold = Math.Clamp(_transportOptions.WeakNetworkLatencyMs, 120, 3000);
            if (latencyMs >= weakThreshold * 2)
            return Math.Max(8 * 1024, baseSize / 4);
            if (latencyMs >= weakThreshold)
            return Math.Max(16 * 1024, baseSize / 2);
            if (latencyMs >= weakThreshold / 2)
            return Math.Max(32 * 1024, (baseSize * 3) / 4);
    
            return baseSize;
        }
    
        private int GetRecentNetworkLatencyMs()
        {
            lock (_latencyLock)
            {
            var now = DateTime.UtcNow;
            if (_lastNetworkLatencyMs >= 0 && now - _lastLatencyProbeUtc <= LatencyProbeInterval)
                return _lastNetworkLatencyMs;
            }
    
            var measured = ProbeNetworkLatencyMs();
            lock (_latencyLock)
            {
            _lastNetworkLatencyMs = measured;
            _lastLatencyProbeUtc = DateTime.UtcNow;
            return _lastNetworkLatencyMs;
            }
        }
    
        private int ProbeNetworkLatencyMs()
        {
            try
            {
            using var ping = new Ping();
            var reply = ping.Send(_serverIp, 1200);
            if (reply?.Status == IPStatus.Success)
                return (int)Math.Clamp(reply.RoundtripTime, 1, int.MaxValue);
            }
            catch
            {
            // Best effort QoS signal.
            }
    
            return -1;
        }
    
        private async Task ReceiveLoopAsync(CancellationToken cancellationToken)
        {
            while (!cancellationToken.IsCancellationRequested && _stream is not null && IsConnected)
            {
            try
            {
                var message = await Task.Run(() => CommunicationProtocol.ReadMessage(_stream), cancellationToken).ConfigureAwait(false);
                if (message.Type == CommunicationProtocol.MsgType.HandshakeAck)
                {
                var parts = message.Text.Split('|');
                if (parts.Length >= 2)
                {
                    SessionId = parts[1];
                    OnSessionEstablished?.Invoke(this, SessionId);
                }
                Log($"Server acknowledged session {SessionId}.");
                }
                else if (message.Type == CommunicationProtocol.MsgType.HeartbeatAck)
                {
                Log("Heartbeat acknowledged.");
                }
                else if (message.Type == CommunicationProtocol.MsgType.JournalAck)
                {
                OnJournalAcknowledged?.Invoke(this, message.Text ?? string.Empty);
                Log($"Journal acknowledged: {message.Text}");
                }
                else
                {
                DispatchReceived(message);
                }
            }
            catch (OperationCanceledException)
            {
                break;
            }
            catch (ObjectDisposedException)
            {
                break;
            }
            catch (IOException ex)
            {
                ReportError("Receive", ex);
                Disconnect();
                break;
            }
            catch (Exception ex)
            {
                ReportError("Receive", ex);
                Disconnect();
                break;
            }
            }
        }
    
        private async Task HeartbeatLoopAsync(CancellationToken cancellationToken)
        {
            while (!cancellationToken.IsCancellationRequested && _running)
            {
            try
            {
                await Task.Delay(TimeSpan.FromSeconds(AppConstants.HeartbeatIntervalSec), cancellationToken).ConfigureAwait(false);
                if (IsConnected)
                await SendMessageAsync(CommunicationProtocol.BuildHeartbeat(_atmId, DateTime.UtcNow.ToString("O")), cancellationToken).ConfigureAwait(false);
            }
            catch (OperationCanceledException)
            {
                break;
            }
            catch (Exception ex)
            {
                ReportError("Heartbeat", ex);
            }
            }
        }
    
        public void Dispose()
        {
            Disconnect();
            _cts?.Dispose();
            _sendGate.Dispose();
        }
        }
        /// <summary>
        /// محرك الاتصال الشبكي - يدير الاتصال TCP بين Client و Server
        /// يدعم: Handshake, Heartbeat, Data Transfer, Commands
        /// </summary>
        public class NetworkEngine
        {
            private TcpClient _tcpClient;
            private NetworkStream _stream;
            private Thread _receiveThread;
            private Thread _heartbeatThread;
            private string _serverIP;
            private int _serverPort;
            private string _atmId;
            private string _atmType;
            private string _clientVersion;
            private bool _isConnected;
            private bool _isRunning;
            private DateTime _lastHeartbeat;
            private readonly object _sendLock = new object();
    
            // أحداث
            public event Action OnConnected;
            public event Action OnDisconnected;
            public event Action<string> OnMessageReceived;
            public event Action<string, byte[]> OnDataReceived;
            public event Action<string, string[]> OnCommandReceived;
            public event Action<string> OnLog;
            public event Action<Exception> OnError;
    
            public bool IsConnected { get { return _isConnected; } }
            public DateTime LastHeartbeat { get { return _lastHeartbeat; } }
    
            public NetworkEngine(string atmId, string atmType, string serverIP, int serverPort)
            {
            _atmId = atmId;
            _atmType = atmType;
            _serverIP = serverIP;
            _serverPort = serverPort;
            _clientVersion = AppConstants.APP_VERSION;
            _isConnected = false;
            _isRunning = false;
            }
    
            /// <summary>
            /// بدء الاتصال بالسيرفر
            /// </summary>
            public bool Connect()
            {
            try
            {
                if (_isConnected) return true;
    
                OnLog?.Invoke("[Network] Connecting to " + _serverIP + ":" + _serverPort);
    
                _tcpClient = new TcpClient();
                _tcpClient.ReceiveTimeout = NetworkConfig.CONNECTION_TIMEOUT_MS;
                _tcpClient.SendTimeout = NetworkConfig.CONNECTION_TIMEOUT_MS;
                _tcpClient.ReceiveBufferSize = NetworkConfig.SOCKET_BUFFER_SIZE;
                _tcpClient.SendBufferSize = NetworkConfig.SOCKET_BUFFER_SIZE;
                _tcpClient.NoDelay = true;
    
                var result = _tcpClient.BeginConnect(_serverIP, _serverPort, null, null);
                bool connected = result.AsyncWaitHandle.WaitOne(NetworkConfig.CONNECTION_TIMEOUT_MS);
    
                if (!connected)
                {
                OnLog?.Invoke("[Network] Connection timeout");
                return false;
                }
    
                _tcpClient.EndConnect(result);
                _stream = _tcpClient.GetStream();
    
                // إرسال Handshake
                if (!PerformHandshake())
                {
                Disconnect();
                return false;
                }
    
                _isConnected = true;
                _isRunning = true;
                _lastHeartbeat = DateTime.Now;
    
                // بدء خيط الاستقبال
                _receiveThread = new Thread(ReceiveLoop);
                _receiveThread.IsBackground = true;
                _receiveThread.Start();
    
                // بدء خيط Heartbeat
                _heartbeatThread = new Thread(HeartbeatLoop);
                _heartbeatThread.IsBackground = true;
                _heartbeatThread.Start();
    
                OnLog?.Invoke("[Network] Connected successfully");
                OnConnected?.Invoke();
                return true;
            }
            catch (Exception ex)
            {
                OnLog?.Invoke("[Network] Connection failed: " + ex.Message);
                OnError?.Invoke(ex);
                return false;
            }
            }
    
            /// <summary>
            /// قطع الاتصال
            /// </summary>
            public void Disconnect()
            {
            _isRunning = false;
            _isConnected = false;
    
            try
            {
                if (_stream != null) { _stream.Close(); _stream = null; }
                if (_tcpClient != null) { _tcpClient.Close(); _tcpClient = null; }
            }
            catch { }
    
            OnLog?.Invoke("[Network] Disconnected");
            OnDisconnected?.Invoke();
            }
    
            /// <summary>
            /// إرسال بيانات جورنال إلى السيرفر
            /// </summary>
            public bool SendJournalData(string fileName, byte[] data, string checksum)
            {
            try
            {
                if (!_isConnected) return false;
    
                // بناء الهيدر: EJDATA|ATM_ID|FILENAME|LENGTH|CHECKSUM|TIMESTAMP
                string header = Protocol.BuildMessage(
                Protocol.DATA_JOURNAL,
                _atmId,
                fileName,
                data.Length.ToString(),
                checksum,
                DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss")
                );
    
                lock (_sendLock)
                {
                // إرسال الهيدر
                SendString(header + Protocol.HEADER_END);
    
                // إرسال البيانات
                _stream.Write(data, 0, data.Length);
                _stream.Flush();
    
                // إرسال نهاية البيانات
                byte[] endMarker = Encoding.UTF8.GetBytes(Protocol.DATA_END);
                _stream.Write(endMarker, 0, endMarker.Length);
                _stream.Flush();
                }
    
                OnLog?.Invoke(string.Format("[Network] Sent {0} ({1} bytes)", fileName, data.Length));
                return true;
            }
            catch (Exception ex)
            {
                OnError?.Invoke(ex);
                HandleConnectionLost();
                return false;
            }
            }
    
            /// <summary>
            /// إرسال ملف كامل إلى السيرفر
            /// </summary>
            public bool SendFile(string fileName, byte[] fileData, string checksum)
            {
            try
            {
                if (!_isConnected) return false;
    
                string header = Protocol.BuildMessage(
                Protocol.DATA_FILE,
                _atmId,
                fileName,
                fileData.Length.ToString(),
                checksum,
                DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss")
                );
    
                lock (_sendLock)
                {
                SendString(header + Protocol.HEADER_END);
                _stream.Write(fileData, 0, fileData.Length);
                _stream.Flush();
                byte[] endMarker = Encoding.UTF8.GetBytes(Protocol.DATA_END);
                _stream.Write(endMarker, 0, endMarker.Length);
                _stream.Flush();
                }
    
                OnLog?.Invoke(string.Format("[Network] Sent file {0} ({1} bytes)", fileName, fileData.Length));
                return true;
            }
            catch (Exception ex)
            {
                OnError?.Invoke(ex);
                HandleConnectionLost();
                return false;
            }
            }
    
            /// <summary>
            /// إرسال حالة الصراف
            /// </summary>
            public bool SendStatus(string status, string cscStatus)
            {
            try
            {
                if (!_isConnected) return false;
                string msg = Protocol.BuildMessage(
                Protocol.STATUS_RESPONSE,
                _atmId,
                status,
                cscStatus,
                DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss")
                );
                lock (_sendLock) { SendString(msg); }
                return true;
            }
            catch (Exception ex)
            {
                OnError?.Invoke(ex);
                return false;
            }
            }
    
            /// <summary>
            /// إرسال نتيجة أمر
            /// </summary>
            public bool SendCommandResult(string commandId, bool success, string resultData)
            {
            try
            {
                if (!_isConnected) return false;
                string msg = Protocol.BuildMessage(
                Protocol.CMD_RESULT,
                _atmId,
                commandId,
                success ? "OK" : "FAIL",
                resultData
                );
                lock (_sendLock) { SendString(msg); }
                return true;
            }
            catch (Exception ex)
            {
                OnError?.Invoke(ex);
                return false;
            }
            }
    
            /// <summary>
            /// عمل Ping للسيرفر
            /// </summary>
            public bool Ping()
            {
            try
            {
                var ping = new System.Net.NetworkInformation.Ping();
                var reply = ping.Send(_serverIP, NetworkConfig.PING_TIMEOUT_MS);
                return reply.Status == System.Net.NetworkInformation.IPStatus.Success;
            }
            catch { return false; }
            }
    
            #region Private Methods
    
            private bool PerformHandshake()
            {
            try
            {
                // إرسال: EJLIVE_HANDSHAKE|ATM_ID|ATM_TYPE|VERSION
                string handshake = Protocol.BuildMessage(
                Protocol.HANDSHAKE,
                _atmId,
                _atmType,
                _clientVersion
                );
                SendString(handshake);
    
                // انتظار الرد
                string response = ReceiveString(5000);
                if (string.IsNullOrEmpty(response))
                {
                OnLog?.Invoke("[Network] Handshake timeout - no response");
                return false;
                }
    
                string[] parts = Protocol.ParseMessage(response);
                if (parts.Length > 0 && parts[0] == Protocol.HANDSHAKE_ACK)
                {
                OnLog?.Invoke("[Network] Handshake successful");
                return true;
                }
    
                OnLog?.Invoke("[Network] Handshake rejected: " + response);
                return false;
            }
            catch (Exception ex)
            {
                OnLog?.Invoke("[Network] Handshake error: " + ex.Message);
                return false;
            }
            }
    
            private void ReceiveLoop()
            {
            byte[] buffer = new byte[NetworkConfig.SOCKET_BUFFER_SIZE];
            StringBuilder messageBuilder = new StringBuilder();
    
            while (_isRunning && _isConnected)
            {
                try
                {
                if (_stream == null || !_tcpClient.Connected) break;
                if (!_stream.DataAvailable)
                {
                    Thread.Sleep(50);
                    continue;
                }
    
                int bytesRead = _stream.Read(buffer, 0, buffer.Length);
                if (bytesRead == 0)
                {
                    HandleConnectionLost();
                    break;
                }
    
                string received = Encoding.UTF8.GetString(buffer, 0, bytesRead);
                messageBuilder.Append(received);
    
                // معالجة الرسائل الكاملة
                string fullMessage = messageBuilder.ToString();
                int newlineIdx;
                while ((newlineIdx = fullMessage.IndexOf('\n')) >= 0)
                {
                    string msg = fullMessage.Substring(0, newlineIdx).Trim();
                    fullMessage = fullMessage.Substring(newlineIdx + 1);
    
                    if (!string.IsNullOrEmpty(msg))
                    {
                    ProcessReceivedMessage(msg);
                    }
                }
                messageBuilder.Clear();
                if (fullMessage.Length > 0) messageBuilder.Append(fullMessage);
                }
                catch (Exception ex)
                {
                if (_isRunning)
                {
                    OnError?.Invoke(ex);
                    HandleConnectionLost();
                }
                break;
                }
            }
            }
    
            private void ProcessReceivedMessage(string message)
            {
            string[] parts = Protocol.ParseMessage(message);
            if (parts.Length == 0) return;
    
            string msgType = parts[0];
    
            switch (msgType)
            {
                case Protocol.HEARTBEAT_ACK:
                _lastHeartbeat = DateTime.Now;
                break;
    
                case Protocol.DATA_ACK:
                OnLog?.Invoke("[Network] Data acknowledged by server");
                break;
    
                case Protocol.STATUS_REQUEST:
                OnMessageReceived?.Invoke(message);
                break;
    
                case Protocol.CMD_RESTART:
                case Protocol.CMD_SCREENSHOT:
                case Protocol.CMD_TIMESYNC:
                case Protocol.CMD_SHUTDOWN:
                case Protocol.CMD_CHANGE_PASSWORD:
                case Protocol.CMD_SEND_IMAGE:
                case Protocol.CMD_UPDATE_CONFIG:
                case Protocol.CMD_GET_SYSINFO:
                OnCommandReceived?.Invoke(msgType, parts);
                OnLog?.Invoke("[Network] Command received: " + msgType);
                break;
    
                default:
                OnMessageReceived?.Invoke(message);
                break;
            }
            }
    
            private void HeartbeatLoop()
            {
            while (_isRunning && _isConnected)
            {
                try
                {
                Thread.Sleep(NetworkConfig.HEARTBEAT_INTERVAL_MS);
                if (!_isRunning || !_isConnected) break;
    
                string hb = Protocol.BuildMessage(
                    Protocol.HEARTBEAT,
                    _atmId,
                    DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss")
                );
    
                lock (_sendLock) { SendString(hb); }
                }
                catch (Exception)
                {
                if (_isRunning) HandleConnectionLost();
                break;
                }
            }
            }
    
            private void SendString(string message)
            {
            if (_stream == null) return;
            byte[] data = Encoding.UTF8.GetBytes(message + "\n");
            _stream.Write(data, 0, data.Length);
            _stream.Flush();
            }
    
            private string ReceiveString(int timeoutMs)
            {
            byte[] buffer = new byte[4096];
            _stream.ReadTimeout = timeoutMs;
            try
            {
                int bytesRead = _stream.Read(buffer, 0, buffer.Length);
                if (bytesRead > 0)
                return Encoding.UTF8.GetString(buffer, 0, bytesRead).Trim();
            }
            catch (IOException) { }
            return null;
            }
    
            private void HandleConnectionLost()
            {
            if (!_isConnected) return;
            _isConnected = false;
            OnLog?.Invoke("[Network] Connection lost");
            OnDisconnected?.Invoke();
            }
    
            #endregion
        }
        /// <summary>
        /// محرك الاتصال الشبكي - يدير الاتصال TCP بين Client و Server
        /// يدعم: Handshake, Heartbeat, Data Transfer, Commands
        /// </summary>
        public class NetworkEngine
        {
            private TcpClient _tcpClient;
            private NetworkStream _stream;
            private Thread _receiveThread;
            private Thread _heartbeatThread;
            private string _serverIP;
            private int _serverPort;
            private string _atmId;
            private string _atmType;
            private string _clientVersion;
            private bool _isConnected;
            private bool _isRunning;
            private DateTime _lastHeartbeat;
            private readonly object _sendLock = new object();
            private readonly object _ackLock = new object();
            private readonly HashSet<string> _pendingJournalAcks = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            private readonly JournalSyncTracker _syncTracker;
    
            // أحداث
            public event Action OnConnected;
            public event Action OnDisconnected;
            public event Action<string> OnMessageReceived;
            public event Action<string, byte[]> OnDataReceived;
            public event Action<string, string[]> OnCommandReceived;
            public event Action<JournalSyncRecord> OnJournalSyncChanged;
            public event Action<string> OnLog;
            public event Action<Exception> OnError;
    
            public bool IsConnected { get { return _isConnected; } }
            public DateTime LastHeartbeat { get { return _lastHeartbeat; } }
    
            public NetworkEngine(string atmId, string atmType, string serverIP, int serverPort)
            {
            _atmId = atmId;
            _atmType = atmType;
            _serverIP = serverIP;
            _serverPort = serverPort;
            _clientVersion = AppConstants.APP_VERSION;
            _isConnected = false;
            _isRunning = false;
            _syncTracker = new JournalSyncTracker();
            _syncTracker.OnRecordChanged += r => OnJournalSyncChanged?.Invoke(r);
            }
    
            /// <summary>
            /// بدء الاتصال بالسيرفر
            /// </summary>
            public bool Connect()
            {
            try
            {
                if (_isConnected) return true;
    
                OnLog?.Invoke("[Network] Connecting to " + _serverIP + ":" + _serverPort);
    
                _tcpClient = new TcpClient();
                _tcpClient.ReceiveTimeout = NetworkConfig.CONNECTION_TIMEOUT_MS;
                _tcpClient.SendTimeout = NetworkConfig.CONNECTION_TIMEOUT_MS;
                _tcpClient.ReceiveBufferSize = NetworkConfig.SOCKET_BUFFER_SIZE;
                _tcpClient.SendBufferSize = NetworkConfig.SOCKET_BUFFER_SIZE;
                _tcpClient.NoDelay = true;
    
                var result = _tcpClient.BeginConnect(_serverIP, _serverPort, null, null);
                bool connected = result.AsyncWaitHandle.WaitOne(NetworkConfig.CONNECTION_TIMEOUT_MS);
    
                if (!connected)
                {
                OnLog?.Invoke("[Network] Connection timeout");
                return false;
                }
    
                _tcpClient.EndConnect(result);
                _stream = _tcpClient.GetStream();
    
                // إرسال Handshake
                if (!PerformHandshake())
                {
                Disconnect();
                return false;
                }
    
                _isConnected = true;
                _isRunning = true;
                _lastHeartbeat = DateTime.Now;
    
                // بدء خيط الاستقبال
                _receiveThread = new Thread(ReceiveLoop);
                _receiveThread.IsBackground = true;
                _receiveThread.Start();
    
                // بدء خيط Heartbeat
                _heartbeatThread = new Thread(HeartbeatLoop);
                _heartbeatThread.IsBackground = true;
                _heartbeatThread.Start();
    
                OnLog?.Invoke("[Network] Connected successfully");
                OnConnected?.Invoke();
                return true;
            }
            catch (Exception ex)
            {
                OnLog?.Invoke("[Network] Connection failed: " + ex.Message);
                OnError?.Invoke(ex);
                return false;
            }
            }
    
            /// <summary>
            /// قطع الاتصال
            /// </summary>
            public void Disconnect()
            {
            _isRunning = false;
            _isConnected = false;
    
            try
            {
                if (_stream != null) { _stream.Close(); _stream = null; }
                if (_tcpClient != null) { _tcpClient.Close(); _tcpClient = null; }
            }
            catch { }
    
            OnLog?.Invoke("[Network] Disconnected");
            OnDisconnected?.Invoke();
            }
    
            /// <summary>
            /// إرسال بيانات جورنال إلى السيرفر
            /// </summary>
            public bool SendJournalData(string fileName, byte[] data, string checksum)
            {
            return SendJournalData(null, fileName, data, checksum);
            }
    
            public bool SendJournalData(string syncId, string fileName, byte[] data, string checksum)
            {
            JournalSyncRecord syncRecord = _syncTracker.BeginLocalSave(_atmId, fileName, data == null ? 0 : data.Length, checksum, null, syncId);
            try
            {
                if (!_isConnected)
                {
                _syncTracker.MarkPending(syncRecord.SyncId);
                return false;
                }
                if (data == null) data = new byte[0];
    
                _syncTracker.MarkSyncing(syncRecord.SyncId, 40);
                string payload = Convert.ToBase64String(data);
                string message = Protocol.BuildMessage(
                Protocol.DATA_JOURNAL,
                _atmId,
                fileName,
                data.Length.ToString(),
                checksum,
                DateTime.UtcNow.ToString("O"),
                payload,
                syncRecord.SyncId
                );
    
                lock (_sendLock)
                {
                SendString(message);
                lock (_ackLock) _pendingJournalAcks.Add(syncRecord.SyncId);
                }
    
                OnLog?.Invoke(string.Format("[Network] Sent {0} ({1} bytes)", fileName, data.Length));
                return true;
            }
            catch (Exception ex)
            {
                _syncTracker.MarkFailed(syncRecord.SyncId, ex.Message);
                OnError?.Invoke(ex);
                HandleConnectionLost();
                return false;
            }
            }
    
            /// <summary>
            /// إرسال ملف كامل إلى السيرفر
            /// </summary>
            public bool SendFile(string fileName, byte[] fileData, string checksum)
            {
            try
            {
                if (!_isConnected) return false;
    
                if (fileData == null) fileData = new byte[0];
                string payload = Convert.ToBase64String(fileData);
                string message = Protocol.BuildMessage(
                Protocol.DATA_FILE,
                _atmId,
                fileName,
                fileData.Length.ToString(),
                checksum,
                DateTime.UtcNow.ToString("O"),
                payload
                );
    
                lock (_sendLock)
                {
                SendString(message);
                }
    
                OnLog?.Invoke(string.Format("[Network] Sent file {0} ({1} bytes)", fileName, fileData.Length));
                return true;
            }
            catch (Exception ex)
            {
                OnError?.Invoke(ex);
                HandleConnectionLost();
                return false;
            }
            }
    
            /// <summary>
            /// إرسال حالة الصراف
            /// </summary>
            public bool SendStatus(string status, string cscStatus)
            {
            try
            {
                if (!_isConnected) return false;
                string msg = Protocol.BuildMessage(
                Protocol.STATUS_RESPONSE,
                _atmId,
                status,
                cscStatus,
                DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss")
                );
                lock (_sendLock) { SendString(msg); }
                return true;
            }
            catch (Exception ex)
            {
                OnError?.Invoke(ex);
                return false;
            }
            }
    
            /// <summary>
            /// إرسال نتيجة أمر
            /// </summary>
            public bool SendCommandResult(string commandId, bool success, string resultData)
            {
            try
            {
                if (!_isConnected) return false;
                string msg = Protocol.BuildMessage(
                Protocol.CMD_RESULT,
                _atmId,
                commandId,
                success ? "OK" : "FAIL",
                resultData
                );
                lock (_sendLock) { SendString(msg); }
                return true;
            }
            catch (Exception ex)
            {
                OnError?.Invoke(ex);
                return false;
            }
            }
    
            public bool SendRawData(byte[] data)
            {
            try
            {
                if (!_isConnected || data == null || data.Length == 0) return false;
                lock (_sendLock)
                {
                _stream.Write(data, 0, data.Length);
                _stream.Flush();
                }
                return true;
            }
            catch (Exception ex)
            {
                OnError?.Invoke(ex);
                HandleConnectionLost();
                return false;
            }
            }
    
            /// <summary>
            /// عمل Ping للسيرفر
            /// </summary>
            public bool Ping()
            {
            try
            {
                var ping = new System.Net.NetworkInformation.Ping();
                var reply = ping.Send(_serverIP, NetworkConfig.PING_TIMEOUT_MS);
                return reply.Status == System.Net.NetworkInformation.IPStatus.Success;
            }
            catch { return false; }
            }
    
            #region Private Methods
    
            private bool PerformHandshake()
            {
            try
            {
                // إرسال: EJLIVE_HANDSHAKE|ATM_ID|ATM_TYPE|VERSION
                string handshake = Protocol.BuildMessage(
                Protocol.HANDSHAKE,
                _atmId,
                _atmType,
                _clientVersion
                );
                SendString(handshake);
    
                // انتظار الرد
                string response = ReceiveString(5000);
                if (string.IsNullOrEmpty(response))
                {
                OnLog?.Invoke("[Network] Handshake timeout - no response");
                return false;
                }
    
                string[] parts = Protocol.ParseMessage(response);
                if (parts.Length > 0 && parts[0] == Protocol.HANDSHAKE_ACK)
                {
                OnLog?.Invoke("[Network] Handshake successful");
                return true;
                }
    
                OnLog?.Invoke("[Network] Handshake rejected: " + response);
                return false;
            }
            catch (Exception ex)
            {
                OnLog?.Invoke("[Network] Handshake error: " + ex.Message);
                return false;
            }
            }
    
            private void ReceiveLoop()
            {
            byte[] buffer = new byte[NetworkConfig.SOCKET_BUFFER_SIZE];
            StringBuilder messageBuilder = new StringBuilder();
    
            while (_isRunning && _isConnected)
            {
                try
                {
                if (_stream == null || !_tcpClient.Connected) break;
                if (!_stream.DataAvailable)
                {
                    Thread.Sleep(50);
                    continue;
                }
    
                int bytesRead = _stream.Read(buffer, 0, buffer.Length);
                if (bytesRead == 0)
                {
                    HandleConnectionLost();
                    break;
                }
    
                string received = Encoding.UTF8.GetString(buffer, 0, bytesRead);
                messageBuilder.Append(received);
    
                // معالجة الرسائل الكاملة
                string fullMessage = messageBuilder.ToString();
                int newlineIdx;
                while ((newlineIdx = fullMessage.IndexOf('\n')) >= 0)
                {
                    string msg = fullMessage.Substring(0, newlineIdx).Trim();
                    fullMessage = fullMessage.Substring(newlineIdx + 1);
    
                    if (!string.IsNullOrEmpty(msg))
                    {
                    ProcessReceivedMessage(msg);
                    }
                }
                messageBuilder.Clear();
                if (fullMessage.Length > 0) messageBuilder.Append(fullMessage);
                }
                catch (Exception ex)
                {
                if (_isRunning)
                {
                    OnError?.Invoke(ex);
                    HandleConnectionLost();
                }
                break;
                }
            }
            }
    
            private void ProcessReceivedMessage(string message)
            {
            string[] parts = Protocol.ParseMessage(message);
            if (parts.Length == 0) return;
    
            string msgType = parts[0];
    
            switch (msgType)
            {
                case Protocol.HEARTBEAT_ACK:
                _lastHeartbeat = DateTime.Now;
                break;
    
                case Protocol.DATA_ACK:
                CompleteOldestJournalAck(parts);
                OnLog?.Invoke("[Network] Data acknowledged by server");
                break;
    
                case Protocol.DATA_NACK:
                MarkJournalNack(parts);
                OnLog?.Invoke("[Network] Data rejected by server");
                break;
    
                case Protocol.STATUS_REQUEST:
                OnMessageReceived?.Invoke(message);
                break;
    
                case Protocol.CMD_RESTART:
                case Protocol.CMD_SCREENSHOT:
                case Protocol.CMD_TIMESYNC:
                case Protocol.CMD_SHUTDOWN:
                case Protocol.CMD_CHANGE_PASSWORD:
                case Protocol.CMD_SEND_IMAGE:
                case Protocol.CMD_IMAGE_SYNC:
                case Protocol.CMD_FORCE_SYNC:
                case Protocol.CMD_GHOST_START:
                case Protocol.CMD_GHOST_STOP:
                case Protocol.CMD_MESSAGE:
                case Protocol.CMD_UPDATE_CONFIG:
                case Protocol.CMD_GET_SYSINFO:
                OnCommandReceived?.Invoke(msgType, parts);
                OnLog?.Invoke("[Network] Command received: " + msgType);
                break;
    
                default:
                OnMessageReceived?.Invoke(message);
                break;
            }
            }
    
            private void HeartbeatLoop()
            {
            while (_isRunning && _isConnected)
            {
                try
                {
                Thread.Sleep(NetworkConfig.HEARTBEAT_INTERVAL_MS);
                if (!_isRunning || !_isConnected) break;
    
                string hb = Protocol.BuildMessage(
                    Protocol.HEARTBEAT,
                    _atmId,
                    DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss")
                );
    
                lock (_sendLock) { SendString(hb); }
                }
                catch (Exception)
                {
                if (_isRunning) HandleConnectionLost();
                break;
                }
            }
            }
    
            private void SendString(string message)
            {
            if (_stream == null) return;
            byte[] data = Encoding.UTF8.GetBytes(message + "\n");
            _stream.Write(data, 0, data.Length);
            _stream.Flush();
            }
    
            private string ReceiveString(int timeoutMs)
            {
            byte[] buffer = new byte[4096];
            _stream.ReadTimeout = timeoutMs;
            try
            {
                int bytesRead = _stream.Read(buffer, 0, buffer.Length);
                if (bytesRead > 0)
                return Encoding.UTF8.GetString(buffer, 0, bytesRead).Trim();
            }
            catch (IOException) { }
            return null;
            }
    
            private void HandleConnectionLost()
            {
            if (!_isConnected) return;
            _isConnected = false;
            OnLog?.Invoke("[Network] Connection lost");
            OnDisconnected?.Invoke();
            }
    
            private void CompleteOldestJournalAck(string[] parts)
            {
            string syncId = parts.Length > 1 ? parts[1] : null;
            lock (_ackLock)
            {
                if (string.IsNullOrEmpty(syncId) && _pendingJournalAcks.Count > 0)
                {
                foreach (string pendingId in _pendingJournalAcks)
                {
                    syncId = pendingId;
                    break;
                }
                }
                if (!string.IsNullOrEmpty(syncId))
                _pendingJournalAcks.Remove(syncId);
            }
            if (!string.IsNullOrEmpty(syncId))
                _syncTracker.MarkCompleted(syncId, "Server acknowledged journal storage");
            }
    
            private void MarkJournalNack(string[] parts)
            {
            string syncId = parts.Length > 1 ? parts[1] : null;
            string message = parts.Length > 2 ? string.Join(" ", parts, 2, parts.Length - 2) : "Server rejected journal payload";
            lock (_ackLock)
            {
                if (!string.IsNullOrEmpty(syncId))
                _pendingJournalAcks.Remove(syncId);
            }
            if (!string.IsNullOrEmpty(syncId))
                _syncTracker.MarkFailed(syncId, message);
            }
    
            #endregion
        }
