            public bool SendJournalFile(string fileName, byte[] data, long offset, string checksum)
            {
            if (!_connected || data == null || data.Length == 0) return false;
            try
            {
            var sha256    = SecurityHelper.SHA256Hash(data);
            int totalChunks = (int)Math.Ceiling((double)data.Length / AppConstants.ChunkSizeBytes);
    
            // START_FILE
            var startMsg = CommunicationProtocol.BuildStartFile(_atmId, fileName, data.Length, offset, checksum);
            lock (_sendLock) { _stream.Write(startMsg, 0, startMsg.Length); _stream.Flush(); }
    
            // Ø§Ù„Ø£Ø¬Ø²Ø§Ø¡
            for (int i = 0; i < totalChunks; i++)
            {
            var chunkOffset = i * (int)AppConstants.ChunkSizeBytes;
            var chunkLen    = Math.Min((int)AppConstants.ChunkSizeBytes, data.Length - chunkOffset);
            var chunk       = new byte[chunkLen];
            Buffer.BlockCopy(data, chunkOffset, chunk, 0, chunkLen);
    
            var chunkMsg = CommunicationProtocol.BuildChunk(i, chunk, _sessionKey);
            lock (_sendLock) { _stream.Write(chunkMsg, 0, chunkMsg.Length); _stream.Flush(); }
    
            if (!WaitForChunkAck(i))
                return false;
    
            TotalBytesSent += chunkLen;
            UpdateSpeed(chunkLen);
            }
    
            // COMPLETE
            var completeMsg = CommunicationProtocol.BuildComplete(fileName, checksum, sha256);
            lock (_sendLock) { _stream.Write(completeMsg, 0, completeMsg.Length); _stream.Flush(); }
    
            var verified = WaitForJournalAck(fileName);
    
            Log($"Sent: {fileName} [{data.Length / 1024.0:F1} KB] in {totalChunks} chunks - {(verified ? "Verified" : "Checksum Mismatch")}");
            return verified;
            }
            catch (Exception ex)
            {
            ReportError("SendJournal", ex);
            HandleDisconnect();
            return false;
            }
            }
    
    
            public NetworkEngine(string serverIp, int serverPort, string atmId, string atmType,
                string networkType = "LAN", JournalOutbox outbox = null)
            {
            _serverIp    = serverIp;
            _serverPort  = serverPort;
            _atmId       = atmId;
            _atmType     = atmType;
            _networkType = networkType;
            _outbox      = outbox;
    
            _reconnectPolicy = networkType switch
            {
            "GSM"  => RetryPolicy.GSM,
            "CDMA" => RetryPolicy.CDMA,
            "ADSL" => RetryPolicy.ADSL,
            _      => RetryPolicy.LAN
            };
            }
    
    
            private readonly object _sendLock = new object();
    
    
            private readonly BlockingCollection<int> _chunkAcks =
            new BlockingCollection<int>(10000);
    
    
            private readonly BlockingCollection<EJMessage> _journalAcks =
            new BlockingCollection<EJMessage>(1000);
    
    
            public bool Connect()
            {
            _running = true;
            return TryConnect();
            }
    
    
            private bool TryConnect()
            {
            for (int attempt = 1; attempt <= _reconnectPolicy.MaxAttempts; attempt++)
            {
            if (!_running) return false;
            try
            {
            Log($"محاولة اتصال {attempt}/{_reconnectPolicy.MaxAttempts} - {_serverIp}:{_serverPort}");
    
            _client = new TcpClient();
            _client.ReceiveTimeout = AppConstants.SocketTimeoutMs;
            _client.SendTimeout    = AppConstants.SocketTimeoutMs;
            _client.Connect(_serverIp, _serverPort);
            _stream = _client.GetStream();
    
            // RSA/AES Handshake (S-06)
            PerformRSAHandshake();
            SendHandshake();
    
            _connected      = true;
            ConnectedAt     = DateTime.UtcNow;
            ReconnectAttempts = attempt;
    
            OnConnectionChanged?.Invoke(this, true);
            OnSessionEstablished?.Invoke(this, SessionId);
            Log($"متصل - Session: {SessionId}");
    
            // Ø¨Ø¯Ø¡ Heartbeat + Receive threads
            StartHeartbeat();
            StartReceive();
    
            // Ø§Ø³ØªØ¦Ù†Ø§Ù Ø§Ù„Ø·Ø§Ø¨ÙˆØ± Ø§Ù„Ù…Ø¹Ù„Ù‚ (L-02)
            ResumeOutbox();
    
            return true;
            }
            catch (Exception ex)
            {
            ReportError("Connect", ex);
            _client?.Close();
            _connected = false;
            OnConnectionChanged?.Invoke(this, false);
    
            if (attempt < _reconnectPolicy.MaxAttempts)
            {
                var delay = _reconnectPolicy.ComputeDelay(attempt);
                Log($"إعادة المحاولة بعد {delay}ms...");
                Thread.Sleep(delay);
            }
            }
            }
            return false;
            }
    
    
            private void PerformRSAHandshake()
            {
            // 1. Ø§Ø³ØªÙ„Ø§Ù… RSA Public Key Ù…Ù† Ø§Ù„Ø³ÙŠØ±ÙØ±
            var rsaMsg     = CommunicationProtocol.ReadMessage(_stream);
            if (rsaMsg.Type != CommunicationProtocol.MsgType.RsaPublicKey)
            throw new InvalidOperationException("Expected RSA Public Key from server");
            var serverPublicKey = rsaMsg.Text;
    
            // 2. ØªÙˆÙ„ÙŠØ¯ AES Session Key ÙˆØªØ´ÙÙŠØ±Ù‡ Ø¨Ù€ RSA
            _sessionKey    = SecurityHelper.GenerateSessionKey();
            var encAesKey  = SecurityHelper.EncryptWithRSAPublicKey(_sessionKey, serverPublicKey);
            var aesMsg     = CommunicationProtocol.BuildAesSessionKey(encAesKey);
            _stream.Write(aesMsg, 0, aesMsg.Length);
    
            Log("RSA/AES Handshake completed - Encrypted session established");
            }
    
    
            private void SendHandshake()
            {
            var frame = CommunicationProtocol.BuildHandshake(_atmId, _atmType, AppConstants.AppVersion);
            _stream.Write(frame, 0, frame.Length);
    
            var response  = CommunicationProtocol.ReadMessage(_stream, _sessionKey);
            if (response.Type != CommunicationProtocol.MsgType.HandshakeAck)
            throw new InvalidOperationException("Handshake ACK not received");
    
            var parts = response.Text.Split('|');
            SessionId = parts.Length > 2 ? parts[2] : Guid.NewGuid().ToString("N");
            }
    
    
            private void StartHeartbeat()
            {
            _heartbeatThread?.Abort();
            _heartbeatThread = new Thread(HeartbeatLoop) { IsBackground = true, Name = "EJLive.Heartbeat" };
            _heartbeatThread.Start();
            }
    
    
            private void HeartbeatLoop()
            {
            _lastHeartbeatAck = DateTime.UtcNow;
            while (_running && _connected)
            {
            try
            {
            Thread.Sleep(AppConstants.HeartbeatIntervalSec * 1000);
            if (!_connected) break;
    
            // ÙØ­Øµ: Ù‡Ù„ Ù…Ø¶Ù‰ ÙˆÙ‚Øª Ø£ÙƒØ«Ø± Ù…Ù† 3Ã— Heartbeat Ø¯ÙˆÙ† Ø±Ø¯ØŸ
            if ((DateTime.UtcNow - _lastHeartbeatAck).TotalSeconds > AppConstants.HeartbeatTimeoutSec)
            {
                Log("Heartbeat timeout - reconnecting...");
                HandleDisconnect();
                break;
            }
    
            var hb = CommunicationProtocol.BuildHeartbeat(_atmId, BuildHeartbeatStatsPayload());
            lock (_sendLock) _stream.Write(hb, 0, hb.Length);
            }
            catch { break; }
            }
            }
    
    
            private void StartReceive()
            {
            _receiveThread = new Thread(ReceiveLoop) { IsBackground = true, Name = "EJLive.Receive" };
            _receiveThread.Start();
            }
    
    
            private void ReceiveLoop()
            {
            while (_running && _connected)
            {
            try
            {
            var msg = CommunicationProtocol.ReadMessage(_stream, _sessionKey);
            TotalBytesReceived += msg.Payload?.Length ?? 0;
    
            if (msg.Type == CommunicationProtocol.MsgType.HeartbeatAck)
            {
                _lastHeartbeatAck = DateTime.UtcNow;
                continue;
            }
            if (msg.Type == CommunicationProtocol.MsgType.ChunkAck)
            {
                if (msg.Payload != null && msg.Payload.Length >= 4)
                _chunkAcks.TryAdd(BitConverter.ToInt32(msg.Payload, 0));
                continue;
            }
            if (msg.Type == CommunicationProtocol.MsgType.JournalAck)
            {
                _journalAcks.TryAdd(msg);
                continue;
            }
            if (msg.Type == CommunicationProtocol.MsgType.Disconnect)
            {
                HandleDisconnect();
                break;
            }
            OnMessageReceived?.Invoke(this, msg);
            }
            catch (IOException) { HandleDisconnect(); break; }
            catch (Exception ex) { ReportError("Receive", ex); break; }
            }
            }
    
    
            private void ResumeOutbox()
            {
            if (_outbox == null) return;
            var thread = new Thread(() =>
            {
            while (_running && _connected)
            {
            Thread.Sleep(100);
            if (_outbox.TryDequeue(out var item))
            {
                if (!item.IsReadyToSend) { _outbox.Enqueue(item); Thread.Sleep(200); continue; }
    
                var success  = SendJournalFile(item.FileName, item.Data, item.Offset, item.Checksum);
    
                if (success)
                _outbox.MarkCompleted(item.ItemId);
                else
                {
                var delay = _reconnectPolicy.ComputeDelay(item.RetryCount + 1);
                _outbox.RetryItem(item.ItemId, delay);
                }
            }
            }
            }) { IsBackground = true, Name = "EJLive.OutboxSender" };
            thread.Start();
            }
    
    
            public void SendMessage(byte[] frame)
            {
            if (!_connected) return;
            lock (_sendLock) { _stream.Write(frame, 0, frame.Length); _stream.Flush(); }
            }
    
    
            private bool WaitForChunkAck(int seqNum)
            {
            var deadline = DateTime.UtcNow.AddMilliseconds(AppConstants.SocketTimeoutMs);
            while (_connected && DateTime.UtcNow < deadline)
            {
            var remaining = Math.Max(50, (int)(deadline - DateTime.UtcNow).TotalMilliseconds);
            if (_chunkAcks.TryTake(out var ackSeq, Math.Min(remaining, 500)) && ackSeq == seqNum)
            return true;
            }
            Log($"CHUNK_ACK timeout seq={seqNum}");
            return false;
            }
    
    
            private bool WaitForJournalAck(string fileName)
            {
            var deadline = DateTime.UtcNow.AddMilliseconds(AppConstants.SocketTimeoutMs);
            while (_connected && DateTime.UtcNow < deadline)
            {
            var remaining = Math.Max(50, (int)(deadline - DateTime.UtcNow).TotalMilliseconds);
            if (!_journalAcks.TryTake(out var ack, Math.Min(remaining, 500)))
            continue;
    
            var text = ack.Text ?? string.Empty;
            if (!string.IsNullOrWhiteSpace(fileName) &&
            text.IndexOf(fileName, StringComparison.OrdinalIgnoreCase) < 0)
            continue;
            return text.IndexOf("OK", StringComparison.OrdinalIgnoreCase) >= 0;
            }
            Log($"JOURNAL_ACK timeout file={fileName}");
            return false;
            }
    
    
            private void HandleDisconnect()
            {
            if (!_connected) return;
            _connected = false;
            _client?.Close();
            OnConnectionChanged?.Invoke(this, false);
            Log("اتصال منقطع");
    
            if (_running)
            {
            var t = new Thread(() =>
            {
            Thread.Sleep(2000);
            TryConnect();
            }) { IsBackground = true };
            t.Start();
            }
            }
    
    
            public void Disconnect()
            {
            _running = false;
            try
            {
            if (_connected)
            {
            var disc = CommunicationProtocol.BuildDisconnect("Client disconnect");
            lock (_sendLock) _stream?.Write(disc, 0, disc.Length);
            }
            }
            catch { }
            _client?.Close();
            _connected = false;
            }
    
    
            private string BuildHeartbeatStatsPayload()
            {
            try
            {
            var process = Process.GetCurrentProcess();
            var uptimeMs = Math.Max(1.0, (double)(Environment.TickCount & int.MaxValue));
            var cpu = (process.TotalProcessorTime.TotalMilliseconds / (Environment.ProcessorCount * uptimeMs)) * 100.0;
            cpu = Math.Max(0.0, Math.Min(100.0, cpu));
    
            var memMb = process.WorkingSet64 / 1024.0 / 1024.0;
            // Heuristic: 2GB baseline for quick health indication without extra OS APIs.
            var memPct = Math.Max(0.0, Math.Min(100.0, (memMb / 2048.0) * 100.0));
    
            var root = Path.GetPathRoot(Environment.SystemDirectory);
            var drives = DriveInfo.GetDrives();
            DriveInfo drive = null;
            if (!string.IsNullOrWhiteSpace(root))
            drive = Array.Find(drives, d => d.IsReady && string.Equals(d.Name, root, StringComparison.OrdinalIgnoreCase));
            var diskPct = drive != null && drive.TotalSize > 0
            ? ((drive.TotalSize - drive.TotalFreeSpace) * 100.0 / drive.TotalSize)
            : 0.0;
            diskPct = Math.Max(0.0, Math.Min(100.0, diskPct));
    
            var health = 100;
            if (cpu > 85) health -= 10;
            if (memPct > 85) health -= 10;
            if (diskPct > 95) health -= 20;
            health = Math.Max(0, Math.Min(100, health));
    
            return $"CPU={cpu:F1};MEM={memPct:F1};DISK={diskPct:F1};HEALTH={health}";
            }
            catch
            {
            return "CPU=0;MEM=0;DISK=0;HEALTH=80";
            }
            }
    
    
            private void UpdateSpeed(long bytes)
            {
            // ØªÙ‚Ø¯ÙŠØ± Ø¨Ø³ÙŠØ· Ù„Ù„Ø³Ø±Ø¹Ø©
            SpeedKBs = bytes / 1024.0;
            }
    
    
            private void ReportError(string context, Exception ex)
