            private void HandleDisconnect()
            {
            if (!_connected) return;
            _connected = false;
            _client?.Close();
            OnConnectionChanged?.Invoke(this, false);
            Log("اتصال منقطع");
    
            if (_running)
            {
                var t = new Thread(() => {
                Thread.Sleep(2000);
                TryConnect();
                })
                {
                IsBackground = true
                };
                t.Start();
            }
            }
    
            public void Disconnect()
            {
            _running = false;
            try
            {
                if (_connected)
                {
                var disc = CommunicationProtocol.BuildDisconnect("Client disconnect");
                lock (_sendLock) _stream?.Write(disc, 0, disc.Length);
                }
            }
            catch { }
            _client?.Close();
            _connected = false;
            }
    
            private string BuildHeartbeatStatsPayload()
            {
            try
            {
                var process = Process.GetCurrentProcess();
                var uptimeMs = Math.Max(1.0, (double)(Environment.TickCount & int.MaxValue));
                var cpu = (process.TotalProcessorTime.TotalMilliseconds / (Environment.ProcessorCount * uptimeMs)) * 100.0;
                cpu = Math.Max(0.0, Math.Min(100.0, cpu));
    
                var memMb = process.WorkingSet64 / 1024.0 / 1024.0;
                // Heuristic: 2GB baseline for quick health indication without extra OS APIs.
                var memPct = Math.Max(0.0, Math.Min(100.0, (memMb / 2048.0) * 100.0));
    
                var root = Path.GetPathRoot(Environment.SystemDirectory);
                var drives = DriveInfo.GetDrives();
                DriveInfo drive = null;
                if (!string.IsNullOrWhiteSpace(root))
                drive = Array.Find(drives, d => d.IsReady && string.Equals(d.Name, root, StringComparison.OrdinalIgnoreCase));
                var diskPct = drive != null && drive.TotalSize > 0 ?
                ((drive.TotalSize - drive.TotalFreeSpace) * 100.0 / drive.TotalSize) :
                0.0;
                diskPct = Math.Max(0.0, Math.Min(100.0, diskPct));
    
                var health = 100;
                if (cpu > 85) health -= 10;
                if (memPct > 85) health -= 10;
                if (diskPct > 95) health -= 20;
                health = Math.Max(0, Math.Min(100, health));
    
                return $"CPU={cpu:F1};MEM={memPct:F1};DISK={diskPct:F1};HEALTH={health}";
            }
            catch
            {
                return "CPU=0;MEM=0;DISK=0;HEALTH=80";
            }
            }
    
            private void UpdateSpeed(long bytes)
            {
            // ØªÙ‚Ø¯ÙŠØ± Ø¨Ø³ÙŠØ· Ù„Ù„Ø³Ø±Ø¹Ø©
            SpeedKBs = bytes / 1024.0;
            }
    
            private void ReportError(string context, Exception ex)
            {
            var message = $"{context}: {ex.Message}";
            Log(message);
            OnError?.Invoke(this, message);
            }
    
            private void Log(string msg) => OnLog?.Invoke(this, msg);
    
            public void Dispose() => Disconnect();
        }
