            }
    
            private bool WaitForChunkAck(int seqNum)
            {
            var deadline = DateTime.UtcNow.AddMilliseconds(AppConstants.SocketTimeoutMs);
            while (_connected && DateTime.UtcNow < deadline)
            {
                var remaining = Math.Max(50, (int)(deadline - DateTime.UtcNow).TotalMilliseconds);
                if (_chunkAcks.TryTake(out var ackSeq, Math.Min(remaining, 500)) && ackSeq == seqNum)
                return true;
            }
            Log($"CHUNK_ACK timeout seq={seqNum}");
            return false;
            }
    
            private bool WaitForJournalAck(string fileName)
            {
            var deadline = DateTime.UtcNow.AddMilliseconds(AppConstants.SocketTimeoutMs);
            while (_connected && DateTime.UtcNow < deadline)
            {
                var remaining = Math.Max(50, (int)(deadline - DateTime.UtcNow).TotalMilliseconds);
                if (!_journalAcks.TryTake(out var ack, Math.Min(remaining, 500)))
                continue;
    
                var text = ack.Text ?? string.Empty;
                if (!string.IsNullOrWhiteSpace(fileName) &&
                text.IndexOf(fileName, StringComparison.OrdinalIgnoreCase) < 0)
                continue;
                return text.IndexOf("OK", StringComparison.OrdinalIgnoreCase) >= 0;
            }
            Log($"JOURNAL_ACK timeout file={fileName}");
            return false;
            }
    
            private void HandleDisconnect()
            {
