            catch (Exception ex)
            {
                OnError?.Invoke(ex);
                HandleConnectionLost();
                return false;
            }
            }
    
            public bool SendFile(string fileName, byte[] fileData, string checksum)
            {
            try
            {
                if (!_isConnected) return false;
    
                string header = Protocol.BuildMessage(
                Protocol.DATA_FILE,
                _atmId,
                fileName,
                fileData.Length.ToString(),
                checksum,
                DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss")
                );
    
                lock (_sendLock)
                {
                SendString(header + Protocol.HEADER_END);
                _stream.Write(fileData, 0, fileData.Length);
                _stream.Flush();
                byte[] endMarker = Encoding.UTF8.GetBytes(Protocol.DATA_END);
                _stream.Write(endMarker, 0, endMarker.Length);
                _stream.Flush();
                }
    
                OnLog?.Invoke(string.Format("[Network] Sent file {0} ({1} bytes)", fileName, fileData.Length));
                return true;
            }
            catch (Exception ex)
            {
                OnError?.Invoke(ex);
                HandleConnectionLost();
                return false;
            }
            }
    
            public bool SendStatus(string status, string cscStatus)
            {
            try
            {
                if (!_isConnected) return false;
                string msg = Protocol.BuildMessage(
                Protocol.STATUS_RESPONSE,
                _atmId,
                status,
                cscStatus,
                DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss")
                );
                lock (_sendLock) { SendString(msg); }
                return true;
            }
            catch (Exception ex)
            {
                OnError?.Invoke(ex);
                return false;
            }
            }
    
            public bool SendCommandResult(string commandId, bool success, string resultData)
            {
            try
            {
                if (!_isConnected) return false;
                string msg = Protocol.BuildMessage(
                Protocol.CMD_RESULT,
                _atmId,
                commandId,
                success ? "OK" : "FAIL",
                resultData
                );
                lock (_sendLock) { SendString(msg); }
                return true;
            }
            catch (Exception ex)
            {
                OnError?.Invoke(ex);
                return false;
            }
            }
    
            public bool Ping()
            {
            try
            {
                var ping = new System.Net.NetworkInformation.Ping();
                var reply = ping.Send(_serverIP, NetworkConfig.PING_TIMEOUT_MS);
                return reply.Status == System.Net.NetworkInformation.IPStatus.Success;
            }
            catch { return false; }
            }
    
            private bool PerformHandshake()
            {
            try
            {
                string handshake = Protocol.BuildMessage(
                Protocol.HANDSHAKE,
                _atmId,
                _atmType,
                _clientVersion
                );
                SendString(handshake);
    
                string response = ReceiveString(5000);
                if (string.IsNullOrEmpty(response))
                {
                OnLog?.Invoke("[Network] Handshake timeout - no response");
                return false;
                }
    
                string[] parts = Protocol.ParseMessage(response);
                if (parts.Length > 0 && parts[0] == Protocol.HANDSHAKE_ACK)
                {
                OnLog?.Invoke("[Network] Handshake successful");
                return true;
                }
    
                OnLog?.Invoke("[Network] Handshake rejected: " + response);
                return false;
            }
            catch (Exception ex)
            {
                OnLog?.Invoke("[Network] Handshake error: " + ex.Message);
                return false;
            }
            }
    
            private void ReceiveLoop()
            {
            byte[] buffer = new byte[NetworkConfig.SOCKET_BUFFER_SIZE];
            StringBuilder messageBuilder = new StringBuilder();
    
            while (_isRunning && _isConnected)
            {
                try
                {
                if (_stream == null || !_tcpClient.Connected) break;
                if (!_stream.DataAvailable)
                {
                Thread.Sleep(50);
                continue;
                }
    
                int bytesRead = _stream.Read(buffer, 0, buffer.Length);
                if (bytesRead == 0)
                {
                HandleConnectionLost();
                break;
                }
    
                string received = Encoding.UTF8.GetString(buffer, 0, bytesRead);
                messageBuilder.Append(received);
    
                string fullMessage = messageBuilder.ToString();
                int newlineIdx;
                while ((newlineIdx = fullMessage.IndexOf('\n')) >= 0)
                {
                string msg = fullMessage.Substring(0, newlineIdx).Trim();
                fullMessage = fullMessage.Substring(newlineIdx + 1);
    
                if (!string.IsNullOrEmpty(msg))
                {
                ProcessReceivedMessage(msg);
                }
                }
                messageBuilder.Clear();
                if (fullMessage.Length > 0) messageBuilder.Append(fullMessage);
                }
                catch (Exception ex)
                {
                if (_isRunning)
                {
                OnError?.Invoke(ex);
                HandleConnectionLost();
                }
                break;
                }
            }
            }
    
            private void ProcessReceivedMessage(string message)
            {
            string[] parts = Protocol.ParseMessage(message);
            if (parts.Length == 0) return;
    
            string msgType = parts[0];
    
            switch (msgType)
            {
                case Protocol.HEARTBEAT_ACK:
                _lastHeartbeat = DateTime.Now;
                break;
    
                case Protocol.DATA_ACK:
                OnLog?.Invoke("[Network] Data acknowledged by server");
                break;
    
                case Protocol.STATUS_REQUEST:
                OnMessageReceived?.Invoke(message);
                break;
    
                case Protocol.CMD_RESTART:
                case Protocol.CMD_SCREENSHOT:
                case Protocol.CMD_TIMESYNC:
                case Protocol.CMD_SHUTDOWN:
                case Protocol.CMD_CHANGE_PASSWORD:
                case Protocol.CMD_SEND_IMAGE:
                case Protocol.CMD_UPDATE_CONFIG:
                case Protocol.CMD_GET_SYSINFO:
                OnCommandReceived?.Invoke(msgType, parts);
                OnLog?.Invoke("[Network] Command received: " + msgType);
                break;
    
                default:
                OnMessageReceived?.Invoke(message);
                break;
            }
            }
    
            private void HeartbeatLoop()
            {
            while (_isRunning && _isConnected)
            {
                try
                {
                Thread.Sleep(NetworkConfig.HEARTBEAT_INTERVAL_MS);
                if (!_isRunning || !_isConnected) break;
    
                string hb = Protocol.BuildMessage(
                Protocol.HEARTBEAT,
                _atmId,
                DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss")
                );
    
                lock (_sendLock) { SendString(hb); }
                }
                catch (Exception)
                {
                if (_isRunning) HandleConnectionLost();
                break;
                }
            }
            }
    
            private void SendString(string message)
            {
            if (_stream == null) return;
            byte[] data = Encoding.UTF8.GetBytes(message + "\n");
            _stream.Write(data, 0, data.Length);
            _stream.Flush();
            }
    
            private string ReceiveString(int timeoutMs)
            {
            byte[] buffer = new byte[4096];
            _stream.ReadTimeout = timeoutMs;
            try
            {
                int bytesRead = _stream.Read(buffer, 0, buffer.Length);
                if (bytesRead > 0)
                return Encoding.UTF8.GetString(buffer, 0, bytesRead).Trim();
            }
            catch (IOException) { }
            return null;
            }
    
            private void HandleConnectionLost()
            {
            if (!_isConnected) return;
            _isConnected = false;
            OnLog?.Invoke("[Network] Connection lost");
            OnDisconnected?.Invoke();
            }
    
    
            // --- Events ---
            public event Action OnConnected;
    
            public event Action OnDisconnected;
    
            public event Action<string> OnMessageReceived;
    
            public event Action<string, byte[]> OnDataReceived;
    
            public event Action<string, string[]> OnCommandReceived;
    
            public event Action<string> OnLog;
    
            public event Action<Exception> OnError;
    
    
        }
    }
    
    namespace EJLive.Core.Network
    {
        public class NetworkEngine : IDisposable
        {
        private TcpClient? _client;
        private NetworkStream? _stream;
        private readonly string _serverIP;
        private readonly int _serverPort;
        private readonly string _deviceId;
        private readonly int _heartbeatInterval;
        private CancellationTokenSource? _cts;
        private Task? _heartbeatTask;
        private Task? _receiveTask;
        private bool _isConnected = false;
        private readonly RetryPolicy _retryPolicy;
        private DateTime _lastHeartbeatSent = DateTime.MinValue;
        private DateTime _lastHeartbeatReceived = DateTime.MinValue;
    
        public bool IsConnected => _isConnected && _client?.Connected == true;
        public event EventHandler<NetworkMessage>? MessageReceived;
        public event EventHandler? Connected;
        public event EventHandler? Disconnected;
        public event EventHandler<string>? ConnectionError;
        public DateTime LastHeartbeatReceived => _lastHeartbeatReceived;
    
        public NetworkEngine(string serverIP, int serverPort, string deviceId, int heartbeatInterval = 30)
        {
            _serverIP = serverIP;
            _serverPort = serverPort;
            _deviceId = deviceId;
            _heartbeatInterval = heartbeatInterval;
            _retryPolicy = new RetryPolicy(maxAttempts: 10, baseDelayMs: 5000, useExponentialBackoff: true, useJitter: true);
        }
    
        public async Task ConnectAsync(CancellationToken cancellationToken = default)
        {
            await _retryPolicy.ExecuteAsync(async () =>
            {
            try
            {
                _cts = new CancellationTokenSource();
                var combinedToken = CancellationTokenSource.CreateLinkedTokenSource(_cts.Token, cancellationToken).Token;
    
                _client = new TcpClient();
                await _client.ConnectAsync(_serverIP, _serverPort);
                _stream = _client.GetStream();
                _isConnected = true;
    
                Logger.Info($"Connected to server {_serverIP}:{_serverPort}", "NetworkEngine");
                Connected?.Invoke(this, EventArgs.Empty);
    
                // Start background tasks
                _heartbeatTask = Task.Run(() => HeartbeatLoopAsync(combinedToken), combinedToken);
                _receiveTask = Task.Run(() => ReceiveLoopAsync(combinedToken), combinedToken);
    
                // Send initial handshake
                await SendHandshakeAsync(combinedToken);
            }
            catch (Exception ex)
            {
                _isConnected = false;
                ConnectionError?.Invoke(this, ex.Message);
                throw;
            }
            }, ex => ex is SocketException || ex is IOException, cancellationToken);
        }
    
        public async Task DisconnectAsync()
        {
            _cts?.Cancel();
            _isConnected = false;
    
            if (_heartbeatTask != null)
            try { await _heartbeatTask.WaitAsync(TimeSpan.FromSeconds(5)); } catch { /* ignore */ }
            if (_receiveTask != null)
            try { await _receiveTask.WaitAsync(TimeSpan.FromSeconds(5)); } catch { /* ignore */ }
    
            _stream?.Close();
            _client?.Close();
            Disconnected?.Invoke(this, EventArgs.Empty);
            Logger.Info("Disconnected from server", "NetworkEngine");
        }
    
        public async Task SendMessageAsync(NetworkMessage message, CancellationToken cancellationToken = default)
        {
            if (!IsConnected || _stream == null)
            throw new InvalidOperationException("Not connected to server");
    
            var json = message.ToJson();
            var checksum = SecurityHelper.CalculateMD5(json);
            message.Checksum = checksum;
    
            var encrypted = SecurityHelper.Encrypt(json);
            var compressed = SecurityHelper.CompressString(encrypted);
            var data = Encoding.UTF8.GetBytes(compressed);
    
            var lengthPrefix = BitConverter.GetBytes(data.Length);
            await _stream.WriteAsync(lengthPrefix, 0, 4, cancellationToken);
            await _stream.WriteAsync(data, 0, data.Length, cancellationToken);
            await _stream.FlushAsync(cancellationToken);
        }
    
        public async Task SendFileChunkAsync(string fileName, byte[] chunk, int chunkIndex, int totalChunks,
                            long fileOffset, CancellationToken cancellationToken = default)
        {
            var message = new NetworkMessage
            {
            Command = CommandType.FileChunk,
            DeviceId = _deviceId,
            FileName = fileName,
            CurrentChunk = chunkIndex,
            TotalChunks = totalChunks,
            FileOffset = fileOffset,
            BinaryData = chunk,
            Checksum = SecurityHelper.CalculateMD5(chunk)
            };
            await SendMessageAsync(message, cancellationToken);
        }
    
        private async Task HeartbeatLoopAsync(CancellationToken cancellationToken)
        {
            while (!cancellationToken.IsCancellationRequested && _isConnected)
            {
            try
            {
                var heartbeatPayload = new HeartbeatPayload
                {
                Status = ATMStatus.Online,
                SystemTime = DateTime.Now,
                CurrentVersion = "3.4.0"
                };
    
                var message = new NetworkMessage
                {
                Command = CommandType.Heartbeat,
                DeviceId = _deviceId,
                Timestamp = DateTime.UtcNow,
                Payload = System.Text.Json.JsonSerializer.Serialize(heartbeatPayload)
                };
    
                await SendMessageAsync(message, cancellationToken);
                _lastHeartbeatSent = DateTime.UtcNow;
                Logger.Debug("Heartbeat sent", "NetworkEngine");
            }
            catch (Exception ex)
            {
                Logger.Warning($"Heartbeat failed: {ex.Message}", "NetworkEngine");
                _isConnected = false;
                ConnectionError?.Invoke(this, ex.Message);
            }
    
            try
            {
                await Task.Delay(TimeSpan.FromSeconds(_heartbeatInterval), cancellationToken);
            }
            catch (OperationCanceledException)
            {
                break;
            }
            }
        }
    
        private async Task ReceiveLoopAsync(CancellationToken cancellationToken)
        {
            var buffer = new byte[8192];
    
            while (!cancellationToken.IsCancellationRequested && _isConnected && _stream != null)
            {
            try
            {
                // Read length prefix
                var lengthBytes = new byte[4];
                var read = await _stream.ReadAsync(lengthBytes.AsMemory(0, 4), cancellationToken);
                if (read < 4) break;
    
                var messageLength = BitConverter.ToInt32(lengthBytes, 0);
                if (messageLength <= 0 || messageLength > 10 * 1024 * 1024) continue; // Max 10MB
    
                // Read message data
                var messageBytes = new byte[messageLength];
                var totalRead = 0;
                while (totalRead < messageLength)
                {
                var chunk = await _stream.ReadAsync(
                    messageBytes.AsMemory(totalRead, messageLength - totalRead), cancellationToken);
                if (chunk == 0) break;
                totalRead += chunk;
                }
    
                if (totalRead < messageLength) break;
    
                // Process message
                var compressed = Encoding.UTF8.GetString(messageBytes);
                var encrypted = SecurityHelper.DecompressString(compressed);
                var json = SecurityHelper.Decrypt(encrypted);
                var message = NetworkMessage.FromJson(json);
    
                if (message != null)
                {
                if (message.Command == CommandType.Heartbeat)
                {
                    _lastHeartbeatReceived = DateTime.UtcNow;
                }
                MessageReceived?.Invoke(this, message);
                }
            }
            catch (OperationCanceledException)
            {
                break;
            }
            catch (Exception ex)
            {
                Logger.Warning($"Receive error: {ex.Message}", "NetworkEngine");
                if (!_isConnected) break;
            }
            }
    
            _isConnected = false;
        }
    
        private async Task SendHandshakeAsync(CancellationToken cancellationToken)
        {
            var message = new NetworkMessage
            {
            Command = CommandType.ACK,
            DeviceId = _deviceId,
            Timestamp = DateTime.UtcNow,
            Payload = "{\"version\":\"3.4.0\",\"protocol\":2}"
            };
            await SendMessageAsync(message, cancellationToken);
        }
    
        public void Dispose()
        {
            _ = DisconnectAsync();
            _cts?.Dispose();
            _stream?.Dispose();
            _client?.Dispose();
        }
        }
