        public sealed partial class NetworkEngine : IDisposable
        {
            // --- Constants & Fields ---
                    private readonly string _host;
    
                    private readonly int _port;
    
                    private readonly string _clientId;
    
                    private TcpClient? _tcpClient;
    
                    private NetworkStream? _stream;
    
                    private CancellationTokenSource? _cts;
    
                    private readonly CircuitBreaker _circuitBreaker;
    
                    private readonly ExponentialBackoffWithJitter _backoff;
    
                    private readonly ConcurrentQueue<TransportMessage> _sendQueue = new();
    
                    private readonly ConcurrentQueue<TransportMessage> _receiveQueue = new();
    
                    private readonly byte[] _readBuffer = new byte[65536];
    
                    private Task? _readLoopTask;
    
                    private Task? _sendLoopTask;
    
                    private Task? _heartbeatTask;
    
                    private volatile bool _isConnected;
    
                    private volatile bool _disposed;
    
                    private DateTime _lastHeartbeatUtc = DateTime.MinValue;
    
                    private string? _sessionId;
    
    
            // --- Properties ---
                    public bool IsConnected => _isConnected;
    
                    public string? SessionId => _sessionId;
    
                    public string ClientId => _clientId;
    
                    public long BytesSent { get; private set; }
    
                    public long BytesReceived { get; private set; }
    
    
            // --- Constructors ---
                    public NetworkEngine(string host, int port, string clientId)
                    {
                        _host = host;
                        _port = port;
                        _clientId = clientId;
                        _circuitBreaker = new CircuitBreaker();
                        _backoff = new ExponentialBackoffWithJitter();
                    }
    
    
            // --- Methods ---
                    public async Task<bool> ConnectAsync(CancellationToken ct = default)
                    {
                        if (_isConnected) return true;
                        if (!_circuitBreaker.AllowRequest()) return false;
    
                        try
                        {
                            _tcpClient = new TcpClient { NoDelay = true, ReceiveTimeout = 30000, SendTimeout = 30000 };
                            await _tcpClient.ConnectAsync(_host, _port, ct).ConfigureAwait(false);
                            _stream = _tcpClient.GetStream();
                            _isConnected = true;
                            _cts = CancellationTokenSource.CreateLinkedTokenSource(ct);
                            _circuitBreaker.RecordSuccess();
                            _backoff.Reset();
    
                            // Start IO loops
                            _readLoopTask = ReadLoopAsync(_cts.Token);
                            _sendLoopTask = SendLoopAsync(_cts.Token);
                            _heartbeatTask = HeartbeatLoopAsync(_cts.Token);
    
                            // Perform handshake
                            await SendHandshakeAsync(_cts.Token).ConfigureAwait(false);
                            OnConnected?.Invoke();
                            Log("Connected successfully.");
                            return true;
                        }
                        catch (Exception ex)
                        {
                            _circuitBreaker.RecordFailure();
                            Log($"Connection failed: {ex.Message}");
                            OnError?.Invoke(ex);
                            return false;
                        }
                    }
    
                    public async Task DisconnectAsync(string reason = "Manual disconnect")
                    {
                        _isConnected = false;
                        _cts?.Cancel();
                        Cleanup();
                        OnDisconnected?.Invoke(reason);
                        Log($"Disconnected: {reason}");
                    }
    
                    public void EnqueueSend(TransportMessage message)
                    {
                        _sendQueue.Enqueue(message);
                    }
    
                    public async Task<bool> SendAsync(TransportMessage message, CancellationToken ct = default)
                    {
                        if (!_isConnected || _stream == null) return false;
                        try
                        {
                            var data = Encoding.UTF8.GetBytes(SerializeMessage(message));
                            await _stream.WriteAsync(data, 0, data.Length, ct).ConfigureAwait(false);
                            await _stream.FlushAsync(ct).ConfigureAwait(false);
                            BytesSent += data.Length;
                            return true;
                        }
                        catch (Exception ex)
                        {
                            Log($"Send failed: {ex.Message}");
                            return false;
                        }
                    }
    
                    public bool TryDequeueReceived(out TransportMessage message)
                    {
                        return _receiveQueue.TryDequeue(out message!);
                    }
    
                    private async Task ReadLoopAsync(CancellationToken ct)
                    {
                        var buffer = new byte[65536];
                        while (!ct.IsCancellationRequested && _isConnected)
                        {
                            try
                            {
                                if (_stream == null) break;
                                int bytesRead = await _stream.ReadAsync(buffer, 0, buffer.Length, ct).ConfigureAwait(false);
                                if (bytesRead == 0) { await DisconnectAsync("Server closed connection"); break; }
    
                                BytesReceived += bytesRead;
                                var text = Encoding.UTF8.GetString(buffer, 0, bytesRead);
    
                                // Handle multi-message frames (newline delimited)
                                foreach (var line in text.Split('\n', StringSplitOptions.RemoveEmptyEntries))
                                {
                                    var msg = DeserializeMessage(line.Trim());
                                    if (msg != null)
                                    {
                                        _receiveQueue.Enqueue(msg);
                                        OnMessageReceived?.Invoke(msg);
                                    }
                                }
                            }
                            catch (OperationCanceledException) { break; }
                            catch (IOException) { await AttemptReconnectAsync(ct).ConfigureAwait(false); }
                            catch (Exception ex) { Log($"Read error: {ex.Message}"); }
                        }
                    }
    
                    private async Task SendLoopAsync(CancellationToken ct)
                    {
                        while (!ct.IsCancellationRequested && _isConnected)
                        {
                            while (_sendQueue.TryDequeue(out var msg))
                            {
                                await SendAsync(msg, ct).ConfigureAwait(false);
                            }
                            await Task.Delay(50, ct).ConfigureAwait(false);
                        }
                    }
    
                    private async Task HeartbeatLoopAsync(CancellationToken ct)
                    {
                        while (!ct.IsCancellationRequested && _isConnected)
                        {
                            await Task.Delay(10000, ct).ConfigureAwait(false);
                            if (!_isConnected) break;
                            var hb = new HeartbeatPayload { ATM_ID = _clientId, SessionId = _sessionId, TimestampUtc = DateTime.UtcNow };
                            var msg = new TransportMessage { MessageType = "HEARTBEAT", Payload = Encoding.UTF8.GetBytes(SerializeHeartbeat(hb)) };
                            EnqueueSend(msg);
                            _lastHeartbeatUtc = DateTime.UtcNow;
                        }
                    }
    
                    private async Task SendHandshakeAsync(CancellationToken ct)
                    {
                        var hs = new HandshakeRequest { ATM_ID = _clientId, ProtocolVersion = "EJLv5" };
                        var msg = new TransportMessage { MessageType = "HANDSHAKE", Payload = Encoding.UTF8.GetBytes(SerializeHandshake(hs)) };
                        await SendAsync(msg, ct).ConfigureAwait(false);
                    }
    
                    private async Task AttemptReconnectAsync(CancellationToken ct)
                    {
                        _isConnected = false;
                        Cleanup();
                        while (!ct.IsCancellationRequested && !_isConnected)
                        {
                            var delay = _backoff.NextDelay();
                            Log($"Reconnecting in {delay.TotalSeconds:N0}s...");
                            await Task.Delay(delay, ct).ConfigureAwait(false);
                            await ConnectAsync(ct).ConfigureAwait(false);
                        }
                    }
    
                    private static string SerializeMessage(TransportMessage msg)
                    {
                        return $"{msg.MessageType}|{msg.TransferId}|{msg.FileName}|{msg.ChunkIndex}|{msg.TotalChunks}|{msg.ChunkSize}|{msg.Checksum}|{msg.IsLastChunk}|{Convert.ToBase64String(msg.Payload ?? Array.Empty<byte>())}\n";
                    }
    
                    private static TransportMessage? DeserializeMessage(string line)
                    {
                        try
                        {
                            var parts = line.Split('|');
                            if (parts.Length < 9) return null;
                            return new TransportMessage
                            {
                                MessageType = parts[0],
                                TransferId = parts[1],
                                FileName = parts[2],
                                ChunkIndex = int.TryParse(parts[3], out var ci) ? ci : 0,
                                TotalChunks = int.TryParse(parts[4], out var tc) ? tc : 0,
                                ChunkSize = int.TryParse(parts[5], out var cs) ? cs : 0,
                                Checksum = parts[6],
                                IsLastChunk = bool.TryParse(parts[7], out var lc) && lc,
                                Payload = Convert.FromBase64String(parts[8])
                            };
                        }
                        catch { return null; }
                    }
    
                    private static string SerializeHeartbeat(HeartbeatPayload hb)
                    {
                        return $"HB|{hb.ATM_ID}|{hb.SessionId}|{hb.TimestampUtc:O}";
                    }
    
                    private static string SerializeHandshake(HandshakeRequest hs)
                    {
                        return $"HS|{hs.ATM_ID}|{hs.MachineId}|{hs.ProtocolVersion}|{hs.ClientVersion}|{hs.Nonce}|{hs.TimestampUtc:O}";
                    }
    
                    private void Cleanup()
                    {
                        try { _tcpClient?.Close(); } catch { }
                        try { _stream?.Dispose(); } catch { }
                        _tcpClient = null;
                        _stream = null;
                    }
    
                    private void Log(string msg)
                    {
                        try { OnLog?.Invoke($"[NetworkEngine] {msg}"); } catch { }
                    }
    
                    public void Dispose()
                    {
                        if (!_disposed)
                        {
                            _disposed = true;
                            _cts?.Cancel();
                            _cts?.Dispose();
                            Cleanup();
                        }
                    }
    
    
            // --- Events ---
                    public event Action? OnConnected;
    
                    public event Action<string>? OnDisconnected;
    
                    public event Action<string>? OnLog;
    
                    public event Action<Exception>? OnError;
    
                    public event Action<TransportMessage>? OnMessageReceived;
    
                    public event Action<string, string>? OnSessionEstablished;
    
    
        }

    private enum CircuitBreakerState
        {
                Closed,
                Open,
                HalfOpen
            }
}

namespace EJLive.Core.Network
{
    public class NetworkEngine : IDisposable
    {
        private TcpClient? _client;
        private NetworkStream? _stream;
        private readonly string _serverIP;
        private readonly int _serverPort;
        private readonly string _deviceId;
        private readonly int _heartbeatInterval;
        private CancellationTokenSource? _cts;
        private Task? _heartbeatTask;
        private Task? _receiveTask;
        private bool _isConnected = false;
        private readonly RetryPolicy _retryPolicy;
        private DateTime _lastHeartbeatSent = DateTime.MinValue;
        private DateTime _lastHeartbeatReceived = DateTime.MinValue;
    
        public bool IsConnected => _isConnected && _client?.Connected == true;
        public event EventHandler<NetworkMessage>? MessageReceived;
        public event EventHandler? Connected;
        public event EventHandler? Disconnected;
        public event EventHandler<string>? ConnectionError;
        public DateTime LastHeartbeatReceived => _lastHeartbeatReceived;
    
        public NetworkEngine(string serverIP, int serverPort, string deviceId, int heartbeatInterval = 30)
        {
            _serverIP = serverIP;
            _serverPort = serverPort;
            _deviceId = deviceId;
            _heartbeatInterval = heartbeatInterval;
            _retryPolicy = new RetryPolicy(maxAttempts: 10, baseDelayMs: 5000, useExponentialBackoff: true, useJitter: true);
        }
    
        public async Task ConnectAsync(CancellationToken cancellationToken = default)
        {
            await _retryPolicy.ExecuteAsync(async () =>
            {
                try
                {
                    _cts = new CancellationTokenSource();
                    var combinedToken = CancellationTokenSource.CreateLinkedTokenSource(_cts.Token, cancellationToken).Token;
    
                    _client = new TcpClient();
                    await _client.ConnectAsync(_serverIP, _serverPort);
                    _stream = _client.GetStream();
                    _isConnected = true;
    
                    Logger.Info($"Connected to server {_serverIP}:{_serverPort}", "NetworkEngine");
                    Connected?.Invoke(this, EventArgs.Empty);
    
                    // Start background tasks
                    _heartbeatTask = Task.Run(() => HeartbeatLoopAsync(combinedToken), combinedToken);
                    _receiveTask = Task.Run(() => ReceiveLoopAsync(combinedToken), combinedToken);
    
                    // Send initial handshake
                    await SendHandshakeAsync(combinedToken);
                }
                catch (Exception ex)
                {
                    _isConnected = false;
                    ConnectionError?.Invoke(this, ex.Message);
                    throw;
                }
            }, ex => ex is SocketException || ex is IOException, cancellationToken);
        }
    
        public async Task DisconnectAsync()
        {
            _cts?.Cancel();
            _isConnected = false;
    
            if (_heartbeatTask != null)
                try { await _heartbeatTask.WaitAsync(TimeSpan.FromSeconds(5)); } catch { /* ignore */ }
            if (_receiveTask != null)
                try { await _receiveTask.WaitAsync(TimeSpan.FromSeconds(5)); } catch { /* ignore */ }
    
            _stream?.Close();
            _client?.Close();
            Disconnected?.Invoke(this, EventArgs.Empty);
            Logger.Info("Disconnected from server", "NetworkEngine");
        }
    
        public async Task SendMessageAsync(NetworkMessage message, CancellationToken cancellationToken = default)
        {
            if (!IsConnected || _stream == null)
                throw new InvalidOperationException("Not connected to server");
    
            var json = message.ToJson();
            var checksum = SecurityHelper.CalculateMD5(json);
            message.Checksum = checksum;
    
            var encrypted = SecurityHelper.Encrypt(json);
            var compressed = SecurityHelper.CompressString(encrypted);
            var data = Encoding.UTF8.GetBytes(compressed);
    
            var lengthPrefix = BitConverter.GetBytes(data.Length);
            await _stream.WriteAsync(lengthPrefix, 0, 4, cancellationToken);
            await _stream.WriteAsync(data, 0, data.Length, cancellationToken);
            await _stream.FlushAsync(cancellationToken);
        }
    
        public async Task SendFileChunkAsync(string fileName, byte[] chunk, int chunkIndex, int totalChunks,
                                                long fileOffset, CancellationToken cancellationToken = default)
        {
            var message = new NetworkMessage
            {
                Command = CommandType.FileChunk,
                DeviceId = _deviceId,
                FileName = fileName,
                CurrentChunk = chunkIndex,
                TotalChunks = totalChunks,
                FileOffset = fileOffset,
                BinaryData = chunk,
                Checksum = SecurityHelper.CalculateMD5(chunk)
            };
            await SendMessageAsync(message, cancellationToken);
        }
    
        private async Task HeartbeatLoopAsync(CancellationToken cancellationToken)
        {
            while (!cancellationToken.IsCancellationRequested && _isConnected)
            {
                try
                {
                    var heartbeatPayload = new HeartbeatPayload
                    {
                        Status = ATMStatus.Online,
                        SystemTime = DateTime.Now,
                        CurrentVersion = "3.4.0"
                    };
    
                    var message = new NetworkMessage
                    {
                        Command = CommandType.Heartbeat,
                        DeviceId = _deviceId,
                        Timestamp = DateTime.UtcNow,
                        Payload = System.Text.Json.JsonSerializer.Serialize(heartbeatPayload)
                    };
    
                    await SendMessageAsync(message, cancellationToken);
                    _lastHeartbeatSent = DateTime.UtcNow;
                    Logger.Debug("Heartbeat sent", "NetworkEngine");
                }
                catch (Exception ex)
                {
                    Logger.Warning($"Heartbeat failed: {ex.Message}", "NetworkEngine");
                    _isConnected = false;
                    ConnectionError?.Invoke(this, ex.Message);
                }
    
                try
                {
                    await Task.Delay(TimeSpan.FromSeconds(_heartbeatInterval), cancellationToken);
                }
                catch (OperationCanceledException)
                {
                    break;
                }
            }
        }
    
        private async Task ReceiveLoopAsync(CancellationToken cancellationToken)
        {
            var buffer = new byte[8192];
    
            while (!cancellationToken.IsCancellationRequested && _isConnected && _stream != null)
            {
                try
                {
                    // Read length prefix
                    var lengthBytes = new byte[4];
                    var read = await _stream.ReadAsync(lengthBytes.AsMemory(0, 4), cancellationToken);
                    if (read < 4) break;
    
                    var messageLength = BitConverter.ToInt32(lengthBytes, 0);
                    if (messageLength <= 0 || messageLength > 10 * 1024 * 1024) continue; // Max 10MB
    
                    // Read message data
                    var messageBytes = new byte[messageLength];
                    var totalRead = 0;
                    while (totalRead < messageLength)
                    {
                        var chunk = await _stream.ReadAsync(
                            messageBytes.AsMemory(totalRead, messageLength - totalRead), cancellationToken);
                        if (chunk == 0) break;
                        totalRead += chunk;
                    }
    
                    if (totalRead < messageLength) break;
    
                    // Process message
                    var compressed = Encoding.UTF8.GetString(messageBytes);
                    var encrypted = SecurityHelper.DecompressString(compressed);
                    var json = SecurityHelper.Decrypt(encrypted);
                    var message = NetworkMessage.FromJson(json);
    
                    if (message != null)
                    {
                        if (message.Command == CommandType.Heartbeat)
                        {
                            _lastHeartbeatReceived = DateTime.UtcNow;
                        }
                        MessageReceived?.Invoke(this, message);
                    }
                }
                catch (OperationCanceledException)
                {
                    break;
                }
                catch (Exception ex)
                {
                    Logger.Warning($"Receive error: {ex.Message}", "NetworkEngine");
                    if (!_isConnected) break;
                }
            }
    
            _isConnected = false;
        }
    
        private async Task SendHandshakeAsync(CancellationToken cancellationToken)
        {
            var message = new NetworkMessage
            {
                Command = CommandType.ACK,
                DeviceId = _deviceId,
                Timestamp = DateTime.UtcNow,
                Payload = "{\"version\":\"3.4.0\",\"protocol\":2}"
            };
            await SendMessageAsync(message, cancellationToken);
        }
    
        public void Dispose()
        {
            _ = DisconnectAsync();
            _cts?.Dispose();
            _stream?.Dispose();
            _client?.Dispose();
        }
    }
