            // --- Constructors ---
                public NetworkEngine(string serverIp, int serverPort, string atmId, string atmType,
                    string networkType = "LAN", JournalOutbox outbox = null)
                {
                _serverIp    = serverIp;
                _serverPort  = serverPort;
                _atmId       = atmId;
                _atmType     = atmType;
                _networkType = networkType;
                _outbox      = outbox;
    
                _reconnectPolicy = networkType switch
                {
                "GSM"  => RetryPolicy.GSM,
                "CDMA" => RetryPolicy.CDMA,
                "ADSL" => RetryPolicy.ADSL,
                _      => RetryPolicy.LAN
                };
                }
    
                public NetworkEngine(string atmId, string atmType, string serverIP, int serverPort)
                {
                _atmId = atmId;
                _atmType = atmType;
                _serverIP = serverIP;
                _serverPort = serverPort;
                _clientVersion = AppConstants.APP_VERSION;
                _isConnected = false;
                _isRunning = false;
                }
    
    
            // --- Methods ---
                private readonly object _sendLock = new object();
    
                public bool Connect()
                {
                _running = true;
                return TryConnect();
                }
    
                private bool TryConnect()
                {
                for (int attempt = 1; attempt <= _reconnectPolicy.MaxAttempts; attempt++)
                {
                if (!_running) return false;
                try
                {
                Log($"محاولة اتصال {attempt}/{_reconnectPolicy.MaxAttempts} → {_serverIp}:{_serverPort}");
    
                _client = new TcpClient();
                _client.ReceiveTimeout = AppConstants.SocketTimeoutMs;
                _client.SendTimeout    = AppConstants.SocketTimeoutMs;
                _client.Connect(_serverIp, _serverPort);
                _stream = _client.GetStream();
    
                // RSA/AES Handshake (S-06)
                PerformRSAHandshake();
                SendHandshake();
    
                _connected      = true;
                ConnectedAt     = DateTime.UtcNow;
                ReconnectAttempts = attempt;
    
                OnConnectionChanged?.Invoke(this, true);
                OnSessionEstablished?.Invoke(this, SessionId);
                Log($"✓ متصل — Session: {SessionId}");
    
                // بدء Heartbeat + Receive threads
                StartHeartbeat();
                StartReceive();
    
                // استئناف الطابور المعلق (L-02)
                ResumeOutbox();
    
                return true;
                }
                catch (Exception ex)
                {
                Log($"فشل الاتصال: {ex.Message}");
                _client?.Close();
                _connected = false;
                OnConnectionChanged?.Invoke(this, false);
    
                if (attempt < _reconnectPolicy.MaxAttempts)
                {
                    var delay = _reconnectPolicy.ComputeDelay(attempt);
                    Log($"إعادة المحاولة بعد {delay}ms...");
                    Thread.Sleep(delay);
                }
                }
                }
                return false;
                }
    
                private void PerformRSAHandshake()
                {
                // 1. استلام RSA Public Key من السيرفر
                var rsaMsg     = CommunicationProtocol.ReadMessage(_stream);
                if (rsaMsg.Type != CommunicationProtocol.MsgType.RsaPublicKey)
                throw new InvalidOperationException("Expected RSA Public Key from server");
                var serverPublicKey = rsaMsg.Text;
    
                // 2. توليد AES Session Key وتشفيره بـ RSA
                _sessionKey    = SecurityHelper.GenerateSessionKey();
                var encAesKey  = SecurityHelper.EncryptWithRSAPublicKey(_sessionKey, serverPublicKey);
                var aesMsg     = CommunicationProtocol.BuildAesSessionKey(encAesKey);
                _stream.Write(aesMsg, 0, aesMsg.Length);
    
                Log("★ RSA/AES Handshake completed — Encrypted session established");
                }
    
                private void SendHandshake()
                {
                var frame = CommunicationProtocol.BuildHandshake(_atmId, _atmType, AppConstants.AppVersion);
                _stream.Write(frame, 0, frame.Length);
    
                var response  = CommunicationProtocol.ReadMessage(_stream, _sessionKey);
                if (response.Type != CommunicationProtocol.MsgType.HandshakeAck)
                throw new InvalidOperationException("Handshake ACK not received");
    
                var parts = response.Text.Split('|');
                SessionId = parts.Length > 2 ? parts[2] : Guid.NewGuid().ToString("N");
                }
    
                private void StartHeartbeat()
                {
                _heartbeatThread?.Abort();
                _heartbeatThread = new Thread(HeartbeatLoop) { IsBackground = true, Name = "EJLive.Heartbeat" };
                _heartbeatThread.Start();
                }
    
                private void HeartbeatLoop()
                {
                _lastHeartbeatAck = DateTime.UtcNow;
                while (_running && _connected)
                {
                try
                {
                Thread.Sleep(AppConstants.HeartbeatIntervalSec * 1000);
                if (!_connected) break;
    
                // فحص: هل مضى وقت أكثر من 3× Heartbeat دون رد؟
                if ((DateTime.UtcNow - _lastHeartbeatAck).TotalSeconds > AppConstants.HeartbeatTimeoutSec)
                {
                    Log("Heartbeat timeout — reconnecting...");
                    HandleDisconnect();
                    break;
                }
    
                var hb = CommunicationProtocol.BuildHeartbeat(_atmId);
                lock (_sendLock) _stream.Write(hb, 0, hb.Length);
                }
                catch { break; }
                }
                }
    
                private void StartReceive()
                {
                _receiveThread = new Thread(ReceiveLoop) { IsBackground = true, Name = "EJLive.Receive" };
                _receiveThread.Start();
                }
    
                private void ReceiveLoop()
                {
                while (_running && _connected)
                {
                try
                {
                var msg = CommunicationProtocol.ReadMessage(_stream, _sessionKey);
                TotalBytesReceived += msg.Payload?.Length ?? 0;
    
                if (msg.Type == CommunicationProtocol.MsgType.HeartbeatAck)
                {
                    _lastHeartbeatAck = DateTime.UtcNow;
                    continue;
                }
                if (msg.Type == CommunicationProtocol.MsgType.Disconnect)
                {
                    HandleDisconnect();
                    break;
                }
                OnMessageReceived?.Invoke(this, msg);
                }
                catch (IOException) { HandleDisconnect(); break; }
                catch (Exception ex) { Log($"Receive error: {ex.Message}"); break; }
                }
                }
    
                private void ResumeOutbox()
                {
                if (_outbox == null) return;
                var thread = new Thread(() =>
                {
                while (_running && _connected)
                {
                Thread.Sleep(100);
                if (_outbox.TryDequeue(out var item))
                {
                    if (!item.IsReadyToSend) { _outbox.Enqueue(item); Thread.Sleep(200); continue; }
    
                    var compData = SecurityHelper.Compress(item.Data);
                    var success  = SendJournalFile(item.FileName, compData, item.Offset, item.Checksum);
    
                    if (success)
                    _outbox.MarkCompleted(item.ItemId);
                    else
                    {
                    var delay = _reconnectPolicy.ComputeDelay(item.RetryCount + 1);
                    _outbox.RetryItem(item.ItemId, delay);
                    }
                }
                }
                }) { IsBackground = true, Name = "EJLive.OutboxSender" };
                thread.Start();
                }
    
                public void SendMessage(byte[] frame)
                {
                if (!_connected) return;
                lock (_sendLock) { _stream.Write(frame, 0, frame.Length); _stream.Flush(); }
                }
    
                private void HandleDisconnect()
                {
                if (!_connected) return;
                _connected = false;
                _client?.Close();
                OnConnectionChanged?.Invoke(this, false);
                Log("✕ اتصال منقطع");
    
                if (_running)
                {
                var t = new Thread(() =>
                {
                Thread.Sleep(2000);
                TryConnect();
                }) { IsBackground = true };
                t.Start();
                }
                }
    
                public void Disconnect()
                {
                _running = false;
                try
                {
                if (_connected)
                {
                var disc = CommunicationProtocol.BuildDisconnect("Client disconnect");
                lock (_sendLock) _stream?.Write(disc, 0, disc.Length);
                }
                }
                catch { }
                _client?.Close();
                _connected = false;
                }
    
