    using var ping = new Ping();
    public partial class NetworkEngine
        {
            private TcpClient _tcpClient;
    
    
            private NetworkStream _stream;
    
    
            private Thread _receiveThread;
    
    
            private Thread _heartbeatThread;
    
    
            private string _serverIP;
    
    
            private int _serverPort;
    
    
            private string _atmId;
    
    
            private string _atmType;
    
    
            private string _clientVersion;
    
    
            private bool _isConnected;
    
    
            private bool _isRunning;
    
    
            private DateTime _lastHeartbeat;
    
    
            private readonly JournalSyncTracker _syncTracker;
    
    
            public bool IsConnected { get { return _isConnected; } }
    
    
            public DateTime LastHeartbeat { get { return _lastHeartbeat; } }
    
    
            public NetworkEngine(string atmId, string atmType, string serverIP, int serverPort)
            {
                _atmId = atmId;
                _atmType = atmType;
                _serverIP = serverIP;
                _serverPort = serverPort;
                _clientVersion = AppConstants.APP_VERSION;
                _isConnected = false;
                _isRunning = false;
            }
    
    
            // Variant from: d:\EJLIVE\EJlive_Reference_Projects\EJLive_Complete_Unified\src\EJLive.Core\Engine\NetworkEngine.cs
            public NetworkEngine(string atmId, string atmType, string serverIP, int serverPort)
            {
                _atmId = atmId;
                _atmType = atmType;
                _serverIP = serverIP;
                _serverPort = serverPort;
                _clientVersion = AppConstants.APP_VERSION;
                _isConnected = false;
                _isRunning = false;
                _syncTracker = new JournalSyncTracker();
                _syncTracker.OnRecordChanged += r => OnJournalSyncChanged?.Invoke(r);
            }
    
    
            // Variant from: d:\EJLIVE\EJlive_Reference_Projects\CodexMarege\src\EJLive.Core\Engine\NetworkEngine.cs
            public NetworkEngine(string atmId, string atmType, string serverIP, int serverPort)
            {
                _atmId = atmId;
                _atmType = atmType;
                _serverIP = serverIP;
                _serverPort = serverPort;
                _clientVersion = AppConstants.APP_VERSION;
                _isConnected = false;
                _isRunning = false;
                _syncTracker = new JournalSyncTracker();
                _syncTracker.OnRecordChanged += r => OnJournalSyncChanged?.Invoke(r);
            }
    
    
            private readonly object _sendLock = new object();
    
    
            public bool Connect()
            {
                try
                {
                    if (_isConnected) return true;
    
                    OnLog?.Invoke("[Network] Connecting to " + _serverIP + ":" + _serverPort);
    
                    _tcpClient = new TcpClient();
                    _tcpClient.ReceiveTimeout = NetworkConfig.CONNECTION_TIMEOUT_MS;
                    _tcpClient.SendTimeout = NetworkConfig.CONNECTION_TIMEOUT_MS;
                    _tcpClient.ReceiveBufferSize = NetworkConfig.SOCKET_BUFFER_SIZE;
                    _tcpClient.SendBufferSize = NetworkConfig.SOCKET_BUFFER_SIZE;
                    _tcpClient.NoDelay = true;
    
                    var result = _tcpClient.BeginConnect(_serverIP, _serverPort, null, null);
                    bool connected = result.AsyncWaitHandle.WaitOne(NetworkConfig.CONNECTION_TIMEOUT_MS);
    
                    if (!connected)
                    {
                        OnLog?.Invoke("[Network] Connection timeout");
                        return false;
                    }
    
                    _tcpClient.EndConnect(result);
                    _stream = _tcpClient.GetStream();
    
                    // إرسال Handshake
                    if (!PerformHandshake())
                    {
                        Disconnect();
                        return false;
                    }
    
                    _isConnected = true;
                    _isRunning = true;
                    _lastHeartbeat = DateTime.Now;
    
                    // بدء خيط الاستقبال
                    _receiveThread = new Thread(ReceiveLoop);
                    _receiveThread.IsBackground = true;
                    _receiveThread.Start();
    
                    // بدء خيط Heartbeat
                    _heartbeatThread = new Thread(HeartbeatLoop);
                    _heartbeatThread.IsBackground = true;
                    _heartbeatThread.Start();
    
                    OnLog?.Invoke("[Network] Connected successfully");
                    OnConnected?.Invoke();
                    return true;
                }
                catch (Exception ex)
                {
                    OnLog?.Invoke("[Network] Connection failed: " + ex.Message);
                    OnError?.Invoke(ex);
                    return false;
                }
            }
    
    
            public void Disconnect()
            {
                _isRunning = false;
                _isConnected = false;
    
                try
                {
                    if (_stream != null) { _stream.Close(); _stream = null; }
                    if (_tcpClient != null) { _tcpClient.Close(); _tcpClient = null; }
                }
                catch { }
    
                OnLog?.Invoke("[Network] Disconnected");
                OnDisconnected?.Invoke();
            }
    
    
            public bool SendJournalData(string fileName, byte[] data, string checksum)
            {
                try
                {
                    if (!_isConnected) return false;
    
                    // بناء الهيدر: EJDATA|ATM_ID|FILENAME|LENGTH|CHECKSUM|TIMESTAMP
                    string header = Protocol.BuildMessage(
                        Protocol.DATA_JOURNAL,
                        _atmId,
                        fileName,
                        data.Length.ToString(),
                        checksum,
                        DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss")
                    );
    
                    lock (_sendLock)
                    {
                        // إرسال الهيدر
                        SendString(header + Protocol.HEADER_END);
    
                        // إرسال البيانات
                        _stream.Write(data, 0, data.Length);
                        _stream.Flush();
    
                        // إرسال نهاية البيانات
                        byte[] endMarker = Encoding.UTF8.GetBytes(Protocol.DATA_END);
                        _stream.Write(endMarker, 0, endMarker.Length);
                        _stream.Flush();
                    }
    
                    OnLog?.Invoke(string.Format("[Network] Sent {0} ({1} bytes)", fileName, data.Length));
                    return true;
                }
                catch (Exception ex)
                {
                    OnError?.Invoke(ex);
                    HandleConnectionLost();
                    return false;
                }
            }
    
    
            public bool SendFile(string fileName, byte[] fileData, string checksum)
            {
                try
                {
                    if (!_isConnected) return false;
    
                    string header = Protocol.BuildMessage(
                        Protocol.DATA_FILE,
                        _atmId,
                        fileName,
                        fileData.Length.ToString(),
                        checksum,
                        DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss")
                    );
    
                    lock (_sendLock)
                    {
                        SendString(header + Protocol.HEADER_END);
                        _stream.Write(fileData, 0, fileData.Length);
                        _stream.Flush();
                        byte[] endMarker = Encoding.UTF8.GetBytes(Protocol.DATA_END);
                        _stream.Write(endMarker, 0, endMarker.Length);
                        _stream.Flush();
                    }
    
                    OnLog?.Invoke(string.Format("[Network] Sent file {0} ({1} bytes)", fileName, fileData.Length));
                    return true;
                }
                catch (Exception ex)
                {
                    OnError?.Invoke(ex);
                    HandleConnectionLost();
                    return false;
                }
            }
    
    
            public bool SendStatus(string status, string cscStatus)
            {
                try
                {
                    if (!_isConnected) return false;
                    string msg = Protocol.BuildMessage(
                        Protocol.STATUS_RESPONSE,
                        _atmId,
                        status,
                        cscStatus,
                        DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss")
                    );
                    lock (_sendLock) { SendString(msg); }
                    return true;
                }
                catch (Exception ex)
                {
                    OnError?.Invoke(ex);
                    return false;
                }
            }
    
    
            public bool SendCommandResult(string commandId, bool success, string resultData)
            {
                try
                {
                    if (!_isConnected) return false;
                    string msg = Protocol.BuildMessage(
                        Protocol.CMD_RESULT,
                        _atmId,
                        commandId,
                        success ? "OK" : "FAIL",
                        resultData
                    );
                    lock (_sendLock) { SendString(msg); }
                    return true;
                }
                catch (Exception ex)
                {
                    OnError?.Invoke(ex);
                    return false;
                }
            }
    
    
            public bool Ping()
            {
                try
                {
                    var ping = new System.Net.NetworkInformation.Ping();
                    var reply = ping.Send(_serverIP, NetworkConfig.PING_TIMEOUT_MS);
                    return reply.Status == System.Net.NetworkInformation.IPStatus.Success;
                }
                catch { return false; }
            }
    
    
            private bool PerformHandshake()
            {
                try
                {
                    // إرسال: EJLIVE_HANDSHAKE|ATM_ID|ATM_TYPE|VERSION
                    string handshake = Protocol.BuildMessage(
                        Protocol.HANDSHAKE,
                        _atmId,
                        _atmType,
                        _clientVersion
                    );
                    SendString(handshake);
    
                    // انتظار الرد
                    string response = ReceiveString(5000);
                    if (string.IsNullOrEmpty(response))
                    {
                        OnLog?.Invoke("[Network] Handshake timeout - no response");
                        return false;
                    }
    
                    string[] parts = Protocol.ParseMessage(response);
                    if (parts.Length > 0 && parts[0] == Protocol.HANDSHAKE_ACK)
                    {
                        OnLog?.Invoke("[Network] Handshake successful");
                        return true;
                    }
    
                    OnLog?.Invoke("[Network] Handshake rejected: " + response);
                    return false;
                }
                catch (Exception ex)
                {
                    OnLog?.Invoke("[Network] Handshake error: " + ex.Message);
                    return false;
                }
            }
    
    
            private void ReceiveLoop()
            {
                byte[] buffer = new byte[NetworkConfig.SOCKET_BUFFER_SIZE];
                StringBuilder messageBuilder = new StringBuilder();
    
                while (_isRunning && _isConnected)
                {
                    try
                    {
                        if (_stream == null || !_tcpClient.Connected) break;
                        if (!_stream.DataAvailable)
                        {
                            Thread.Sleep(50);
                            continue;
                        }
    
                        int bytesRead = _stream.Read(buffer, 0, buffer.Length);
                        if (bytesRead == 0)
                        {
                            HandleConnectionLost();
                            break;
                        }
    
                        string received = Encoding.UTF8.GetString(buffer, 0, bytesRead);
                        messageBuilder.Append(received);
    
                        // معالجة الرسائل الكاملة
                        string fullMessage = messageBuilder.ToString();
                        int newlineIdx;
                        while ((newlineIdx = fullMessage.IndexOf('\n')) >= 0)
                        {
                            string msg = fullMessage.Substring(0, newlineIdx).Trim();
                            fullMessage = fullMessage.Substring(newlineIdx + 1);
    
                            if (!string.IsNullOrEmpty(msg))
                            {
                                ProcessReceivedMessage(msg);
                            }
                        }
                        messageBuilder.Clear();
                        if (fullMessage.Length > 0) messageBuilder.Append(fullMessage);
                    }
                    catch (Exception ex)
                    {
                        if (_isRunning)
                        {
                            OnError?.Invoke(ex);
                            HandleConnectionLost();
                        }
                        break;
                    }
                }
            }
    
    
            private void ProcessReceivedMessage(string message)
            {
