            public bool SendJournalData(string syncId, string fileName, byte[] data, string checksum)
            {
                JournalSyncRecord syncRecord = _syncTracker.BeginLocalSave(_atmId, fileName, data == null ? 0 : data.Length, checksum, null, syncId);
                try
                {
                    if (!_isConnected)
                    {
                        _syncTracker.MarkPending(syncRecord.SyncId);
                        return false;
                    }
                    if (data == null) data = new byte[0];
    
                    _syncTracker.MarkSyncing(syncRecord.SyncId, 40);
                    string payload = Convert.ToBase64String(data);
                    string message = Protocol.BuildMessage(
                        Protocol.DATA_JOURNAL,
                        _atmId,
                        fileName,
                        data.Length.ToString(),
                        checksum,
                        DateTime.UtcNow.ToString("O"),
                        payload,
                        syncRecord.SyncId
                    );
    
                    lock (_sendLock)
                    {
                        SendString(message);
                        lock (_ackLock) _pendingJournalAcks.Add(syncRecord.SyncId);
                    }
    
                    OnLog?.Invoke(string.Format("[Network] Sent {0} ({1} bytes)", fileName, data.Length));
                    return true;
                }
                catch (Exception ex)
                {
                    _syncTracker.MarkFailed(syncRecord.SyncId, ex.Message);
                    OnError?.Invoke(ex);
                    HandleConnectionLost();
                    return false;
                }
            }
    
    
