            }
    
    
            private void HandleDisconnect()
            {
                if (!_connected) return;
                _connected = false;
                _client?.Close();
                OnConnectionChanged?.Invoke(this, false);
                Log("✕ اتصال منقطع");
    
                if (_running)
                {
                    var t = new Thread(() =>
                    {
                        Thread.Sleep(2000);
                        TryConnect();
                    }) { IsBackground = true };
                    t.Start();
                }
            }
    
    
