            public bool SendStatus(string status, string cscStatus)
            {
                if (!_connected) return false;
                try
                {
                    string statusText = $"{Protocol.STATUS_RESPONSE}|{_atmId}|{status}|{cscStatus}|{DateTime.Now:yyyy-MM-dd HH:mm:ss}";
                    var frame = CommunicationProtocol.BuildCommandResult(_atmId + "|STATUS", true, statusText);
                    lock (_sendLock) { _stream.Write(frame, 0, frame.Length); _stream.Flush(); }
                    return true;
                }
                catch (Exception ex) { ReportError("SendStatus", ex); return false; }
            }
    
    
            public bool SendCommandResult(string commandId, bool success, string resultData)
            {
                if (!_connected) return false;
                try
                {
                    var frame = CommunicationProtocol.BuildCommandResult(commandId, success, resultData);
                    lock (_sendLock) { _stream.Write(frame, 0, frame.Length); _stream.Flush(); }
                    return true;
                }
                catch (Exception ex) { ReportError("SendCommandResult", ex); return false; }
            }
    
    
            public bool Ping()
            {
                try
                {
                    var ping = new System.Net.NetworkInformation.Ping();
                    var reply = ping.Send(_serverIp, NetworkConfig.PING_TIMEOUT_MS);
                    return reply.Status == System.Net.NetworkInformation.IPStatus.Success;
                }
                catch { return false; }
            }
    
    
