            {
                _atmId         = atmId;
                _atmType       = atmType;
                _serverIP      = serverIP;
                _serverPort    = serverPort;
                _clientVersion = AppConstants.APP_VERSION;
                _isConnected   = false;
                _isRunning     = false;
            }
    
    
