                    private bool PerformHandshake()
                    {
                        try
                        {
                            // إرسال: EJLIVE_HANDSHAKE|ATM_ID|ATM_TYPE|VERSION
                            string handshake = Protocol.BuildMessage(
                                Protocol.HANDSHAKE,
                                _atmId,
                                _atmType,
                                _clientVersion
                            );
                            SendString(handshake);
    
                            // انتظار الرد
                            string response = ReceiveString(5000);
                            if (string.IsNullOrEmpty(response))
                            {
                                OnLog?.Invoke("[Network] Handshake timeout - no response");
                                return false;
                            }
    
                            string[] parts = Protocol.ParseMessage(response);
                            if (parts.Length > 0 && parts[0] == Protocol.HANDSHAKE_ACK)
                            {
                                OnLog?.Invoke("[Network] Handshake successful");
                                return true;
                            }
    
                            OnLog?.Invoke("[Network] Handshake rejected: " + response);
                            return false;
                        }
                        catch (Exception ex)
                        {
                            OnLog?.Invoke("[Network] Handshake error: " + ex.Message);
                            return false;
                        }
                    }
    
                    private void ReceiveLoop()
                    {
                        byte[] buffer = new byte[NetworkConfig.SOCKET_BUFFER_SIZE];
                        StringBuilder messageBuilder = new StringBuilder();
    
                        while (_isRunning && _isConnected)
                        {
                            try
                            {
                                if (_stream == null || !_tcpClient.Connected) break;
                                if (!_stream.DataAvailable)
                                {
                                    Thread.Sleep(50);
                                    continue;
                                }
    
                                int bytesRead = _stream.Read(buffer, 0, buffer.Length);
                                if (bytesRead == 0)
                                {
                                    HandleConnectionLost();
                                    break;
                                }
    
                                string received = Encoding.UTF8.GetString(buffer, 0, bytesRead);
                                messageBuilder.Append(received);
    
                                // معالجة الرسائل الكاملة
                                string fullMessage = messageBuilder.ToString();
                                int newlineIdx;
                                while ((newlineIdx = fullMessage.IndexOf('\n')) >= 0)
                                {
                                    string msg = fullMessage.Substring(0, newlineIdx).Trim();
                                    fullMessage = fullMessage.Substring(newlineIdx + 1);
    
                                    if (!string.IsNullOrEmpty(msg))
                                    {
                                        ProcessReceivedMessage(msg);
                                    }
                                }
                                messageBuilder.Clear();
                                if (fullMessage.Length > 0) messageBuilder.Append(fullMessage);
                            }
                            catch (Exception ex)
                            {
                                if (_isRunning)
                                {
                                    OnError?.Invoke(ex);
                                    HandleConnectionLost();
                                }
                                break;
                            }
                        }
                    }
    
                    private void ProcessReceivedMessage(string message)
                    {
                        string[] parts = Protocol.ParseMessage(message);
                        if (parts.Length == 0) return;
    
                        string msgType = parts[0];
    
                        switch (msgType)
                        {
                            case Protocol.HEARTBEAT_ACK:
                                _lastHeartbeat = DateTime.Now;
                                break;
    
                            case Protocol.DATA_ACK:
                                OnLog?.Invoke("[Network] Data acknowledged by server");
                                break;
    
                            case Protocol.STATUS_REQUEST:
                                OnMessageReceived?.Invoke(message);
                                break;
    
                            case Protocol.CMD_RESTART:
                            case Protocol.CMD_SCREENSHOT:
                            case Protocol.CMD_TIMESYNC:
                            case Protocol.CMD_SHUTDOWN:
                            case Protocol.CMD_CHANGE_PASSWORD:
                            case Protocol.CMD_SEND_IMAGE:
                            case Protocol.CMD_UPDATE_CONFIG:
                            case Protocol.CMD_GET_SYSINFO:
                                OnCommandReceived?.Invoke(msgType, parts);
                                OnLog?.Invoke("[Network] Command received: " + msgType);
                                break;
    
                            default:
                                OnMessageReceived?.Invoke(message);
                                break;
                        }
                    }
    
                    private void HeartbeatLoop()
                    {
                        while (_isRunning && _isConnected)
                        {
                            try
                            {
                                Thread.Sleep(NetworkConfig.HEARTBEAT_INTERVAL_MS);
                                if (!_isRunning || !_isConnected) break;
    
                                string hb = Protocol.BuildMessage(
                                    Protocol.HEARTBEAT,
                                    _atmId,
                                    DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss")
                                );
    
                                lock (_sendLock) { SendString(hb); }
                            }
                            catch (Exception)
                            {
                                if (_isRunning) HandleConnectionLost();
                                break;
                            }
                        }
                    }
    
                    private void SendString(string message)
                    {
                        if (_stream == null) return;
                        byte[] data = Encoding.UTF8.GetBytes(message + "\n");
                        _stream.Write(data, 0, data.Length);
                        _stream.Flush();
                    }
    
                    private string ReceiveString(int timeoutMs)
                    {
                        byte[] buffer = new byte[4096];
                        _stream.ReadTimeout = timeoutMs;
                        try
                        {
                            int bytesRead = _stream.Read(buffer, 0, buffer.Length);
                            if (bytesRead > 0)
                                return Encoding.UTF8.GetString(buffer, 0, bytesRead).Trim();
                        }
                        catch (IOException) { }
                        return null;
                    }
    
                    private void HandleConnectionLost()
                    {
                        if (!_isConnected) return;
                        _isConnected = false;
                        OnLog?.Invoke("[Network] Connection lost");
                        OnDisconnected?.Invoke();
                    }
    
