            _reconnectPolicy = networkType switch
            {
                "GSM"  => RetryPolicy.GSM,
                "CDMA" => RetryPolicy.CDMA,
                "ADSL" => RetryPolicy.ADSL,
                _      => RetryPolicy.LAN
            };
            }
            public NetworkEngine(string serverIP, int serverPort, string deviceId, int heartbeatInterval = 30)
            _serverIP = serverIP;
            public NetworkEngine(string host, int port, string clientId)
            {
            _host = host;
            _port = port;
            _clientId = clientId;
            _circuitBreaker = new CircuitBreaker();
            _backoff = new ExponentialBackoffWithJitter();
            }
            public void Connect()
            {
            try
            {
                Disconnect();
                _client = new TcpClient();
                _client.Connect(_serverIP, _serverPort);
                _stream = _client.GetStream();
                _isConnected = true;
                SendLine("EJLIVE_HANDSHAKE|" + _atmId + "|" + _atmType + "|" + DateTime.Now.ToString("yyyyMMddHHmmss"));
                StartHeartbeat();
                StartReader();
                Log("Connected to server " + _serverIP + ":" + _serverPort);
                OnConnected?.Invoke();
            }
            catch (Exception ex)
            {
                _isConnected = false;
                OnError?.Invoke(ex);
                OnDisconnected?.Invoke();
            }
            }
            public void Disconnect()
            {
            bool wasConnected = _isConnected;
            _isConnected = false;
            try { _stream?.Close(); } catch { }
            try { _client?.Close(); } catch { }
            _stream = null;
            _client = null;
            if (wasConnected)
            {
                Log("Disconnected from server.");
                OnDisconnected?.Invoke();
            }
            }
            public bool SendJournalData(string fileName, byte[] rawData, string checksum)
            {
            if (!_isConnected || _stream == null) return false;
            try
            {
                byte[] compressed = CompressData(rawData);
                byte[] encrypted = EncryptAES256(compressed);
                string header = "EJDATA|" + _atmId + "|" + encrypted.Length + "|" + Sanitize(fileName) + "|" + Sanitize(checksum);
                byte[] headerBytes = Encoding.UTF8.GetBytes(header + "\n");
                _stream.Write(headerBytes, 0, headerBytes.Length);
                _stream.Write(encrypted, 0, encrypted.Length);
                _stream.Flush();
                return true;
            }
            catch (Exception ex)
            {
                OnError?.Invoke(ex);
                Disconnect();
                return false;
            }
            }
            public void SendTerminalProfile(string branchName, string vendor, string network, string region)
            {
            SendLine("STATUSMETA|" + _atmId + "|branch=" + Sanitize(branchName) + "|vendor=" + Sanitize(vendor) + "|network=" + Sanitize(network) + "|region=" + Sanitize(region));
            }
            public void SendCashStatus(int cass1, int cass2, int cass3, int cass4, int remaining, int loaded, int depositIn, int dispenseOut, int reject, int retract)
            {
            SendLine(
                "CASHSTATUS|" + _atmId +
                "|cass1=" + cass1 +
                "|cass2=" + cass2 +
                "|cass3=" + cass3 +
                "|cass4=" + cass4 +
                "|remaining=" + remaining +
                "|loaded=" + loaded +
                "|depositIn=" + depositIn +
                "|dispenseOut=" + dispenseOut +
                "|reject=" + reject +
                "|retract=" + retract);
            }
            public void SendCommandResult(string command, bool success, string message)
            {
            SendLine("CMD_RESULT|" + _atmId + "|" + Sanitize(command) + "|" + (success ? "OK" : "FAIL") + "|" + Sanitize(message));
            }
            public void SendFile(string fileName, byte[] data, string checksum)
            {
            if (!_isConnected || _stream == null || data == null) return;
            try
            {
                string header = "EJFILE|" + _atmId + "|" + data.Length + "|" + Sanitize(fileName) + "|" + Sanitize(checksum);
                byte[] headerBytes = Encoding.UTF8.GetBytes(header + "\n");
                _stream.Write(headerBytes, 0, headerBytes.Length);
                _stream.Write(data, 0, data.Length);
                _stream.Flush();
            }
            catch (Exception ex)
            {
                OnError?.Invoke(ex);
                Disconnect();
            }
            }
            public void SendRawData(byte[] data)
            {
            if (!_isConnected || _stream == null || data == null) return;
            try
            {
                _stream.Write(data, 0, data.Length);
                _stream.Flush();
            }
            catch (Exception ex)
            {
                OnError?.Invoke(ex);
                Disconnect();
            }
            }
            private void StartHeartbeat()
            {
            _heartbeatThread = new Thread(() =>
            {
                while (_isConnected)
                {
                try
                {
                    SendLine("HEARTBEAT|" + _atmId + "|" + DateTime.Now.ToString("yyyyMMddHHmmss"));
                    Thread.Sleep(30000);
                }
                catch
                {
                    Disconnect();
                    break;
                }
                }
            });
            _heartbeatThread.IsBackground = true;
            _heartbeatThread.Start();
            }
            private void StartReader()
            {
            _readThread = new Thread(() =>
            {
                byte[] buffer = new byte[8192];
                while (_isConnected)
                {
                try
                {
                    int bytesRead = _stream.Read(buffer, 0, buffer.Length);
                    if (bytesRead <= 0) break;
                    string payload = Encoding.UTF8.GetString(buffer, 0, bytesRead).Trim();
                    if (string.IsNullOrWhiteSpace(payload)) continue;
                    foreach (string line in payload.Split(new[] { '\n' }, StringSplitOptions.RemoveEmptyEntries))
                    {
                    HandleServerLine(line.Trim());
                    }
                }
                catch (Exception ex)
                {
                    OnError?.Invoke(ex);
                    break;
                }
                }
                Disconnect();
            });
            _readThread.IsBackground = true;
            _readThread.Start();
            }
            private void HandleServerLine(string line)
            {
            if (line.StartsWith("CMD|", StringComparison.OrdinalIgnoreCase))
            {
                string[] parts = line.Split('|');
                if (parts.Length >= 2)
                {
                string command = parts[1];
                string[] parameters = parts.Length > 2 ? new ArraySegment<string>(parts, 2, parts.Length - 2).ToArray() : new string[0];
                OnCommandReceived?.Invoke(command, parameters);
                }
            }
            }
            private void SendLine(string line)
            {
            if (!_isConnected || _stream == null) return;
            byte[] bytes = Encoding.UTF8.GetBytes(line + "\n");
            _stream.Write(bytes, 0, bytes.Length);
            _stream.Flush();
            }
            private static string Sanitize(string value)
            {
            if (string.IsNullOrWhiteSpace(value)) return "-";
            return value.Replace("|", "/").Replace("\r", " ").Replace("\n", " ").Trim();
            }
            private void Log(string message)
            {
            OnLog?.Invoke("[Network] " + message);
            }
            private static byte[] CompressData(byte[] data)
            {
            using (MemoryStream output = new MemoryStream())
            {
                using (DeflateStream deflate = new DeflateStream(output, CompressionMode.Compress))
                {
                deflate.Write(data, 0, data.Length);
                }
                return output.ToArray();
            }
            }
            private static byte[] EncryptAES256(byte[] data)
            {
            using (Aes aes = Aes.Create())
            {
                aes.Key = Encoding.UTF8.GetBytes(EJLive.Core.Constants.Encryption.AESKey);
                aes.IV = Encoding.UTF8.GetBytes(EJLive.Core.Constants.Encryption.AESIV);
                aes.Mode = CipherMode.CBC;
                aes.Padding = PaddingMode.PKCS7;
                using (ICryptoTransform encryptor = aes.CreateEncryptor())
                {
                return encryptor.TransformFinalBlock(data, 0, data.Length);
                }
            }
            }
            public bool Connect()
            {
            try
            {
                if (_isConnected) return true;
                OnLog?.Invoke("[Network] Connecting to " + _serverIP + ":" + _serverPort);
                _tcpClient = new TcpClient();
                _tcpClient.ReceiveTimeout = NetworkConfig.CONNECTION_TIMEOUT_MS;
                _tcpClient.SendTimeout = NetworkConfig.CONNECTION_TIMEOUT_MS;
                _tcpClient.ReceiveBufferSize = NetworkConfig.SOCKET_BUFFER_SIZE;
                _tcpClient.SendBufferSize = NetworkConfig.SOCKET_BUFFER_SIZE;
                _tcpClient.NoDelay = true;
                var result = _tcpClient.BeginConnect(_serverIP, _serverPort, null, null);
                bool connected = result.AsyncWaitHandle.WaitOne(NetworkConfig.CONNECTION_TIMEOUT_MS);
                if (!connected)
                {
                OnLog?.Invoke("[Network] Connection timeout");
                return false;
                }
                _tcpClient.EndConnect(result);
                _stream = _tcpClient.GetStream();
                // إرسال Handshake
                if (!PerformHandshake())
                {
                Disconnect();
                return false;
                }
                _isConnected = true;
                _isRunning = true;
                _lastHeartbeat = DateTime.Now;
                // بدء خيط الاستقبال
                _receiveThread = new Thread(ReceiveLoop);
                _receiveThread.IsBackground = true;
                _receiveThread.Start();
                // بدء خيط Heartbeat
                _heartbeatThread = new Thread(HeartbeatLoop);
                _heartbeatThread.IsBackground = true;
                _heartbeatThread.Start();
                OnLog?.Invoke("[Network] Connected successfully");
                OnConnected?.Invoke();
                return true;
            }
            catch (Exception ex)
            {
                OnLog?.Invoke("[Network] Connection failed: " + ex.Message);
                OnError?.Invoke(ex);
                return false;
            }
            }
            public void Disconnect()
            {
            _isRunning = false;
            _isConnected = false;
            try
            {
                if (_stream != null) { _stream.Close(); _stream = null; }
                if (_tcpClient != null) { _tcpClient.Close(); _tcpClient = null; }
            }
            catch { }
            OnLog?.Invoke("[Network] Disconnected");
            OnDisconnected?.Invoke();
            }
            public bool SendJournalData(string fileName, byte[] rawData, string checksum)
            {
            var payload = rawData ?? Array.Empty<byte>();
            var computedChecksum = string.IsNullOrWhiteSpace(checksum)
                ? SecurityHelper.SHA256Hash(payload)
                : checksum;
            return _engine.SendJournalFile(fileName ?? "journal.ej", payload, 0, computedChecksum);
            }
            public void SendTerminalProfile(string branchName, string vendor, string network, string region)
            {
            var payload = $"STATUSMETA|branch={Sanitize(branchName)}|vendor={Sanitize(vendor)}|network={Sanitize(network)}|region={Sanitize(region)}";
            _engine.SendMessage(CommunicationProtocol.BuildFrame(CommunicationProtocol.MsgType.Broadcast, payload));
            }
