                ? SecurityHelper.SHA256Hash(payload)
                : checksum;
            _engine.SendJournalFile(fileName ?? "payload.bin", payload, 0, computedChecksum);
            }
            public bool SendRawData(byte[] data)
            {
            try
            {
                if (!_isConnected || data == null || data.Length == 0) return false;
                lock (_sendLock)
                {
                _stream.Write(data, 0, data.Length);
                _stream.Flush();
                }
                return true;
            }
            catch (Exception ex)
            {
                OnError?.Invoke(ex);
                HandleConnectionLost();
                return false;
            }
            }
            private void HandleIncomingMessage(EJMessage message)
            {
            if (message.Type != CommunicationProtocol.MsgType.Command)
                return;
            if (RemoteCommandEnvelope.TryParse(message.Text, out var command))
            {
                var parameters = string.IsNullOrWhiteSpace(command.Payload)
                ? Array.Empty<string>()
                : command.Payload.Split(';', StringSplitOptions.RemoveEmptyEntries)
                    .Select(value => value.Trim())
                    .Where(value => value.Length > 0)
                    .ToArray();
                OnCommandReceived?.Invoke(command.CommandType, parameters);
                return;
            }
            if (!AppConfig.Load().AllowUnsignedLegacyCommands)
            {
                OnLog?.Invoke("[Network] Command rejected: signature verification failed and unsigned fallback is disabled.");
                return;
            }
            var fallbackParts = (message.Text ?? string.Empty).Split('|', StringSplitOptions.RemoveEmptyEntries);
            if (fallbackParts.Length == 0)
                return;
            OnCommandReceived?.Invoke(fallbackParts[0], fallbackParts.Skip(1).ToArray());
            }
            public void Dispose()
            {
            _engine.Dispose();
            }
            public void SendCommandResult(string commandId, bool success, string message)
            {
            SendLine(
                "CMD_RESULT|" +
                _atmId + "|" +
                Sanitize(commandId) + "|" +
                (success ? "ACK" : "FAILED") + "|" +
                Sanitize(message) + "|" +
                DateTime.Now.ToString("yyyyMMddHHmmss"));
            }
            private void HandleServerLine(string line)
            {
            if (line.StartsWith("CMD|", StringComparison.OrdinalIgnoreCase))
            {
                string[] parts = line.Split('|');
                if (parts.Length >= 3)
                {
                string commandId = parts[1];
                string command = parts[2];
                string[] parameters = parts.Length > 3 ? new ArraySegment<string>(parts, 3, parts.Length - 3).ToArray() : new string[0];
                OnCommandReceived?.Invoke(commandId, command, parameters);
                }
            }
            }
            private readonly object _sendLock = new object();
            private readonly object _ackLock = new object();
            private readonly HashSet<string> _pendingJournalAcks = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            public bool SendJournalData(string fileName, byte[] data, string checksum)
            {
            return SendJournalData(null, fileName, data, checksum);
            }
            public bool SendJournalData(string syncId, string fileName, byte[] data, string checksum)
            {
            JournalSyncRecord syncRecord = _syncTracker.BeginLocalSave(_atmId, fileName, data == null ? 0 : data.Length, checksum, null, syncId);
            try
            {
                if (!_isConnected)
                {
                _syncTracker.MarkPending(syncRecord.SyncId);
                return false;
                }
                if (data == null) data = new byte[0];
                _syncTracker.MarkSyncing(syncRecord.SyncId, 40);
                string payload = Convert.ToBase64String(data);
                string message = Protocol.BuildMessage(
                Protocol.DATA_JOURNAL,
                _atmId,
                fileName,
                data.Length.ToString(),
                checksum,
                DateTime.UtcNow.ToString("O"),
                payload,
                syncRecord.SyncId
                );
                lock (_sendLock)
                {
                SendString(message);
                lock (_ackLock) _pendingJournalAcks.Add(syncRecord.SyncId);
                }
                OnLog?.Invoke(string.Format("[Network] Sent {0} ({1} bytes)", fileName, data.Length));
                return true;
            }
            catch (Exception ex)
            {
                _syncTracker.MarkFailed(syncRecord.SyncId, ex.Message);
                OnError?.Invoke(ex);
                HandleConnectionLost();
                return false;
            }
            }
            public bool SendFile(string fileName, byte[] fileData, string checksum)
            {
            try
            {
                if (!_isConnected) return false;
                if (fileData == null) fileData = new byte[0];
                string payload = Convert.ToBase64String(fileData);
                string message = Protocol.BuildMessage(
                Protocol.DATA_FILE,
                _atmId,
                fileName,
                fileData.Length.ToString(),
                checksum,
                DateTime.UtcNow.ToString("O"),
                payload
                );
                lock (_sendLock)
                {
                SendString(message);
                }
                OnLog?.Invoke(string.Format("[Network] Sent file {0} ({1} bytes)", fileName, fileData.Length));
                return true;
            }
            catch (Exception ex)
            {
                OnError?.Invoke(ex);
                HandleConnectionLost();
                return false;
            }
            }
            public bool SendStatus(string status, string cscStatus)
            {
            try
            {
                if (!_isConnected) return false;
                string msg = Protocol.BuildMessage(
                Protocol.STATUS_RESPONSE,
                _atmId,
                status,
                cscStatus,
                DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss")
                );
                lock (_sendLock) { SendString(msg); }
                return true;
            }
            catch (Exception ex)
            {
                OnError?.Invoke(ex);
                return false;
            }
            }
            public bool SendCommandResult(string commandId, bool success, string resultData)
            {
            try
            {
                if (!_isConnected) return false;
                string msg = Protocol.BuildMessage(
                Protocol.CMD_RESULT,
                _atmId,
                commandId,
                success ? "OK" : "FAIL",
                resultData
                );
                lock (_sendLock) { SendString(msg); }
                return true;
            }
            catch (Exception ex)
            {
                OnError?.Invoke(ex);
                return false;
            }
            }
            public bool Ping()
            {
            try
            {
                var ping = new System.Net.NetworkInformation.Ping();
                var reply = ping.Send(_serverIP, NetworkConfig.PING_TIMEOUT_MS);
                return reply.Status == System.Net.NetworkInformation.IPStatus.Success;
            }
            catch { return false; }
            }
            private bool PerformHandshake()
            {
            try
            {
                // إرسال: EJLIVE_HANDSHAKE|ATM_ID|ATM_TYPE|VERSION
                string handshake = Protocol.BuildMessage(
                Protocol.HANDSHAKE,
                _atmId,
                _atmType,
                _clientVersion
                );
                SendString(handshake);
                // انتظار الرد
                string response = ReceiveString(5000);
                if (string.IsNullOrEmpty(response))
                {
                OnLog?.Invoke("[Network] Handshake timeout - no response");
                return false;
                }
                string[] parts = Protocol.ParseMessage(response);
                if (parts.Length > 0 && parts[0] == Protocol.HANDSHAKE_ACK)
                {
                OnLog?.Invoke("[Network] Handshake successful");
                return true;
                }
                OnLog?.Invoke("[Network] Handshake rejected: " + response);
                return false;
            }
            catch (Exception ex)
            {
                OnLog?.Invoke("[Network] Handshake error: " + ex.Message);
                return false;
            }
            }
            private void ReceiveLoop()
            {
            byte[] buffer = new byte[NetworkConfig.SOCKET_BUFFER_SIZE];
            StringBuilder messageBuilder = new StringBuilder();
            while (_isRunning && _isConnected)
            {
                try
                {
                if (_stream == null || !_tcpClient.Connected) break;
                if (!_stream.DataAvailable)
                {
                    Thread.Sleep(50);
                    continue;
                }
                int bytesRead = _stream.Read(buffer, 0, buffer.Length);
                if (bytesRead == 0)
                {
                    HandleConnectionLost();
                    break;
                }
                string received = Encoding.UTF8.GetString(buffer, 0, bytesRead);
                messageBuilder.Append(received);
                // معالجة الرسائل الكاملة
                string fullMessage = messageBuilder.ToString();
                int newlineIdx;
                while ((newlineIdx = fullMessage.IndexOf('\n')) >= 0)
                {
                    string msg = fullMessage.Substring(0, newlineIdx).Trim();
                    fullMessage = fullMessage.Substring(newlineIdx + 1);
                    if (!string.IsNullOrEmpty(msg))
                    {
                    ProcessReceivedMessage(msg);
                    }
                }
                messageBuilder.Clear();
                if (fullMessage.Length > 0) messageBuilder.Append(fullMessage);
                }
                catch (Exception ex)
                {
                if (_isRunning)
                {
                    OnError?.Invoke(ex);
                    HandleConnectionLost();
                }
                break;
                }
            }
            }
            private void ProcessReceivedMessage(string message)
            {
            string[] parts = Protocol.ParseMessage(message);
            if (parts.Length == 0) return;
            string msgType = parts[0];
            switch (msgType)
            {
                case Protocol.HEARTBEAT_ACK:
                _lastHeartbeat = DateTime.Now;
                break;
                case Protocol.DATA_ACK:
                CompleteOldestJournalAck(parts);
                OnLog?.Invoke("[Network] Data acknowledged by server");
                break;
                case Protocol.DATA_NACK:
                MarkJournalNack(parts);
                OnLog?.Invoke("[Network] Data rejected by server");
                break;
                case Protocol.STATUS_REQUEST:
                OnMessageReceived?.Invoke(message);
                break;
                case Protocol.CMD_RESTART:
                case Protocol.CMD_SCREENSHOT:
                case Protocol.CMD_TIMESYNC:
                case Protocol.CMD_SHUTDOWN:
                case Protocol.CMD_CHANGE_PASSWORD:
                case Protocol.CMD_SEND_IMAGE:
                case Protocol.CMD_IMAGE_SYNC:
                case Protocol.CMD_FORCE_SYNC:
                case Protocol.CMD_GHOST_START:
                case Protocol.CMD_GHOST_STOP:
                case Protocol.CMD_MESSAGE:
                case Protocol.CMD_UPDATE_CONFIG:
                case Protocol.CMD_GET_SYSINFO:
                OnCommandReceived?.Invoke(msgType, parts);
                OnLog?.Invoke("[Network] Command received: " + msgType);
                break;
                default:
                OnMessageReceived?.Invoke(message);
                break;
            }
            }
            private void HeartbeatLoop()
            {
            while (_isRunning && _isConnected)
            {
                try
                {
                Thread.Sleep(NetworkConfig.HEARTBEAT_INTERVAL_MS);
                if (!_isRunning || !_isConnected) break;
                string hb = Protocol.BuildMessage(
                    Protocol.HEARTBEAT,
                    _atmId,
                    DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss")
                );
                lock (_sendLock) { SendString(hb); }
                }
                catch (Exception)
                {
                if (_isRunning) HandleConnectionLost();
                break;
                }
            }
            }
            private void SendString(string message)
            {
            if (_stream == null) return;
            byte[] data = Encoding.UTF8.GetBytes(message + "\n");
            _stream.Write(data, 0, data.Length);
            _stream.Flush();
            }
            private string ReceiveString(int timeoutMs)
            {
            byte[] buffer = new byte[4096];
            _stream.ReadTimeout = timeoutMs;
            try
            {
                int bytesRead = _stream.Read(buffer, 0, buffer.Length);
                if (bytesRead > 0)
                return Encoding.UTF8.GetString(buffer, 0, bytesRead).Trim();
            }
            catch (IOException) { }
            return null;
            }
            private void HandleConnectionLost()
            {
            if (!_isConnected) return;
            _isConnected = false;
            OnLog?.Invoke("[Network] Connection lost");
            OnDisconnected?.Invoke();
            }
            private void CompleteOldestJournalAck(string[] parts)
            {
            string syncId = parts.Length > 1 ? parts[1] : null;
            lock (_ackLock)
            {
                if (string.IsNullOrEmpty(syncId) && _pendingJournalAcks.Count > 0)
                {
                foreach (string pendingId in _pendingJournalAcks)
                {
                    syncId = pendingId;
                    break;
                }
                }
                if (!string.IsNullOrEmpty(syncId))
                _pendingJournalAcks.Remove(syncId);
            }
            if (!string.IsNullOrEmpty(syncId))
                _syncTracker.MarkCompleted(syncId, "Server acknowledged journal storage");
            }
            private void MarkJournalNack(string[] parts)
            {
            string syncId = parts.Length > 1 ? parts[1] : null;
            string message = parts.Length > 2 ? string.Join(" ", parts, 2, parts.Length - 2) : "Server rejected journal payload";
            lock (_ackLock)
            {
                if (!string.IsNullOrEmpty(syncId))
                _pendingJournalAcks.Remove(syncId);
            }
            if (!string.IsNullOrEmpty(syncId))
                _syncTracker.MarkFailed(syncId, message);
            }
            public bool SendJournalData(string fileName, byte[] data, string checksum)
            {
            try
            {
                if (!_isConnected) return false;
                // بناء الهيدر: EJDATA|ATM_ID|FILENAME|LENGTH|CHECKSUM|TIMESTAMP
                string header = Protocol.BuildMessage(
                Protocol.DATA_JOURNAL,
                _atmId,
                fileName,
                data.Length.ToString(),
                checksum,
                DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss")
                );
                lock (_sendLock)
                {
                // إرسال الهيدر
                SendString(header + Protocol.HEADER_END);
                // إرسال البيانات
                _stream.Write(data, 0, data.Length);
                _stream.Flush();
                // إرسال نهاية البيانات
                byte[] endMarker = Encoding.UTF8.GetBytes(Protocol.DATA_END);
                _stream.Write(endMarker, 0, endMarker.Length);
                _stream.Flush();
                }
                OnLog?.Invoke(string.Format("[Network] Sent {0} ({1} bytes)", fileName, data.Length));
                return true;
            }
            catch (Exception ex)
            {
                OnError?.Invoke(ex);
                HandleConnectionLost();
                return false;
            }
            }
            public bool SendFile(string fileName, byte[] fileData, string checksum)
            {
            try
            {
                if (!_isConnected) return false;
                string header = Protocol.BuildMessage(
                Protocol.DATA_FILE,
                _atmId,
                fileName,
                fileData.Length.ToString(),
                checksum,
                DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss")
                );
                lock (_sendLock)
                {
                SendString(header + Protocol.HEADER_END);
                _stream.Write(fileData, 0, fileData.Length);
                _stream.Flush();
                byte[] endMarker = Encoding.UTF8.GetBytes(Protocol.DATA_END);
                _stream.Write(endMarker, 0, endMarker.Length);
                _stream.Flush();
                }
                OnLog?.Invoke(string.Format("[Network] Sent file {0} ({1} bytes)", fileName, fileData.Length));
                return true;
            }
            catch (Exception ex)
            {
                OnError?.Invoke(ex);
                HandleConnectionLost();
                return false;
            }
            }
            private void ProcessReceivedMessage(string message)
            {
            string[] parts = Protocol.ParseMessage(message);
            if (parts.Length == 0) return;
            string msgType = parts[0];
            switch (msgType)
            {
                case Protocol.HEARTBEAT_ACK:
                _lastHeartbeat = DateTime.Now;
                break;
                case Protocol.DATA_ACK:
                OnLog?.Invoke("[Network] Data acknowledged by server");
                break;
                case Protocol.STATUS_REQUEST:
                OnMessageReceived?.Invoke(message);
                break;
                case Protocol.CMD_RESTART:
                case Protocol.CMD_SCREENSHOT:
                case Protocol.CMD_TIMESYNC:
                case Protocol.CMD_SHUTDOWN:
                case Protocol.CMD_CHANGE_PASSWORD:
                case Protocol.CMD_SEND_IMAGE:
                case Protocol.CMD_UPDATE_CONFIG:
                case Protocol.CMD_GET_SYSINFO:
                OnCommandReceived?.Invoke(msgType, parts);
                OnLog?.Invoke("[Network] Command received: " + msgType);
                break;
                default:
                OnMessageReceived?.Invoke(message);
                break;
            }
            }
            private readonly BlockingCollection<int> _chunkAcks =
            new BlockingCollection<int>(10000);
            private readonly BlockingCollection<EJMessage> _journalAcks =
            new BlockingCollection<EJMessage>(1000);
            private bool TryConnect()
            {
            for (int attempt = 1; attempt <= _reconnectPolicy.MaxAttempts; attempt++)
            {
                if (!_running) return false;
                try
                {
                Log($"محاولة اتصال {attempt}/{_reconnectPolicy.MaxAttempts} - {_serverIp}:{_serverPort}");
                _client = new TcpClient();
                _client.ReceiveTimeout = AppConstants.SocketTimeoutMs;
                _client.SendTimeout    = AppConstants.SocketTimeoutMs;
                _client.Connect(_serverIp, _serverPort);
                _stream = _client.GetStream();
                // RSA/AES Handshake (S-06)
                PerformRSAHandshake();
                SendHandshake();
                _connected      = true;
                ConnectedAt     = DateTime.UtcNow;
                ReconnectAttempts = attempt;
                OnConnectionChanged?.Invoke(this, true);
                OnSessionEstablished?.Invoke(this, SessionId);
                Log($"متصل - Session: {SessionId}");
                // بدء Heartbeat + Receive threads
                StartHeartbeat();
                StartReceive();
                // استئناف الطابور المعلق (L-02)
                ResumeOutbox();
                return true;
                }
                catch (Exception ex)
                {
                ReportError("Connect", ex);
                _client?.Close();
                _connected = false;
                OnConnectionChanged?.Invoke(this, false);
                if (attempt < _reconnectPolicy.MaxAttempts)
                {
                    var delay = _reconnectPolicy.ComputeDelay(attempt);
                    Log($"إعادة المحاولة بعد {delay}ms...");
                    Thread.Sleep(delay);
                }
                }
            }
            return false;
            }
            private void PerformRSAHandshake()
            {
            // 1. استلام RSA Public Key من السيرفر
            var rsaMsg     = CommunicationProtocol.ReadMessage(_stream);
            if (rsaMsg.Type != CommunicationProtocol.MsgType.RsaPublicKey)
                throw new InvalidOperationException("Expected RSA Public Key from server");
            var serverPublicKey = rsaMsg.Text;
            // 2. توليد AES Session Key وتشفيره بـ RSA
            _sessionKey    = SecurityHelper.GenerateSessionKey();
            var encAesKey  = SecurityHelper.EncryptWithRSAPublicKey(_sessionKey, serverPublicKey);
            var aesMsg     = CommunicationProtocol.BuildAesSessionKey(encAesKey);
            _stream.Write(aesMsg, 0, aesMsg.Length);
            Log("RSA/AES Handshake completed - Encrypted session established");
            }
            private void SendHandshake()
            {
            var frame = CommunicationProtocol.BuildHandshake(_atmId, _atmType, AppConstants.AppVersion);
            _stream.Write(frame, 0, frame.Length);
            var response  = CommunicationProtocol.ReadMessage(_stream, _sessionKey);
            if (response.Type != CommunicationProtocol.MsgType.HandshakeAck)
                throw new InvalidOperationException("Handshake ACK not received");
            var parts = response.Text.Split('|');
            SessionId = parts.Length > 2 ? parts[2] : Guid.NewGuid().ToString("N");
            }
            private void StartHeartbeat()
            {
            _heartbeatThread?.Abort();
            _heartbeatThread = new Thread(HeartbeatLoop) { IsBackground = true, Name = "EJLive.Heartbeat" };
            _heartbeatThread.Start();
            }
            private void HeartbeatLoop()
            {
            _lastHeartbeatAck = DateTime.UtcNow;
            while (_running && _connected)
            {
                try
                {
                Thread.Sleep(AppConstants.HeartbeatIntervalSec * 1000);
                if (!_connected) break;
                // فحص: هل مضى وقت أكثر من 3× Heartbeat دون رد؟
                if ((DateTime.UtcNow - _lastHeartbeatAck).TotalSeconds > AppConstants.HeartbeatTimeoutSec)
                {
                    Log("Heartbeat timeout - reconnecting...");
                    HandleDisconnect();
                    break;
                }
                var hb = CommunicationProtocol.BuildHeartbeat(_atmId, BuildHeartbeatStatsPayload());
                lock (_sendLock) _stream.Write(hb, 0, hb.Length);
                }
                catch { break; }
            }
            }
            private void StartReceive()
            {
            _receiveThread = new Thread(ReceiveLoop) { IsBackground = true, Name = "EJLive.Receive" };
            _receiveThread.Start();
            }
            private void ReceiveLoop()
            {
            while (_running && _connected)
            {
                try
                {
                var msg = CommunicationProtocol.ReadMessage(_stream, _sessionKey);
                TotalBytesReceived += msg.Payload?.Length ?? 0;
                if (msg.Type == CommunicationProtocol.MsgType.HeartbeatAck)
                {
                    _lastHeartbeatAck = DateTime.UtcNow;
                    continue;
                }
                if (msg.Type == CommunicationProtocol.MsgType.ChunkAck)
                {
                    if (msg.Payload != null && msg.Payload.Length >= 4)
                    _chunkAcks.TryAdd(BitConverter.ToInt32(msg.Payload, 0));
                    continue;
                }
                if (msg.Type == CommunicationProtocol.MsgType.JournalAck)
                {
                    _journalAcks.TryAdd(msg);
                    continue;
                }
                if (msg.Type == CommunicationProtocol.MsgType.Disconnect)
                {
                    HandleDisconnect();
                    break;
                }
                OnMessageReceived?.Invoke(this, msg);
                }
                catch (IOException) { HandleDisconnect(); break; }
                catch (Exception ex) { ReportError("Receive", ex); break; }
            }
            }
            public bool SendStatus(string status, string cscStatus)
            {
            if (!_connected) return false;
            try
            {
                string statusText = $"{Protocol.STATUS_RESPONSE}|{_atmId}|{status}|{cscStatus}|{DateTime.Now:yyyy-MM-dd HH:mm:ss}";
                var frame = CommunicationProtocol.BuildCommandResult(_atmId + "|STATUS", true, statusText);
                lock (_sendLock) { _stream.Write(frame, 0, frame.Length); _stream.Flush(); }
                return true;
            }
            catch (Exception ex) { ReportError("SendStatus", ex); return false; }
            }
            public bool SendCommandResult(string commandId, bool success, string resultData)
            {
            if (!_connected) return false;
            try
            {
                var frame = CommunicationProtocol.BuildCommandResult(commandId, success, resultData);
                lock (_sendLock) { _stream.Write(frame, 0, frame.Length); _stream.Flush(); }
                return true;
            }
            catch (Exception ex) { ReportError("SendCommandResult", ex); return false; }
            }
            public bool Ping()
            {
            try
            {
                var ping = new System.Net.NetworkInformation.Ping();
                var reply = ping.Send(_serverIp, NetworkConfig.PING_TIMEOUT_MS);
                return reply.Status == System.Net.NetworkInformation.IPStatus.Success;
            }
            catch { return false; }
            }
            private void ResumeOutbox()
            {
            if (_outbox == null) return;
            var thread = new Thread(() =>
            {
                while (_running && _connected)
                {
                Thread.Sleep(100);
                if (_outbox.TryDequeue(out var item))
                {
                    if (!item.IsReadyToSend) { _outbox.Enqueue(item); Thread.Sleep(200); continue; }
                    var success  = SendJournalFile(item.FileName, item.Data, item.Offset, item.Checksum);
                    if (success)
                    _outbox.MarkCompleted(item.ItemId);
                    else
                    {
                    var delay = _reconnectPolicy.ComputeDelay(item.RetryCount + 1);
                    _outbox.RetryItem(item.ItemId, delay);
                    }
                }
                }
            }) { IsBackground = true, Name = "EJLive.OutboxSender" };
            thread.Start();
            }
            public void SendMessage(byte[] frame)
            {
            if (!_connected) return;
            lock (_sendLock) { _stream.Write(frame, 0, frame.Length); _stream.Flush(); }
            }
            private bool WaitForChunkAck(int seqNum)
            {
            var deadline = DateTime.UtcNow.AddMilliseconds(AppConstants.SocketTimeoutMs);
            while (_connected && DateTime.UtcNow < deadline)
            {
                var remaining = Math.Max(50, (int)(deadline - DateTime.UtcNow).TotalMilliseconds);
                if (_chunkAcks.TryTake(out var ackSeq, Math.Min(remaining, 500)) && ackSeq == seqNum)
                return true;
            }
            Log($"CHUNK_ACK timeout seq={seqNum}");
            return false;
            }
            private bool WaitForJournalAck(string fileName)
            {
            var deadline = DateTime.UtcNow.AddMilliseconds(AppConstants.SocketTimeoutMs);
            while (_connected && DateTime.UtcNow < deadline)
            {
                var remaining = Math.Max(50, (int)(deadline - DateTime.UtcNow).TotalMilliseconds);
                if (!_journalAcks.TryTake(out var ack, Math.Min(remaining, 500)))
                continue;
                var text = ack.Text ?? string.Empty;
                if (!string.IsNullOrWhiteSpace(fileName) &&
                text.IndexOf(fileName, StringComparison.OrdinalIgnoreCase) < 0)
                continue;
                return text.IndexOf("OK", StringComparison.OrdinalIgnoreCase) >= 0;
            }
            Log($"JOURNAL_ACK timeout file={fileName}");
            return false;
            }
            private void HandleDisconnect()
            {
            if (!_connected) return;
            _connected = false;
            _client?.Close();
            OnConnectionChanged?.Invoke(this, false);
            Log("اتصال منقطع");
            if (_running)
            {
                var t = new Thread(() =>
                {
                Thread.Sleep(2000);
                TryConnect();
                }) { IsBackground = true };
                t.Start();
            }
            }
            private string BuildHeartbeatStatsPayload()
            {
            try
            {
                var process = Process.GetCurrentProcess();
                var uptimeMs = Math.Max(1.0, (double)(Environment.TickCount & int.MaxValue));
                var cpu = (process.TotalProcessorTime.TotalMilliseconds / (Environment.ProcessorCount * uptimeMs)) * 100.0;
                cpu = Math.Max(0.0, Math.Min(100.0, cpu));
                var memMb = process.WorkingSet64 / 1024.0 / 1024.0;
                var memPct = Math.Max(0.0, Math.Min(100.0, (memMb / 2048.0) * 100.0));
                var root = Path.GetPathRoot(Environment.SystemDirectory);
                var drives = DriveInfo.GetDrives();
                DriveInfo drive = null;
                if (!string.IsNullOrWhiteSpace(root))
                drive = Array.Find(drives, d => d.IsReady && string.Equals(d.Name, root, StringComparison.OrdinalIgnoreCase));
                var diskPct = drive != null && drive.TotalSize > 0
                ? ((drive.TotalSize - drive.TotalFreeSpace) * 100.0 / drive.TotalSize)
                : 0.0;
                diskPct = Math.Max(0.0, Math.Min(100.0, diskPct));
                var health = 100;
                if (cpu > 85) health -= 10;
                if (memPct > 85) health -= 10;
                if (diskPct > 95) health -= 20;
                health = Math.Max(0, Math.Min(100, health));
                return $"CPU={cpu:F1};MEM={memPct:F1};DISK={diskPct:F1};HEALTH={health}";
            }
            catch
            {
                return "CPU=0;MEM=0;DISK=0;HEALTH=80";
            }
            }
            private void UpdateSpeed(long bytes)
            {
            SpeedKBs = bytes / 1024.0;
            }
            private void ReportError(string context, Exception ex)
            {
            var message = $"{context}: {ex.Message}";
            Log(message);
            OnError?.Invoke(this, message);
            }
            private void Log(string msg) => OnLog?.Invoke(this, msg);
            public void Dispose()
            {
            if (!_disposed)
            {
                _disposed = true;
                _cts?.Cancel();
                _cts?.Dispose();
                Cleanup();
            }
            }
            private bool TryConnect()
            {
            for (int attempt = 1; attempt <= _reconnectPolicy.MaxAttempts; attempt++)
            {
                if (!_running) return false;
                try
                {
                Log($"محاولة اتصال {attempt}/{_reconnectPolicy.MaxAttempts} → {_serverIp}:{_serverPort}");
                _client = new TcpClient();
                _client.ReceiveTimeout = AppConstants.SocketTimeoutMs;
                _client.SendTimeout    = AppConstants.SocketTimeoutMs;
                _client.Connect(_serverIp, _serverPort);
                _stream = _client.GetStream();
                // RSA/AES Handshake (S-06)
                PerformRSAHandshake();
                SendHandshake();
                _connected      = true;
                ConnectedAt     = DateTime.UtcNow;
                ReconnectAttempts = attempt;
                OnConnectionChanged?.Invoke(this, true);
                OnSessionEstablished?.Invoke(this, SessionId);
                Log($"✓ متصل — Session: {SessionId}");
                // بدء Heartbeat + Receive threads
                StartHeartbeat();
                StartReceive();
                // استئناف الطابور المعلق (L-02)
                ResumeOutbox();
                return true;
                }
                catch (Exception ex)
                {
                Log($"فشل الاتصال: {ex.Message}");
                _client?.Close();
                _connected = false;
                OnConnectionChanged?.Invoke(this, false);
                if (attempt < _reconnectPolicy.MaxAttempts)
                {
                    var delay = _reconnectPolicy.ComputeDelay(attempt);
                    Log($"إعادة المحاولة بعد {delay}ms...");
                    Thread.Sleep(delay);
                }
                }
            }
            return false;
            }
            private void PerformRSAHandshake()
            {
            // 1. استلام RSA Public Key من السيرفر
            var rsaMsg     = CommunicationProtocol.ReadMessage(_stream);
            if (rsaMsg.Type != CommunicationProtocol.MsgType.RsaPublicKey)
                throw new InvalidOperationException("Expected RSA Public Key from server");
            var serverPublicKey = rsaMsg.Text;
            // 2. توليد AES Session Key وتشفيره بـ RSA
            _sessionKey    = SecurityHelper.GenerateSessionKey();
            var encAesKey  = SecurityHelper.EncryptWithRSAPublicKey(_sessionKey, serverPublicKey);
            var aesMsg     = CommunicationProtocol.BuildAesSessionKey(encAesKey);
            _stream.Write(aesMsg, 0, aesMsg.Length);
            Log("★ RSA/AES Handshake completed — Encrypted session established");
            }
            private void ResumeOutbox()
            {
            if (_outbox == null) return;
            var thread = new Thread(() =>
            {
                while (_running && _connected)
                {
                Thread.Sleep(100);
                if (_outbox.TryDequeue(out var item))
                {
                    if (!item.IsReadyToSend) { _outbox.Enqueue(item); Thread.Sleep(200); continue; }
                    var compData = SecurityHelper.Compress(item.Data);
                    var success  = SendJournalFile(item.FileName, compData, item.Offset, item.Checksum);
                    if (success)
                    _outbox.MarkCompleted(item.ItemId);
                    else
                    {
                    var delay = _reconnectPolicy.ComputeDelay(item.RetryCount + 1);
                    _outbox.RetryItem(item.ItemId, delay);
                    }
                }
                }
            }) { IsBackground = true, Name = "EJLive.OutboxSender" };
            thread.Start();
            }
            private void HandleDisconnect()
            {
            if (!_connected) return;
            _connected = false;
            _client?.Close();
            OnConnectionChanged?.Invoke(this, false);
            Log("✕ اتصال منقطع");
            if (_running)
            {
                var t = new Thread(() =>
                {
                Thread.Sleep(2000);
                TryConnect();
                }) { IsBackground = true };
                t.Start();
            }
            }
            _retryPolicy = new RetryPolicy(maxAttempts: 10, baseDelayMs: 5000, useExponentialBackoff: true, useJitter: true);
            public async Task<bool> ConnectAsync(CancellationToken ct = default)
            {
            if (_isConnected) return true;
            if (!_circuitBreaker.AllowRequest()) return false;
            try
            {
                _tcpClient = new TcpClient { NoDelay = true, ReceiveTimeout = 30000, SendTimeout = 30000 };
                await _tcpClient.ConnectAsync(_host, _port, ct).ConfigureAwait(false);
                _stream = _tcpClient.GetStream();
                _isConnected = true;
                _cts = CancellationTokenSource.CreateLinkedTokenSource(ct);
                _circuitBreaker.RecordSuccess();
                _backoff.Reset();
                // Start IO loops
                _readLoopTask = ReadLoopAsync(_cts.Token);
                _sendLoopTask = SendLoopAsync(_cts.Token);
                _heartbeatTask = HeartbeatLoopAsync(_cts.Token);
                // Perform handshake
                await SendHandshakeAsync(_cts.Token).ConfigureAwait(false);
                OnConnected?.Invoke();
                Log("Connected successfully.");
                return true;
            }
            catch (Exception ex)
            {
                _circuitBreaker.RecordFailure();
                Log($"Connection failed: {ex.Message}");
                OnError?.Invoke(ex);
                return false;
            }
            }
            public async Task DisconnectAsync(string reason = "Manual disconnect")
            {
            _isConnected = false;
            _cts?.Cancel();
            Cleanup();
            OnDisconnected?.Invoke(reason);
            Log($"Disconnected: {reason}");
            }
            public void EnqueueSend(TransportMessage message)
            {
            _sendQueue.Enqueue(message);
            }
            public async Task<bool> SendAsync(TransportMessage message, CancellationToken ct = default)
            {
            if (!_isConnected || _stream == null) return false;
            try
            {
                var data = Encoding.UTF8.GetBytes(SerializeMessage(message));
                await _stream.WriteAsync(data, 0, data.Length, ct).ConfigureAwait(false);
                await _stream.FlushAsync(ct).ConfigureAwait(false);
                BytesSent += data.Length;
                return true;
            }
            catch (Exception ex)
            {
                Log($"Send failed: {ex.Message}");
                return false;
            }
            }
            public bool TryDequeueReceived(out TransportMessage message)
            {
            return _receiveQueue.TryDequeue(out message!);
            }
            private async Task ReadLoopAsync(CancellationToken ct)
            {
            var buffer = new byte[65536];
            while (!ct.IsCancellationRequested && _isConnected)
            {
                try
                {
                if (_stream == null) break;
                int bytesRead = await _stream.ReadAsync(buffer, 0, buffer.Length, ct).ConfigureAwait(false);
                if (bytesRead == 0) { await DisconnectAsync("Server closed connection"); break; }
                BytesReceived += bytesRead;
                var text = Encoding.UTF8.GetString(buffer, 0, bytesRead);
                // Handle multi-message frames (newline delimited)
                foreach (var line in text.Split('\n', StringSplitOptions.RemoveEmptyEntries))
                {
                    var msg = DeserializeMessage(line.Trim());
                    if (msg != null)
                    {
                    _receiveQueue.Enqueue(msg);
                    OnMessageReceived?.Invoke(msg);
                    }
                }
                }
                catch (OperationCanceledException) { break; }
                catch (IOException) { await AttemptReconnectAsync(ct).ConfigureAwait(false); }
                catch (Exception ex) { Log($"Read error: {ex.Message}"); }
            }
            }
            private async Task SendLoopAsync(CancellationToken ct)
            {
            while (!ct.IsCancellationRequested && _isConnected)
            {
                while (_sendQueue.TryDequeue(out var msg))
                {
                await SendAsync(msg, ct).ConfigureAwait(false);
                }
                await Task.Delay(50, ct).ConfigureAwait(false);
            }
            }
            private async Task HeartbeatLoopAsync(CancellationToken ct)
            {
            while (!ct.IsCancellationRequested && _isConnected)
            {
                await Task.Delay(10000, ct).ConfigureAwait(false);
                if (!_isConnected) break;
                var hb = new HeartbeatPayload { ATM_ID = _clientId, SessionId = _sessionId, TimestampUtc = DateTime.UtcNow };
                var msg = new TransportMessage { MessageType = "HEARTBEAT", Payload = Encoding.UTF8.GetBytes(SerializeHeartbeat(hb)) };
                EnqueueSend(msg);
                _lastHeartbeatUtc = DateTime.UtcNow;
            }
            }
            private async Task SendHandshakeAsync(CancellationToken ct)
            {
            var hs = new HandshakeRequest { ATM_ID = _clientId, ProtocolVersion = "EJLv5" };
            var msg = new TransportMessage { MessageType = "HANDSHAKE", Payload = Encoding.UTF8.GetBytes(SerializeHandshake(hs)) };
            await SendAsync(msg, ct).ConfigureAwait(false);
            }
            private async Task AttemptReconnectAsync(CancellationToken ct)
            {
            _isConnected = false;
            Cleanup();
            while (!ct.IsCancellationRequested && !_isConnected)
            {
                var delay = _backoff.NextDelay();
                Log($"Reconnecting in {delay.TotalSeconds:N0}s...");
                await Task.Delay(delay, ct).ConfigureAwait(false);
                await ConnectAsync(ct).ConfigureAwait(false);
            }
            }
            private static string SerializeMessage(TransportMessage msg)
            {
            return $"{msg.MessageType}|{msg.TransferId}|{msg.FileName}|{msg.ChunkIndex}|{msg.TotalChunks}|{msg.ChunkSize}|{msg.Checksum}|{msg.IsLastChunk}|{Convert.ToBase64String(msg.Payload ?? Array.Empty<byte>())}\n";
            }
            private static TransportMessage? DeserializeMessage(string line)
            {
            try
            {
                var parts = line.Split('|');
                if (parts.Length < 9) return null;
                return new TransportMessage
                {
                MessageType = parts[0],
                TransferId = parts[1],
                FileName = parts[2],
                ChunkIndex = int.TryParse(parts[3], out var ci) ? ci : 0,
                TotalChunks = int.TryParse(parts[4], out var tc) ? tc : 0,
                ChunkSize = int.TryParse(parts[5], out var cs) ? cs : 0,
                Checksum = parts[6],
                IsLastChunk = bool.TryParse(parts[7], out var lc) && lc,
                Payload = Convert.FromBase64String(parts[8])
                };
            }
            catch { return null; }
            }
            private static string SerializeHeartbeat(HeartbeatPayload hb)
            {
            return $"HB|{hb.ATM_ID}|{hb.SessionId}|{hb.TimestampUtc:O}";
            }
            private static string SerializeHandshake(HandshakeRequest hs)
            {
            return $"HS|{hs.ATM_ID}|{hs.MachineId}|{hs.ProtocolVersion}|{hs.ClientVersion}|{hs.Nonce}|{hs.TimestampUtc:O}";
            }
            private void Cleanup()
            {
            try { _tcpClient?.Close(); } catch { }
            try { _stream?.Dispose(); } catch { }
            _tcpClient = null;
            _stream = null;
            }
            private void Log(string msg)
            {
            try { OnLog?.Invoke($"[NetworkEngine] {msg}"); } catch { }
            }
            public event Action<string> OnLog;
            public event Action<Exception> OnError;
            public event Action OnConnected;
            public event Action OnDisconnected;
            public event Action<string, string[]> OnCommandReceived;
            public event Action<string>? OnLog;
            public event Action<Exception>? OnError;
            public event Action? OnConnected;
            public event Action<string>? OnDisconnected;
            public event Action<string, string>? OnSessionEstablished;
            public event Action<string> OnMessageReceived;
            public event Action<string, byte[]> OnDataReceived;
            public event Action<JournalSyncRecord> OnJournalSyncChanged;
            public event EventHandler<bool>          OnConnectionChanged;
            public event EventHandler<string>        OnSessionEstablished;
            public event Action<TransportMessage>? OnMessageReceived;
            public event EventHandler<NetworkMessage>? MessageReceived;
            public event EventHandler? Connected;
            public event EventHandler? Disconnected;
            public event EventHandler<string>? ConnectionError;
        }
